(window.OKLA_I18N_PRODUCTS=window.OKLA_I18N_PRODUCTS||{}).sk=[{"code":"OKL-001","name_cs":"Flipper Zero – kapesní multitool pro elektroniku","name_t":"Flipper Zero – vreckový multitool pre elektroniku","short_cs_text":"Flipper Zero spojuje NFC na frekvenci 13,56 MHz a RFID na 125 kHz s vlastním displejem a ovládacími tlačítky. Podporované karty lze prozkoumávat přímo na zařízení a jejich data ukládat na microSD. Rozsah čtení a emulace určuje konkrétní protokol i zabezpečení karty. Vestavěný infračervený přijímač a vysílač umožňují pracovat se signály kompatibilních dálkových ovladačů. Naučené příkazy se ukládají do souborů a následně se vybírají v nabídce přístroje. Flipper tak slouží také jako programovatelný ovladač vlastní elektroniky. Rozhraní GPIO propojuje přístroj s externími obvody a vývojovým příslušenstvím. Otevřený firmware podporuje vlastní aplikace a experimenty s elektronikou. Spolu s microSD vytváří prostor pro samostatné projekty s vlastním ovládáním, uloženými soubory a připojenými periferiemi.","short_t_text":"Flipper Zero spája NFC na frekvencii 13,56 MHz a RFID na 125 kHz s vlastným displejom a ovládacími tlačidlami. Podporované karty možno skúmať priamo na zariadení a ich dáta ukladať na microSD. Rozsah čítania a emulácie určuje konkrétny protokol aj zabezpečenie karty. Vstavaný infračervený prijímač a vysielač umožňujú pracovať so signálmi kompatibilných diaľkových ovládačov. Naučené príkazy sa ukladajú do súborov a následne sa vyberajú v ponuke prístroja. Flipper tak slúži aj ako programovateľný ovládač vlastnej elektroniky. Rozhranie GPIO prepája prístroj s externými obvodmi a vývojovým príslušenstvom. Otvorený firmvér podporuje vlastné aplikácie a experimenty s elektronikou. Spolu s microSD vytvára priestor pre samostatné projekty s vlastným ovládaním, uloženými súbormi a pripojenými perifériami.","short_t_html":"\n                            Flipper Zero spája NFC na frekvencii 13,56 MHz a RFID na 125 kHz s vlastným displejom a ovládacími tlačidlami. Podporované karty možno skúmať priamo na zariadení a ich dáta ukladať na microSD. Rozsah čítania a emulácie určuje konkrétny protokol aj zabezpečenie karty. Vstavaný infračervený prijímač a vysielač umožňujú pracovať so signálmi kompatibilných diaľkových ovládačov. Naučené príkazy sa ukladajú do súborov a následne sa vyberajú v ponuke prístroja. Flipper tak slúži aj ako programovateľný ovládač vlastnej elektroniky. Rozhranie GPIO prepája prístroj s externými obvodmi a vývojovým príslušenstvom. Otvorený firmvér podporuje vlastné aplikácie a experimenty s elektronikou. Spolu s microSD vytvára priestor pre samostatné projekty s vlastným ovládaním, uloženými súbormi a pripojenými perifériami.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Flipper Zero – vreckový multitool pre elektroniku</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>NFC a RFID vo vreckovom zariadení</h3><p>Flipper Zero spája NFC na frekvencii 13,56 MHz a RFID na 125 kHz s vlastným displejom a ovládacími tlačidlami. Podporované karty možno skúmať priamo na zariadení a ich dáta ukladať na microSD. Rozsah čítania a emulácie určuje konkrétny protokol aj zabezpečenie karty.</p><p style=\"margin-top:16px\">Obe technológie používajú odlišné frekvencie a pracujú s rôznymi typmi identifikátorov. Samostatné ponuky sprístupňujú zodpovedajúce funkcie podľa zvoleného rozhrania. Displej zobrazuje dostupné údaje a fyzické tlačidlá umožňujú vyberať uložené položky bez pripojeného počítača. Pamäťová karta uchováva súbory na ďalšiu prácu.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-001-function-1.jpg\" alt=\"Flipper Zero – vreckový multitool pre elektroniku – NFC a RFID vo vreckovom zariadení\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Ilustračné zobrazenie funkcie</figcaption></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Infračervené ovládanie</h3><p>Vstavaný infračervený prijímač a vysielač umožňujú pracovať so signálmi kompatibilných diaľkových ovládačov. Naučené príkazy sa ukladajú do súborov a následne sa vyberajú v ponuke prístroja. Flipper tak slúži aj ako programovateľný ovládač vlastnej elektroniky.</p><p style=\"margin-top:16px\">Infračervený prenos pracuje so svetelnými impulzmi, ktoré prijíma ovládaný spotrebič. Uložené príkazy možno usporiadať podľa jednotlivých ovládačov a znova vyvolať z ponuky. Prijímacia aj vysielacia časť sú integrované v prístroji, takže zachytenie podporovaného povelu a jeho následné odoslanie využíva to isté zariadenie.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-001-function-2.jpg\" alt=\"Flipper Zero – vreckový multitool pre elektroniku – Infračervené ovládanie\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Ilustračné zobrazenie funkcie</figcaption></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>GPIO a otvorený firmvér</h3><p>Rozhranie GPIO prepája prístroj s externými obvodmi a vývojovým príslušenstvom. Otvorený firmvér podporuje vlastné aplikácie a experimenty s elektronikou. Spolu s microSD vytvára priestor pre samostatné projekty s vlastným ovládaním, uloženými súbormi a pripojenými perifériami.</p><p style=\"margin-top:16px\">Pripojený obvod môže rozšíriť funkcie podľa svojho zapojenia a programovej podpory. GPIO prenáša elektrické signály medzi prístrojom a perifériou, zatiaľ čo firmvér určuje ich spracovanie. Vlastné aplikácie tak môžu spájať vstupy z externej elektroniky s informáciami na displeji a ovládaním cez tlačidlá.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-001-function-3.jpg\" alt=\"Flipper Zero – vreckový multitool pre elektroniku – GPIO a otvorený firmvér\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Ilustračné zobrazenie funkcie</figcaption></figure></section></article>\n                            ","params":[["Kategorie","Elektronické multitooly","Kategória","Elektronické multitooly"],["Výrobce","Flipper Devices","Výrobca","Flipper Devices"],["Kategorie","Elektronické multitooly","Kategória","Elektronické multitooly"],["Model","Flipper Zero","Model","Flipper Zero"],["Typ zařízení","Kapesní elektronický multitool","Typ zariadenia","Vreckový elektronický multitool"],["Ovládání","Displej a fyzická tlačítka","Ovládanie","Displej a fyzické tlačidlá"],["Infračervené rozhraní","Ano","Infračervené rozhranie","Áno"],["NFC","13,56 MHz, podporované protokoly","NFC","13,56 MHz, podporované protokoly"],["RFID","125 kHz, podporované protokoly","RFID","125 kHz, podporované protokoly"],["Rozšíření","GPIO","Rozšírenie","GPIO"],["Paměťová karta","microSD","Pamäťová karta","microSD"],["Software","Otevřený firmware","Softvér","Otvorený firmvér"]],"catalog_names":{"Kapesní multitool Flipper Zero":"Vreckový multitool Flipper Zero","Flipper Zero – kapesní multitool pro elektroniku":"Flipper Zero – vreckový multitool pre elektroniku"},"catalog_short_cs":"Poznejte elektroniku, kterou běžně používáte, z jiné strany. Flipper Zero spojuje práci s podporovanými rádiovými protokoly, NFC, RFID a infračerveným ovládáním v malém přístroji s vlastním displejem. Hodí se pro výuku, vývoj i testování vašeho vybavení. Nabídku ovládáte přímo na zařízení a vlastní projekty můžete rozšiřovat prostřednictvím GPIO. Otevřený firmware a dokumentace dávají prostor postupovat od hotových funkcí k vlastnímu programu, doma u stolu i při praktických pokusech. Dálkový ovladač, přístupový čip a NFC karta používají různé způsoby komunikace. Flipper Zero vám pomůže podporované systémy prozkoumat a pochopit rozdíly mezi nimi.","catalog_short_t":"Spoznajte elektroniku, ktorú bežne používate, z inej stránky. Flipper Zero spája prácu s podporovanými rádiovými protokolmi, NFC, RFID a infračerveným ovládaním v malom prístroji s vlastným displejom. Hodí sa na výučbu, vývoj aj testovanie vášho vybavenia. Ponuku ovládate priamo na zariadení a vlastné projekty môžete rozširovať prostredníctvom GPIO. Otvorený firmvér a dokumentácia dávajú priestor postupovať od hotových funkcií k vlastnému programu, doma pri stole aj pri praktických pokusoch. Diaľkový ovládač, prístupový čip a NFC karta používajú rôzne spôsoby komunikácie. Flipper Zero vám pomôže podporované systémy preskúmať a pochopiť rozdiely medzi nimi."},{"code":"OKL-002","name_cs":"LILYGO T-Embed CC1101 – vývojová platforma ESP32-S3","name_t":"LILYGO T-Embed CC1101 – vývojová platforma ESP32-S3","short_cs_text":"Dvoujádrový ESP32-S3 pracuje s taktem až 240 MHz. Deska má 16 MB flash a 8 MB PSRAM pro vlastní firmware, grafické rozhraní a zpracování dat. Wi-Fi a Bluetooth LE doplňují připojení potřebné pro síťové a mobilní projekty. IPS displej s úhlopříčkou 1,9 palce má rozlišení 320 × 170 pixelů. Otočný enkodér s tlačítkem slouží k procházení nabídek a změně hodnot. Displej i ovládací prvek jsou součástí jednoho kompaktního těla, takže základní uživatelské rozhraní nevyžaduje další panel. Rádiový modul CC1101 doplňuje NFC rozhraní PN532 a infračervená komunikace. Zařízení tvoří programovatelný základ pro různé bezdrátové experimenty. Dostupné funkce a podporované protokoly závisí na nahraném firmwaru a konkrétním osazení platformy.","short_t_text":"Dvojjadrový ESP32-S3 pracuje s taktom až 240 MHz. Doska má 16 MB flash a 8 MB PSRAM pre vlastný firmvér, grafické rozhranie a spracovanie dát. Wi-Fi a Bluetooth LE dopĺňajú pripojenie potrebné pre sieťové a mobilné projekty. IPS displej s uhlopriečkou 1,9 palca má rozlíšenie 320 × 170 pixelov. Otočný enkodér s tlačidlom slúži na prechádzanie ponúk a zmenu hodnôt. Displej aj ovládací prvok sú súčasťou jedného kompaktného tela, takže základné používateľské rozhranie nevyžaduje ďalší panel. Rádiový modul CC1101 dopĺňajú NFC rozhranie PN532 a infračervená komunikácia. Zariadenie tvorí programovateľný základ pre rôzne bezdrôtové experimenty. Dostupné funkcie a podporované protokoly závisia od nahraného firmvéru a konkrétneho osadenia platformy.","short_t_html":"\n                            Dvojjadrový ESP32-S3 pracuje s taktom až 240 MHz. Doska má 16 MB flash a 8 MB PSRAM pre vlastný firmvér, grafické rozhranie a spracovanie dát. Wi-Fi a Bluetooth LE dopĺňajú pripojenie potrebné pre sieťové a mobilné projekty. IPS displej s uhlopriečkou 1,9 palca má rozlíšenie 320 × 170 pixelov. Otočný enkodér s tlačidlom slúži na prechádzanie ponúk a zmenu hodnôt. Displej aj ovládací prvok sú súčasťou jedného kompaktného tela, takže základné používateľské rozhranie nevyžaduje ďalší panel. Rádiový modul CC1101 dopĺňajú NFC rozhranie PN532 a infračervená komunikácia. Zariadenie tvorí programovateľný základ pre rôzne bezdrôtové experimenty. Dostupné funkcie a podporované protokoly závisia od nahraného firmvéru a konkrétneho osadenia platformy.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>LILYGO T-Embed CC1101 – vývojová platforma ESP32-S3</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Procesor ESP32-S3</h3><p>Dvojjadrový ESP32-S3 pracuje s taktom až 240 MHz. Doska má 16 MB flash a 8 MB PSRAM pre vlastný firmvér, grafické rozhranie a spracovanie dát. Wi-Fi a Bluetooth LE dopĺňajú pripojenie potrebné pre sieťové a mobilné projekty.</p><p style=\"margin-top:16px\">Flash slúži na uloženie programu a jeho dát, zatiaľ čo PSRAM rozširuje pracovnú pamäť dostupnú aplikácii. Toto rozdelenie je využiteľné pri práci s obrazovkami, ponukami aj komunikačnými úlohami. Integrované bezdrôtové rozhranie umožňuje prepojiť lokálne ovládanie platformy s dátami z kompatibilnej siete alebo zariadenia.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-002-function-1.jpg\" alt=\"LILYGO T-Embed CC1101 – vývojová platforma ESP32-S3 – Procesor ESP32-S3\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Farebný displej a otočný ovládač</h3><p>IPS displej s uhlopriečkou 1,9 palca má rozlíšenie 320 × 170 pixelov. Otočný enkodér s tlačidlom slúži na prechádzanie ponúk a zmenu hodnôt. Displej aj ovládací prvok sú súčasťou jedného kompaktného tela, takže základné používateľské rozhranie nevyžaduje ďalší panel.</p><p style=\"margin-top:16px\">Široký formát obrazovky poskytuje priestor pre stavové údaje, ikony a prehľadné ponuky. Otáčanie enkodéra a stlačenie jeho tlačidla predstavujú dva rôzne vstupy pre program. Firmvér im môže priradiť posun medzi položkami, úpravu nastavení alebo potvrdenie voľby bez toho, aby bolo nutné pripájať klávesnicu.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-002-function-2.jpg\" alt=\"LILYGO T-Embed CC1101 – vývojová platforma ESP32-S3 – Farebný displej a otočný ovládač\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>CC1101, NFC a infračervené rozhranie</h3><p>Rádiový modul CC1101 dopĺňajú NFC rozhranie PN532 a infračervená komunikácia. Zariadenie tvorí programovateľný základ pre rôzne bezdrôtové experimenty. Dostupné funkcie a podporované protokoly závisia od nahraného firmvéru a konkrétneho osadenia platformy.</p><p style=\"margin-top:16px\">Jednotlivé komunikačné časti predstavujú rôzne rozhrania s vlastnými možnosťami a obmedzeniami. Rádiový modul spracúva podporovanú rádiovú komunikáciu, PN532 slúži na NFC a infračervená časť na optický prenos. Program môže ich obsluhu spojiť s obrazovkou a ovládačom do spoločného používateľského rozhrania.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-002-function-3.jpg\" alt=\"LILYGO T-Embed CC1101 – vývojová platforma ESP32-S3 – CC1101, NFC a infračervené rozhranie\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie","Elektronické multitooly","Kategória","Elektronické multitooly"],["Výrobce","LILYGO","Výrobca","LILYGO"],["Kategorie","Elektronické multitooly","Kategória","Elektronické multitooly"],["Model","LILYGO T Embed CC1101 ESP32 S3","Model","LILYGO T Embed CC1101 ESP32 S3"],["Displej","1,9″ IPS TFT, ST7789V","Displej","1,9″ IPS TFT, ST7789V"],["Procesor","ESP32-S3, dvoujádrový LX7","Procesor","ESP32-S3, dvojjadrový LX7"],["Takt procesoru","Až 240 MHz","Takt procesora","Až 240 MHz"],["Flash","16 MB","Flash","16 MB"],["PSRAM","8 MB","PSRAM","8 MB"],["Rozlišení displeje","320 × 170 px","Rozlíšenie displeja","320 × 170 px"],["Wi-Fi","2,4 GHz, 802.11 b/g/n","Wi-Fi","2,4 GHz, 802.11 b/g/n"],["Bluetooth","5.0 LE","Bluetooth","5.0 LE"],["Rádiový modul","CC1101","Rádiový modul","CC1101"],["NFC modul","PN532","NFC modul","PN532"],["Připojení","USB-C","Pripojenie","USB-C"],["Ovládání","Otočný enkodér","Ovládanie","Otočný enkodér"],["Paměťová karta","TF / microSD","Pamäťová karta","TF / microSD"]],"catalog_names":{"Multifunkční vývojová platforma LILYGO T Embed CC1101 ESP32 S3":"Multifunkčná vývojová platforma LILYGO T Embed CC1101 ESP32 S3","LILYGO T-Embed CC1101 – vývojová platforma ESP32-S3":"LILYGO T-Embed CC1101 – vývojová platforma ESP32-S3"},"catalog_short_cs":"Postavte vlastní ovládací panel, bezdrátový experiment nebo rozhraní pro chytrou elektroniku. LILYGO T-Embed CC1101 propojuje procesor ESP32-S3, rádiový modul CC1101, barevný displej a otočný ovladač v kompaktní vývojové platformě. Místo skládání základních částí z několika desek získáte přehledný základ pro vlastní firmware. Hodnoty, nabídky a stav programu můžete sledovat přímo na zařízení. Praktické řešení pro výuku, rychlé prototypy i aplikace, jejichž ovládání chcete mít po ruce. Dvoujádrový procesor tvoří základ pro ovládací rozhraní, vyhodnocování vstupů a komunikaci. Platformu lze programovat pomocí běžných nástrojů pro ESP32 a začít na ukázkách výrobce.","catalog_short_t":"Postavte si vlastný ovládací panel, bezdrôtový experiment alebo rozhranie pre inteligentnú elektroniku. LILYGO T-Embed CC1101 prepája procesor ESP32-S3, rádiový modul CC1101, farebný displej a otočný ovládač v kompaktnej vývojovej platforme. Namiesto skladania základných častí z niekoľkých dosiek získate prehľadný základ pre vlastný firmvér. Hodnoty, ponuky a stav programu môžete sledovať priamo na zariadení. Praktické riešenie na výučbu, rýchle prototypy aj aplikácie, ktorých ovládanie chcete mať poruke. Dvojjadrový procesor tvorí základ pre ovládacie rozhranie, vyhodnocovanie vstupov a komunikáciu. Platformu možno programovať pomocou bežných nástrojov pre ESP32 a začať na ukážkach výrobcu."},{"code":"OKL-003","name_cs":"LILYGO T-Deck Plus – kapesní komunikátor ESP32","name_t":"LILYGO T-Deck Plus – vreckový komunikátor ESP32","short_cs_text":"T-Deck Plus má vlastní klávesnici pro zadávání textu, příkazů a hodnot. Trackball doplňuje ovládání nabídky a pohyb v rozhraní. Vstupní prvky lze použít ve vlastním firmwaru pro přenosný terminál, komunikátor nebo ovládací panel. Barevný panel s rozlišením 320 × 240 pixelů zobrazuje text, aktuální hodnoty i jednoduchou grafiku. Dotykové ovládání lze kombinovat s klávesnicí a trackballem. Procesor ESP32-S3 poskytuje základ pro vlastní aplikace i bezdrátové připojení. Verze Plus zahrnuje GPS a vestavěnou baterii pro přenosné projekty. Polohové údaje může vlastní program spojit s informacemi na displeji. Rozhraní a dostupné piny vycházejí ze zapojení verze Plus; GPS v této variantě využívá piny konektoru Grove.","short_t_text":"T-Deck Plus má vlastnú klávesnicu na zadávanie textu, príkazov a hodnôt. Trackball dopĺňa ovládanie ponuky a pohyb v rozhraní. Vstupné prvky možno použiť vo vlastnom firmvéri pre prenosný terminál, komunikátor alebo ovládací panel. Farebný panel s rozlíšením 320 × 240 pixelov zobrazuje text, aktuálne hodnoty aj jednoduchú grafiku. Dotykové ovládanie možno kombinovať s klávesnicou a trackballom. Procesor ESP32-S3 poskytuje základ pre vlastné aplikácie aj bezdrôtové pripojenie. Verzia Plus zahŕňa GPS a vstavanú batériu pre prenosné projekty. Polohové údaje môže vlastný program spojiť s informáciami na displeji. Rozhranie a dostupné piny vychádzajú zo zapojenia verzie Plus; GPS v tomto variante využíva piny konektora Grove.","short_t_html":"\n                            T-Deck Plus má vlastnú klávesnicu na zadávanie textu, príkazov a hodnôt. Trackball dopĺňa ovládanie ponuky a pohyb v rozhraní. Vstupné prvky možno použiť vo vlastnom firmvéri pre prenosný terminál, komunikátor alebo ovládací panel. Farebný panel s rozlíšením 320 × 240 pixelov zobrazuje text, aktuálne hodnoty aj jednoduchú grafiku. Dotykové ovládanie možno kombinovať s klávesnicou a trackballom. Procesor ESP32-S3 poskytuje základ pre vlastné aplikácie aj bezdrôtové pripojenie. Verzia Plus zahŕňa GPS a vstavanú batériu pre prenosné projekty. Polohové údaje môže vlastný program spojiť s informáciami na displeji. Rozhranie a dostupné piny vychádzajú zo zapojenia verzie Plus; GPS v tomto variante využíva piny konektora Grove.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>LILYGO T-Deck Plus – vreckový komunikátor ESP32</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Fyzická klávesnica a trackball</h3><p>T-Deck Plus má vlastnú klávesnicu na zadávanie textu, príkazov a hodnôt. Trackball dopĺňa ovládanie ponuky a pohyb v rozhraní. Vstupné prvky možno použiť vo vlastnom firmvéri pre prenosný terminál, komunikátor alebo ovládací panel.</p><p style=\"margin-top:16px\">Samostatné klávesy umožňujú priame zadávanie znakov bez softvérovej klávesnice cez celú obrazovku. Displej tak zostáva dostupný pre obsah aplikácie. Trackball poskytuje ďalší vstup, ktorého funkciu určuje program, a dopĺňa textové zadávanie o pohyb medzi položkami alebo prácu s kurzorom.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-003-function-1.jpg\" alt=\"LILYGO T-Deck Plus – vreckový komunikátor ESP32 – Fyzická klávesnica a trackball\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Dotykový displej 2,8 palca</h3><p>Farebný panel s rozlíšením 320 × 240 pixelov zobrazuje text, aktuálne hodnoty aj jednoduchú grafiku. Dotykové ovládanie možno kombinovať s klávesnicou a trackballom. Procesor ESP32-S3 poskytuje základ pre vlastné aplikácie aj bezdrôtové pripojenie.</p><p style=\"margin-top:16px\">Rozlíšenie panela určuje priestor pre grafické prvky aplikácie a vykresľovaný text. Dotyková vrstva poskytuje priamy vstup z plochy obrazovky, fyzická klávesnica zasa zachováva samostatnú cestu na písanie. Vlastné rozhranie môže tieto spôsoby ovládania kombinovať podľa charakteru zobrazovaných dát.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-003-function-2.jpg\" alt=\"LILYGO T-Deck Plus – vreckový komunikátor ESP32 – Dotykový displej 2,8 palca\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>GPS a vstavaná batéria</h3><p>Verzia Plus zahŕňa GPS a vstavanú batériu pre prenosné projekty. Polohové údaje môže vlastný program spojiť s informáciami na displeji. Rozhranie a dostupné piny vychádzajú zo zapojenia verzie Plus; GPS v tomto variante využíva piny konektora Grove.</p><p style=\"margin-top:16px\">GPS dodáva aplikácii polohové údaje, zatiaľ čo batéria umožňuje používať zariadenie bez trvalo pripojeného napájacieho kábla. Zobrazenie polohy aj jej ďalšie využitie zabezpečuje nahraný softvér. Zdieľanie pinov v tejto verzii je súčasťou hardvérového zapojenia a ovplyvňuje možnosti súčasného pripojenia ďalších periférií.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-003-function-3.jpg\" alt=\"LILYGO T-Deck Plus – vreckový komunikátor ESP32 – GPS a vstavaná batéria\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie","Elektronické multitooly","Kategória","Elektronické multitooly"],["Výrobce","LILYGO","Výrobca","LILYGO"],["Kategorie","Elektronické multitooly","Kategória","Elektronické multitooly"],["Model","LILYGO T Deck Plus","Model","LILYGO T Deck Plus"],["Displej","2,8″ LCD, ST7789","Displej","2,8″ LCD, ST7789"],["Procesor","ESP32-S3","Procesor","ESP32-S3"],["Flash","16 MB","Flash","16 MB"],["PSRAM","8 MB","PSRAM","8 MB"],["Rozlišení displeje","320 × 240 px","Rozlíšenie displeja","320 × 240 px"],["Dotykové ovládání","Kapacitní, GT911","Dotykové ovládanie","Kapacitné, GT911"],["Další ovládání","Fyzická klávesnice a trackball","Ďalšie ovládanie","Fyzická klávesnica a trackball"],["GPS modul","MIA-M10Q","GPS modul","MIA-M10Q"],["Bluetooth","5.0 LE","Bluetooth","5.0 LE"],["Wi-Fi","2,4 GHz","Wi-Fi","2,4 GHz"],["Připojení","USB-C","Pripojenie","USB-C"],["Paměťová karta","TF / microSD","Pamäťová karta","TF / microSD"],["Baterie","2000 mAh","Batéria","2000 mAh"]],"catalog_names":{"Kapesní ESP32 komunikátor LILYGO T Deck Plus":"Vreckový ESP32 komunikátor LILYGO T Deck Plus","LILYGO T-Deck Plus – kapesní komunikátor ESP32":"LILYGO T-Deck Plus – vreckový komunikátor ESP32"},"catalog_short_cs":"Vytvořte vlastní přenosný terminál, datový panel nebo IoT rozhraní s pohodlnějším zadáváním. LILYGO T-Deck Plus kombinuje platformu ESP32-S3 s fyzickou klávesnicí, dotykovým displejem a trackballem. Text, stav aplikace a její ovládání tak máte přímo na zařízení bez trvale připojeného počítače. GPS přidává možnosti práce s polohovými daty a vestavěná baterie podporuje přenosné projekty. Konkrétní bezdrátové funkce závisejí na variantě a nahraném firmwaru. Krátký text, příkaz nebo změna nastavení se zadávají přehledněji na fyzické klávesnici než několika tlačítky. T-Deck Plus proto dává smysl při návrhu vlastních terminálů a ovládacích rozhraní.","catalog_short_t":"Vytvorte si vlastný prenosný terminál, dátový panel alebo IoT rozhranie s pohodlnejším zadávaním. LILYGO T-Deck Plus kombinuje platformu ESP32-S3 s fyzickou klávesnicou, dotykovým displejom a trackballom. Text, stav aplikácie a jej ovládanie tak máte priamo na zariadení bez trvalo pripojeného počítača. GPS pridáva možnosti práce s polohovými dátami a vstavaná batéria podporuje prenosné projekty. Konkrétne bezdrôtové funkcie závisia od variantu a nahraného firmvéru. Krátky text, príkaz alebo zmena nastavenia sa zadávajú prehľadnejšie na fyzickej klávesnici ako niekoľkými tlačidlami. T-Deck Plus preto dáva zmysel pri návrhu vlastných terminálov a ovládacích rozhraní."},{"code":"OKL-004","name_cs":"M5Stack Cardputer ADV – mini počítač s klávesnicí","name_t":"M5Stack Cardputer ADV – mini počítač s klávesnicou","short_cs_text":"Cardputer ADV staví na procesoru ESP32-S3 a modulu Stamp-S3A. Klávesnice, displej a napájení jsou integrovány do malého zařízení pro vlastní embedded aplikace. Platforma podporuje programování prostřednictvím nástrojů výrobce včetně Arduino a UiFlow2. Klávesnice s 56 tlačítky doplňuje barevný 1,14palcový displej s rozlišením 240 × 135 pixelů. Audio kodek, mikrofon a reproduktor rozšiřují aplikace o záznam a zvukovou odezvu. Vstupy a výstupy jsou dostupné v jednom přenosném celku. Grove, rozšiřující sběrnice a microSD propojují Cardputer ADV s příslušenstvím a soubory. Připojené moduly mohou poskytovat data pro zobrazení nebo další zpracování. Boční konektory zůstávají přístupné i při používání klávesnice a displeje.","short_t_text":"Cardputer ADV stavia na procesore ESP32-S3 a module Stamp-S3A. Klávesnica, displej a napájanie sú integrované do malého zariadenia pre vlastné embedded aplikácie. Platforma podporuje programovanie prostredníctvom nástrojov výrobcu vrátane Arduino a UiFlow2. Klávesnica s 56 tlačidlami dopĺňa farebný 1,14-palcový displej s rozlíšením 240 × 135 pixelov. Audio kodek, mikrofón a reproduktor rozširujú aplikácie o záznam a zvukovú odozvu. Vstupy a výstupy sú dostupné v jednom prenosnom celku. Grove, rozširujúca zbernica a microSD prepájajú Cardputer ADV s príslušenstvom a súbormi. Pripojené moduly môžu poskytovať dáta na zobrazenie alebo ďalšie spracovanie. Bočné konektory zostávajú prístupné aj pri používaní klávesnice a displeja.","short_t_html":"\n                            Cardputer ADV stavia na procesore ESP32-S3 a module Stamp-S3A. Klávesnica, displej a napájanie sú integrované do malého zariadenia pre vlastné embedded aplikácie. Platforma podporuje programovanie prostredníctvom nástrojov výrobcu vrátane Arduino a UiFlow2. Klávesnica s 56 tlačidlami dopĺňa farebný 1,14-palcový displej s rozlíšením 240 × 135 pixelov. Audio kodek, mikrofón a reproduktor rozširujú aplikácie o záznam a zvukovú odozvu. Vstupy a výstupy sú dostupné v jednom prenosnom celku. Grove, rozširujúca zbernica a microSD prepájajú Cardputer ADV s príslušenstvom a súbormi. Pripojené moduly môžu poskytovať dáta na zobrazenie alebo ďalšie spracovanie. Bočné konektory zostávajú prístupné aj pri používaní klávesnice a displeja.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>M5Stack Cardputer ADV – mini počítač s klávesnicou</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>ESP32-S3 v samostatnom mini počítači</h3><p>Cardputer ADV stavia na procesore ESP32-S3 a module Stamp-S3A. Klávesnica, displej a napájanie sú integrované do malého zariadenia pre vlastné embedded aplikácie. Platforma podporuje programovanie prostredníctvom nástrojov výrobcu vrátane Arduino a UiFlow2.</p><p style=\"margin-top:16px\">Vlastný program môže prijímať text z klávesnice, spracovať ho a zobraziť výsledok na vstavanom paneli. Bezdrôtové možnosti ESP32-S3 rozširujú tento základ o komunikáciu s podporovanými zariadeniami. Integrované vyhotovenie prepája výpočtovú časť a používateľské vstupy bez nutnosti zostavovať celý ovládací panel z oddelených dielov.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-004-function-1.jpg\" alt=\"M5Stack Cardputer ADV – mini počítač s klávesnicou – ESP32-S3 v samostatnom mini počítači\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Klávesnica, obraz a zvuk</h3><p>Klávesnica s 56 tlačidlami dopĺňa farebný 1,14-palcový displej s rozlíšením 240 × 135 pixelov. Audio kodek, mikrofón a reproduktor rozširujú aplikácie o záznam a zvukovú odozvu. Vstupy a výstupy sú dostupné v jednom prenosnom celku.</p><p style=\"margin-top:16px\">Displej slúži na krátke texty, ponuky a stavové informácie. Mikrofón tvorí zvukový vstup, reproduktor naopak výstup pre podporovanú aplikáciu. Ich zapojenie cez audio časť umožňuje pracovať so zvukom ako s ďalšou zložkou programu popri obrazovom výstupe a fyzických klávesoch.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-004-function-2.jpg\" alt=\"M5Stack Cardputer ADV – mini počítač s klávesnicou – Klávesnica, obraz a zvuk\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Konektory a rozšírenia</h3><p>Grove, rozširujúca zbernica a microSD prepájajú Cardputer ADV s príslušenstvom a súbormi. Pripojené moduly môžu poskytovať dáta na zobrazenie alebo ďalšie spracovanie. Bočné konektory zostávajú prístupné aj pri používaní klávesnice a displeja.</p><p style=\"margin-top:16px\">Pamäťová karta poskytuje súborové úložisko oddelené od samotného programu. Pripojené príslušenstvo môže dopĺňať vstupné údaje alebo rozširovať výstupy podľa zapojenia a softvérovej podpory. Kombinácia konektorov, klávesnice a obrazovky dáva projektu vlastné ovládacie rozhranie aj pri použití externých elektronických modulov.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-004-function-3.jpg\" alt=\"M5Stack Cardputer ADV – mini počítač s klávesnicou – Konektory a rozšírenia\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie","Elektronické multitooly","Kategória","Elektronické multitooly"],["Výrobce","M5Stack","Výrobca","M5Stack"],["Kategorie","Elektronické multitooly","Kategória","Elektronické multitooly"],["Model","M5Stack Cardputer ADV","Model","M5Stack Cardputer ADV"],["Klávesnice","56 kláves, 4 × 14","Klávesnica","56 klávesov, 4 × 14"],["Displej","1,14″ LCD, ST7789V2","Displej","1,14″ LCD, ST7789V2"],["Procesor","ESP32-S3FN8, Stamp-S3A","Procesor","ESP32-S3FN8, Stamp-S3A"],["Takt procesoru","Až 240 MHz","Takt procesora","Až 240 MHz"],["Flash","8 MB","Flash","8 MB"],["Rozlišení displeje","240 × 135 px","Rozlíšenie displeja","240 × 135 px"],["Paměťová karta","microSD","Pamäťová karta","microSD"],["Audio kodek","ES8311","Audio kodek","ES8311"],["Pohybový senzor","BMI270, 6 os","Pohybový senzor","BMI270, 6 osí"],["Rozšíření","Grove HY2.0-4P a EXT 2.54-14P","Rozšírenie","Grove HY2.0-4P a EXT 2.54-14P"],["Infračervené rozhraní","Vysílač","Infračervené rozhranie","Vysielač"],["Vývojová prostředí","Arduino, UiFlow2, ESP-IDF, PlatformIO","Vývojové prostredia","Arduino, UiFlow2, ESP-IDF, PlatformIO"]],"catalog_names":{"Programovatelný mini počítač M5Stack Cardputer ADV":"Programovateľný mini počítač M5Stack Cardputer ADV","M5Stack Cardputer ADV – mini počítač s klávesnicí":"M5Stack Cardputer ADV – mini počítač s klávesnicou"},"catalog_short_cs":"Malé zařízení pro velký prostor vlastním nápadům. M5Stack Cardputer ADV spojuje platformu ESP32-S3, barevný displej a 56klávesovou klávesnici v přenosném vývojovém počítači. Hodí se pro vlastní terminály, jednoduché ovládací aplikace a experimenty s elektronikou. Vstup i výstup máte přímo na zařízení, takže nemusíte každou akci zadávat z notebooku. Rozšiřující rozhraní, zvukové prvky a microSD pak umožňují postupně rozvíjet program podle potřeb projektu. Cardputer ADV se hodí tam, kde chcete samostatné rozhraní s možností psát text. Procesor ESP32-S3 tvoří základ vlastního programu a klávesnice usnadňuje zadávání příkazů nebo hodnot.","catalog_short_t":"Malé zariadenie, ktoré dáva veľký priestor vlastným nápadom. M5Stack Cardputer ADV spája platformu ESP32-S3, farebný displej a 56-klávesovú klávesnicu v prenosnom vývojovom počítači. Hodí sa na vlastné terminály, jednoduché ovládacie aplikácie a experimenty s elektronikou. Vstup aj výstup máte priamo na zariadení, takže nemusíte každú akciu zadávať z notebooku. Rozširujúce rozhrania, zvukové prvky a microSD potom umožňujú postupne rozvíjať program podľa potrieb projektu. Cardputer ADV sa hodí tam, kde chcete samostatné rozhranie s možnosťou písať text. Procesor ESP32-S3 tvorí základ vlastného programu a klávesnica uľahčuje zadávanie príkazov alebo hodnôt."},{"code":"OKL-005","name_cs":"Vývojová sada ESP32 pro IoT projekty","name_t":"Vývojová sada ESP32 pre IoT projekty","short_cs_text":"Základem sady je vývojová deska ESP32 s bezdrátovou komunikací. Vlastní program zpracovává vstupy a ovládá připojené prvky. Deska umožňuje spojit elektronické zapojení s komunikací přes Wi-Fi nebo Bluetooth. Sada sdružuje vývojovou desku, propojovací vodiče a elektronické prvky pro sestavování výukových obvodů. Nepájivé pole umožňuje měnit zapojení bez trvalého pájeného spoje. Jednotlivé součásti vytvářejí základ pro práci s digitálními vstupy, výstupy a periferiemi. Desku lze kombinovat s kompatibilními senzory, indikačními prvky a dalšími moduly. Program určuje reakce obvodu a podobu získaných dat. Zapojení se může měnit mezi jednotlivými projekty a stejný základ tak poslouží při výuce elektroniky i návrhu IoT prototypu.","short_t_text":"Základom sady je vývojová doska ESP32 s bezdrôtovou komunikáciou. Vlastný program spracúva vstupy a ovláda pripojené prvky. Doska umožňuje spojiť elektronické zapojenie s komunikáciou cez Wi-Fi alebo Bluetooth. Sada združuje vývojovú dosku, prepojovacie vodiče a elektronické prvky na zostavovanie výučbových obvodov. Nepájivé pole umožňuje meniť zapojenie bez trvalého spájkovaného spoja. Jednotlivé súčasti vytvárajú základ pre prácu s digitálnymi vstupmi, výstupmi a perifériami. Dosku možno kombinovať s kompatibilnými senzormi, indikačnými prvkami a ďalšími modulmi. Program určuje reakcie obvodu a podobu získaných dát. Zapojenie sa môže meniť medzi jednotlivými projektmi, a tak rovnaký základ poslúži pri výučbe elektroniky aj pri návrhu IoT prototypu.","short_t_html":"\n                            Základom sady je vývojová doska ESP32 s bezdrôtovou komunikáciou. Vlastný program spracúva vstupy a ovláda pripojené prvky. Doska umožňuje spojiť elektronické zapojenie s komunikáciou cez Wi-Fi alebo Bluetooth. Sada združuje vývojovú dosku, prepojovacie vodiče a elektronické prvky na zostavovanie výučbových obvodov. Nepájivé pole umožňuje meniť zapojenie bez trvalého spájkovaného spoja. Jednotlivé súčasti vytvárajú základ pre prácu s digitálnymi vstupmi, výstupmi a perifériami. Dosku možno kombinovať s kompatibilnými senzormi, indikačnými prvkami a ďalšími modulmi. Program určuje reakcie obvodu a podobu získaných dát. Zapojenie sa môže meniť medzi jednotlivými projektmi, a tak rovnaký základ poslúži pri výučbe elektroniky aj pri návrhu IoT prototypu.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Vývojová sada ESP32 pre IoT projekty</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Programovateľná doska ESP32</h3><p>Základom sady je vývojová doska ESP32 s bezdrôtovou komunikáciou. Vlastný program spracúva vstupy a ovláda pripojené prvky. Doska umožňuje spojiť elektronické zapojenie s komunikáciou cez Wi-Fi alebo Bluetooth.</p><p style=\"margin-top:16px\">Riadiaci program prepája stav vstupných pinov s požadovanou reakciou výstupov. Bezdrôtová časť môže odovzdávať dáta ďalšiemu zariadeniu alebo prijímať podporované povely. Jeden projekt tak môže zahŕňať miestne elektronické zapojenie aj sieťovú komunikáciu, pričom výsledné správanie určuje zvolený firmvér.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-005-function-1.jpg\" alt=\"Vývojová sada ESP32 pre IoT projekty – Programovateľná doska ESP32\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Súčiastky na praktické experimenty</h3><p>Sada združuje vývojovú dosku, prepojovacie vodiče a elektronické prvky na zostavovanie výučbových obvodov. Nepájivé pole umožňuje meniť zapojenie bez trvalého spájkovaného spoja. Jednotlivé súčasti vytvárajú základ pre prácu s digitálnymi vstupmi, výstupmi a perifériami.</p><p style=\"margin-top:16px\">Kontaktné pole prepája zasunuté vývody a vodiče prostredníctvom vnútorných vodivých spojov. Zapojenie je rozoberateľné a jednotlivé časti možno presúvať medzi pokusmi. Vodiče vytvárajú prepojenie medzi doskou a obvodom, zatiaľ čo konkrétne elektronické prvky určujú, akú funkciu zostavený celok plní.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-005-function-2.jpg\" alt=\"Vývojová sada ESP32 pre IoT projekty – Súčiastky na praktické experimenty\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Modulárna konštrukcia projektov</h3><p>Dosku možno kombinovať s kompatibilnými senzormi, indikačnými prvkami a ďalšími modulmi. Program určuje reakcie obvodu a podobu získaných dát. Zapojenie sa môže meniť medzi jednotlivými projektmi, a tak rovnaký základ poslúži pri výučbe elektroniky aj pri návrhu IoT prototypu.</p><p style=\"margin-top:16px\">Modulárny prístup umožňuje rozvíjať projekt postupne od jednoduchého zapojenia k zostave s viacerými vstupmi a výstupmi. Program môže spájať namerané údaje, signalizáciu a prenos dát v jednom behu. Rozsah projektu vychádza z pripojených súčastí, ich elektrickej kompatibility a dostupných prostriedkov dosky.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-005-function-3.jpg\" alt=\"Vývojová sada ESP32 pre IoT projekty – Modulárna konštrukcia projektov\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie","Elektronické multitooly","Kategória","Elektronické multitooly"],["Kategorie","Elektronické multitooly","Kategória","Elektronické multitooly"],["Typ produktu","Vývojová sada","Typ produktu","Vývojová sada"],["Platforma","ESP32","Platforma","ESP32"],["Určení","Výuka elektroniky a programování","Určenie","Výučba elektroniky a programovania"],["Způsob použití","Vlastní firmware a zapojení","Spôsob použitia","Vlastný firmvér a zapojenie"],["Oblast projektů","IoT a automatizace","Oblasť projektov","IoT a automatizácia"],["Provedení","Sada pro prototypování","Vyhotovenie","Sada na prototypovanie"]],"catalog_names":{"Vývojová sada ESP32 pro IoT projekty":"Vývojová sada ESP32 pre IoT projekty"},"catalog_short_cs":"Začněte s elektronikou na úlohách, jejichž výsledek hned uvidíte. Vývojová sada ESP32 tvoří základ pro programování mikrokontroléru, práci se vstupy a vlastní IoT prototypy. Využijete ji při domácím studiu, ve školní výuce i při ověřování nápadů na automatizaci. Postupným propojováním programu a zapojení získáte zkušenosti použitelné u dalších zařízení. Konkrétní úlohy, napájení i možnosti připojení se řídí dodanou deskou a skutečným obsahem zvolené varianty sady. Začněte úlohou, u které rozumíte každému kroku: krátký program, kompatibilní součástka a srozumitelná reakce na změnu vstupu. Při dalším pokusu přidejte jedinou novou funkci.","catalog_short_t":"Začnite s elektronikou na úlohách, ktorých výsledok hneď uvidíte. Vývojová sada ESP32 tvorí základ na programovanie mikrokontroléra, prácu so vstupmi a vlastné IoT prototypy. Využijete ju pri domácom štúdiu, v školskej výučbe aj pri overovaní nápadov na automatizáciu. Postupným prepájaním programu a zapojenia získate skúsenosti použiteľné aj pri ďalších zariadeniach. Konkrétne úlohy, napájanie aj možnosti pripojenia sa riadia dodanou doskou a skutočným obsahom zvoleného variantu sady. Začnite úlohou, pri ktorej rozumiete každému kroku: krátky program, kompatibilná súčiastka a zrozumiteľná reakcia na zmenu vstupu. Pri ďalšom pokuse pridajte jedinú novú funkciu."},{"code":"OKL-006","name_cs":"Chytré brýle WAI4 s AI","name_t":"Inteligentné okuliare WAI4 s AI","short_cs_text":"WAI4 spojuje brýlové provedení s elektronikou určenou k propojení s kompatibilním telefonem. Černá obruba zachovává podobu běžného nositelného doplňku. Ovládací a elektronické části jsou součástí konstrukce brýlí. Doprovodný software zajišťuje propojení funkcí brýlí s telefonem. Dostupné AI nástroje vycházejí z konkrétní aplikace, její verze a připojených služeb. Výpočty a nabídka funkcí proto nejsou dány samotným vzhledem obruby. Součásti zařízení jsou rozloženy do obruby a stranic. Brýle ponechávají ruce volné a základní elektroniku nesou přímo na hlavě. Konstrukce tohoto typu se používá jako příslušenství k telefonu; nezahrnuje automaticky zobrazování rozšířené reality před očima.","short_t_text":"WAI4 spája okuliarové vyhotovenie s elektronikou určenou na prepojenie s kompatibilným telefónom. Čierny rám zachováva podobu bežného nositeľného doplnku. Ovládacie a elektronické časti sú súčasťou konštrukcie okuliarov. Sprievodný softvér zabezpečuje prepojenie funkcií okuliarov s telefónom. Dostupné AI nástroje vychádzajú z konkrétnej aplikácie, jej verzie a pripojených služieb. Výpočty a ponuka funkcií preto nie sú dané samotným vzhľadom rámu. Súčasti zariadenia sú rozložené v ráme a bočniciach. Okuliare nechávajú ruky voľné a základnú elektroniku nesú priamo na hlave. Konštrukcia tohto typu sa používa ako príslušenstvo k telefónu; nezahŕňa automaticky zobrazovanie rozšírenej reality pred očami.","short_t_html":"\n                            WAI4 spája okuliarové vyhotovenie s elektronikou určenou na prepojenie s kompatibilným telefónom. Čierny rám zachováva podobu bežného nositeľného doplnku. Ovládacie a elektronické časti sú súčasťou konštrukcie okuliarov. Sprievodný softvér zabezpečuje prepojenie funkcií okuliarov s telefónom. Dostupné AI nástroje vychádzajú z konkrétnej aplikácie, jej verzie a pripojených služieb. Výpočty a ponuka funkcií preto nie sú dané samotným vzhľadom rámu. Súčasti zariadenia sú rozložené v ráme a bočniciach. Okuliare nechávajú ruky voľné a základnú elektroniku nesú priamo na hlave. Konštrukcia tohto typu sa používa ako príslušenstvo k telefónu; nezahŕňa automaticky zobrazovanie rozšírenej reality pred očami.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Inteligentné okuliare WAI4 s AI</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Elektronika v okuliarovom ráme</h3><p>WAI4 spája okuliarové vyhotovenie s elektronikou určenou na prepojenie s kompatibilným telefónom. Čierny rám zachováva podobu bežného nositeľného doplnku. Ovládacie a elektronické časti sú súčasťou konštrukcie okuliarov.</p><p style=\"margin-top:16px\">Konštrukcia združuje nosný rám a funkčné elektronické časti v jednom predmete. Telefón zostáva nadväzujúcim zariadením pre podporované digitálne funkcie. Rozloženie súčastí do tela okuliarov umožňuje ich nosenie bez samostatného držiaka a zachováva priamy prístup k ovládacím prvkom na konštrukcii.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-006-function-1.jpg\" alt=\"Inteligentné okuliare WAI4 s AI – Elektronika v okuliarovom ráme\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Ilustračné zobrazenie funkcie</figcaption></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Spolupráca s mobilným zariadením</h3><p>Sprievodný softvér zabezpečuje prepojenie funkcií okuliarov s telefónom. Dostupné AI nástroje vychádzajú z konkrétnej aplikácie, jej verzie a pripojených služieb. Výpočty a ponuka funkcií preto nie sú dané samotným vzhľadom rámu.</p><p style=\"margin-top:16px\">Aplikácia tvorí rozhranie medzi pripojeným príslušenstvom a dostupnými službami. Jednotlivé funkcie môžu využívať spracovanie v telefóne alebo nadväzujúce online prostredie podľa konkrétnej implementácie. Jazykové možnosti a ponuka nástrojov sú vlastnosťou používaného softvéru, preto sa môžu líšiť medzi verziami a nastaveniami služby.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-006-function-2.jpg\" alt=\"Inteligentné okuliare WAI4 s AI – Spolupráca s mobilným zariadením\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Ilustračné zobrazenie funkcie</figcaption></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Kompaktné nositeľné vyhotovenie</h3><p>Súčasti zariadenia sú rozložené v ráme a bočniciach. Okuliare nechávajú ruky voľné a základnú elektroniku nesú priamo na hlave. Konštrukcia tohto typu sa používa ako príslušenstvo k telefónu; nezahŕňa automaticky zobrazovanie rozšírenej reality pred očami.</p><p style=\"margin-top:16px\">Nositeľné vyhotovenie presúva príslušenstvo z ruky do bežne používaného okuliarového formátu. Bočnice zároveň tvoria konštrukčný priestor pre vstavané súčasti a ich prepojenie. Okuliare a telefón fungujú ako nadväzujúce časti zostavy, v ktorej dostupný softvér určuje, aké úlohy možno skutočne vykonávať.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-006-function-3.jpg\" alt=\"Inteligentné okuliare WAI4 s AI – Kompaktné nositeľné vyhotovenie\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Ilustračné zobrazenie funkcie</figcaption></figure></section></article>\n                            ","params":[["Kategorie","Chytrá elektronika","Kategória","Inteligentná elektronika"],["Kategorie","Chytrá elektronika","Kategória","Inteligentná elektronika"],["Model","WAI4","Model","WAI4"],["Typ zařízení","Chytré brýle","Typ zariadenia","Inteligentné okuliare"],["Provedení","Nositelné brýlové příslušenství","Vyhotovenie","Nositeľné okuliarové príslušenstvo"],["Spolupracující zařízení","Kompatibilní mobilní telefon","Spolupracujúce zariadenie","Kompatibilný mobilný telefón"],["AI funkce","Podle aplikace a dostupné služby","AI funkcie","Podľa aplikácie a dostupnej služby"],["Oblast použití","Každodenní chytré příslušenství","Oblasť použitia","Každodenné inteligentné príslušenstvo"]],"catalog_names":{"Chytré brýle WAI4 s AI":"Inteligentné okuliare WAI4 s AI"},"catalog_short_cs":"Vyzkoušejte nositelnou elektroniku v podobě každodenního doplňku. Chytré brýle WAI4 spojují brýlové provedení s elektronikou a použitím s kompatibilním telefonem. Jsou zajímavou volbou pro zájemce o jinou podobu chytrého příslušenství. Dostupné AI funkce se odvíjejí od aplikace, jazyka, připojení a podmínek poskytované služby. Při výběru proto posuzujte pohodlí obrub společně s podporou funkcí, které chcete skutečně využívat. Důležitý je soulad brýlí, telefonu a softwaru. Brýle představují jinou podobu nositelné elektroniky než hodinky nebo sluchátka. Záleží na jejich vzhledu, usazení a způsobu, jakým je chcete zapojit do běžného dne.","catalog_short_t":"Vyskúšajte nositeľnú elektroniku v podobe každodenného doplnku. Inteligentné okuliare WAI4 spájajú okuliarové vyhotovenie s elektronikou a používaním s kompatibilným telefónom. Sú zaujímavou voľbou pre záujemcov o inú podobu inteligentného príslušenstva. Dostupné AI funkcie sa odvíjajú od aplikácie, jazyka, pripojenia a podmienok poskytovanej služby. Pri výbere preto posudzujte pohodlie rámu spolu s podporou funkcií, ktoré chcete skutočne využívať. Dôležitý je súlad okuliarov, telefónu a softvéru. Okuliare predstavujú inú podobu nositeľnej elektroniky ako hodinky alebo slúchadlá. Záleží na ich vzhľade, usadení a spôsobe, akým ich chcete zapojiť do bežného dňa."},{"code":"OKL-007","name_cs":"Esaker G300 – chytré brýle","name_t":"Esaker G300 – inteligentné okuliare","short_cs_text":"G300 nabízí nositelnou elektroniku v klasickém brýlovém tvaru. Funkční části jsou integrovány do obruby a stranic. Propojení s kompatibilním mobilním zařízením rozšiřuje možnosti běžného příslušenství k telefonu. Podporované funkce využívají doprovodný software a připojení k telefonu. Rozsah AI služeb a jejich dostupnost závisí na konkrétní aplikaci. Brýlové provedení umožňuje mít příslušenství při sobě bez držení dalšího zařízení v ruce. Čelní část, stranice a ovládání tvoří jeden celek. Elektronika je začleněna do konstrukce, která zůstává vizuálně blízká běžným brýlím. Konkrétní provedení čoček a dostupné funkce odpovídají dodané variantě G300.","short_t_text":"G300 ponúka nositeľnú elektroniku v klasickom okuliarovom tvare. Funkčné časti sú integrované do rámu a bočníc. Prepojenie s kompatibilným mobilným zariadením rozširuje možnosti bežného príslušenstva k telefónu. Podporované funkcie využívajú sprievodný softvér a pripojenie k telefónu. Rozsah AI služieb a ich dostupnosť závisí od konkrétnej aplikácie. Okuliarové vyhotovenie umožňuje mať príslušenstvo pri sebe bez držania ďalšieho zariadenia v ruke. Predná časť, bočnice a ovládanie tvoria jeden celok. Elektronika je začlenená do konštrukcie, ktorá zostáva vizuálne blízka bežným okuliarom. Konkrétne vyhotovenie šošoviek a dostupné funkcie zodpovedajú dodanému variantu G300.","short_t_html":"\n                            G300 ponúka nositeľnú elektroniku v klasickom okuliarovom tvare. Funkčné časti sú integrované do rámu a bočníc. Prepojenie s kompatibilným mobilným zariadením rozširuje možnosti bežného príslušenstva k telefónu. Podporované funkcie využívajú sprievodný softvér a pripojenie k telefónu. Rozsah AI služieb a ich dostupnosť závisí od konkrétnej aplikácie. Okuliarové vyhotovenie umožňuje mať príslušenstvo pri sebe bez držania ďalšieho zariadenia v ruke. Predná časť, bočnice a ovládanie tvoria jeden celok. Elektronika je začlenená do konštrukcie, ktorá zostáva vizuálne blízka bežným okuliarom. Konkrétne vyhotovenie šošoviek a dostupné funkcie zodpovedajú dodanému variantu G300.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Esaker G300 – inteligentné okuliare</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Inteligentné okuliare Esaker G300</h3><p>G300 ponúka nositeľnú elektroniku v klasickom okuliarovom tvare. Funkčné časti sú integrované do rámu a bočníc. Prepojenie s kompatibilným mobilným zariadením rozširuje možnosti bežného príslušenstva k telefónu.</p><p style=\"margin-top:16px\">Rám zabezpečuje mechanické spojenie jednotlivých častí a zároveň nesie integrované prvky zariadenia. Bočnice dopĺňajú priestor pre elektroniku mimo prednej časti okuliarov. G300 tak prepája funkciu nositeľného doplnku s možnosťami pripojeného telefónu, prostredníctvom ktorého sú sprístupnené podporované digitálne funkcie.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-007-function-1.jpg\" alt=\"Esaker G300 – inteligentné okuliare – Inteligentné okuliare Esaker G300\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Mobilný softvér a pripojenie</h3><p>Podporované funkcie využívajú sprievodný softvér a pripojenie k telefónu. Rozsah AI služieb a ich dostupnosť závisí od konkrétnej aplikácie. Okuliarové vyhotovenie umožňuje mať príslušenstvo pri sebe bez držania ďalšieho zariadenia v ruke.</p><p style=\"margin-top:16px\">Mobilná časť zostavy zabezpečuje softvérové prostredie na spracovanie a ovládanie dostupných funkcií. Podporu konkrétnej služby určuje jej kompatibilita s okuliarmi a používaným systémom. Rozsah možností preto vychádza z celého prepojenia zariadenia a aplikácie vrátane nastavení a dostupnosti nadväzujúcich služieb.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-007-function-2.jpg\" alt=\"Esaker G300 – inteligentné okuliare – Mobilný softvér a pripojenie\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Rám s integrovanými prvkami</h3><p>Predná časť, bočnice a ovládanie tvoria jeden celok. Elektronika je začlenená do konštrukcie, ktorá zostáva vizuálne blízka bežným okuliarom. Konkrétne vyhotovenie šošoviek a dostupné funkcie zodpovedajú dodanému variantu G300.</p><p style=\"margin-top:16px\">Integrované usporiadanie drží ovládacie a funkčné časti priamo na nositeľnej konštrukcii. Vonkajší tvar zostáva kompaktný a pri nosení nevyžaduje samostatné puzdro na elektroniku. Šošovky tvoria súčasť konkrétneho vyhotovenia, zatiaľ čo pripojené digitálne funkcie sú naviazané na podporovaný telefón a príslušný softvér.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-007-function-3.jpg\" alt=\"Esaker G300 – inteligentné okuliare – Rám s integrovanými prvkami\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie","Chytrá elektronika","Kategória","Inteligentná elektronika"],["Kategorie","Chytrá elektronika","Kategória","Inteligentná elektronika"],["Model","G300","Model","G300"],["Typ produktu","Chytré brýle","Typ produktu","Inteligentné okuliare"],["Značka","Esaker","Značka","Esaker"],["Provedení","Nositelné elektronické příslušenství","Vyhotovenie","Nositeľné elektronické príslušenstvo"],["Spolupracující zařízení","Kompatibilní mobilní zařízení","Spolupracujúce zariadenie","Kompatibilné mobilné zariadenie"],["Softwarové funkce","Podle varianty a aplikace","Softvérové funkcie","Podľa variantu a aplikácie"]],"catalog_names":{"Chytré brýle Esaker G300":"Inteligentné okuliare Esaker G300","Esaker G300 – chytré brýle":"Esaker G300 – inteligentné okuliare"},"catalog_short_cs":"Klasický tvar brýlí může být také součástí chytré výbavy. Esaker G300 je nositelné elektronické příslušenství určené pro použití s kompatibilním mobilním zařízením. Zaujme uživatele, kteří hledají jiný formát doplňku k telefonu a chtějí ho sladit s každodenním nošením. Při výběru zohledněte pohodlí obrub, podporovanou aplikaci a skutečné možnosti dodávané varianty. Jejich soulad rozhoduje, které funkce vám budou užitečné doma, při práci nebo během cestování. Elektronika nemusí představovat další předmět uložený v kapse. Brýlové provedení propojuje běžný doplněk s novým způsobem používání příslušenství k telefonu.","catalog_short_t":"Klasický tvar okuliarov môže byť aj súčasťou inteligentnej výbavy. Esaker G300 je nositeľné elektronické príslušenstvo určené na použitie s kompatibilným mobilným zariadením. Zaujme používateľov, ktorí hľadajú iný formát doplnku k telefónu a chcú ho zladiť s každodenným nosením. Pri výbere zohľadnite pohodlie rámu, podporovanú aplikáciu a skutočné možnosti dodávaného variantu. Ich súlad rozhoduje o tom, ktoré funkcie vám budú užitočné doma, v práci alebo počas cestovania. Elektronika nemusí predstavovať ďalší predmet uložený vo vrecku. Okuliarové vyhotovenie prepája bežný doplnok s novým spôsobom používania príslušenstva k telefónu."},{"code":"OKL-008","name_cs":"S29A – kapesní AI diktafon","name_t":"S29A – vreckový AI diktafón","short_cs_text":"S29A slouží k zachycení mluveného slova, osobních poznámek a rozhovorů. Samostatné zařízení uchovává nahrávku jako podklad pro pozdější práci. Ploché tělo a vlastní ovládání doplňují přenosné provedení. Podporovaný software může převádět zvukový záznam na text a usnadnit práci s obsahem nahrávky. Dostupné jazyky, souhrny a limity zpracování závisejí na použité službě. Kvalita výsledku souvisí se srozumitelností zvuku a jazykem mluvčích. Zvuk zůstává zdrojem původního sdělení, zatímco textový výstup usnadňuje vyhledávání a další zpracování. Kompaktní rekordér odděluje pořizování záznamu od běžného ovládání telefonu. Výsledné soubory lze využít podle možností doprovodné aplikace.","short_t_text":"S29A slúži na zachytenie hovoreného slova, osobných poznámok a rozhovorov. Samostatné zariadenie uchováva nahrávku ako podklad na neskoršiu prácu. Ploché telo a vlastné ovládanie dopĺňajú prenosné vyhotovenie. Podporovaný softvér môže prevádzať zvukový záznam na text a uľahčiť prácu s obsahom nahrávky. Dostupné jazyky, zhrnutia a limity spracovania závisia od použitej služby. Kvalita výsledku súvisí so zrozumiteľnosťou zvuku a jazykom hovoriacich. Zvuk zostáva zdrojom pôvodného prejavu, zatiaľ čo textový výstup uľahčuje vyhľadávanie a ďalšie spracovanie. Kompaktný rekordér oddeľuje vytváranie záznamu od bežného ovládania telefónu. Výsledné súbory možno využiť podľa možností sprievodnej aplikácie.","short_t_html":"\n                            S29A slúži na zachytenie hovoreného slova, osobných poznámok a rozhovorov. Samostatné zariadenie uchováva nahrávku ako podklad na neskoršiu prácu. Ploché telo a vlastné ovládanie dopĺňajú prenosné vyhotovenie. Podporovaný softvér môže prevádzať zvukový záznam na text a uľahčiť prácu s obsahom nahrávky. Dostupné jazyky, zhrnutia a limity spracovania závisia od použitej služby. Kvalita výsledku súvisí so zrozumiteľnosťou zvuku a jazykom hovoriacich. Zvuk zostáva zdrojom pôvodného prejavu, zatiaľ čo textový výstup uľahčuje vyhľadávanie a ďalšie spracovanie. Kompaktný rekordér oddeľuje vytváranie záznamu od bežného ovládania telefónu. Výsledné súbory možno využiť podľa možností sprievodnej aplikácie.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>S29A – vreckový AI diktafón</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Zvukový záznam vo vreckovom formáte</h3><p>S29A slúži na zachytenie hovoreného slova, osobných poznámok a rozhovorov. Samostatné zariadenie uchováva nahrávku ako podklad na neskoršiu prácu. Ploché telo a vlastné ovládanie dopĺňajú prenosné vyhotovenie.</p><p style=\"margin-top:16px\">Zvuková stopa zachováva pôvodné formulácie aj časovú nadväznosť zaznamenaného prejavu. Záznam možno neskôr znova prehrať a porovnať s nadväzujúcim textovým výstupom. Vrecková konštrukcia sústreďuje vytváranie nahrávky do samostatného prístroja, zatiaľ čo ďalšie spracovanie môže prebiehať v prostredí podporovaného softvéru.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-008-function-1.jpg\" alt=\"S29A – vreckový AI diktafón – Zvukový záznam vo vreckovom formáte\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Prepis prostredníctvom AI</h3><p>Podporovaný softvér môže prevádzať zvukový záznam na text a uľahčiť prácu s obsahom nahrávky. Dostupné jazyky, zhrnutia a limity spracovania závisia od použitej služby. Kvalita výsledku súvisí so zrozumiteľnosťou zvuku a jazykom hovoriacich.</p><p style=\"margin-top:16px\">Prevod reči na text vytvára ďalšiu podobu toho istého obsahu, s ktorou sa pri čítaní ľahšie pracuje. Rozpoznávanie reči ovplyvňujú prekrývajúce sa hlasy, okolité zvuky a výslovnosť. Prípadné automatické zhrnutie nadväzuje na spracovaný záznam a jeho rozsah zodpovedá možnostiam používanej služby.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-008-function-2.jpg\" alt=\"S29A – vreckový AI diktafón – Prepis prostredníctvom AI\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Prepojenie nahrávky s pracovným podkladom</h3><p>Zvuk zostáva zdrojom pôvodného prejavu, zatiaľ čo textový výstup uľahčuje vyhľadávanie a ďalšie spracovanie. Kompaktný rekordér oddeľuje vytváranie záznamu od bežného ovládania telefónu. Výsledné súbory možno využiť podľa možností sprievodnej aplikácie.</p><p style=\"margin-top:16px\">Audio a text predstavujú dve navzájom nadväzujúce vrstvy podkladu. Nahrávka umožňuje vrátiť sa k hlasu a presnému zneniu, text zjednodušuje orientáciu v obsahu. Spôsob sprístupnenia, ukladania a odovzdávania výstupov vychádza z podporovaných funkcií aplikácie, cez ktorú sa so záznamom pracuje.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-008-function-3.jpg\" alt=\"S29A – vreckový AI diktafón – Prepojenie nahrávky s pracovným podkladom\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie","Chytrá elektronika","Kategória","Inteligentná elektronika"],["Kategorie","Chytrá elektronika","Kategória","Inteligentná elektronika"],["Model","S29A","Model","S29A"],["Typ produktu","Digitální diktafon","Typ produktu","Digitálny diktafón"],["Zaznamenávaný obsah","Zvuk","Zaznamenávaný obsah","Zvuk"],["Provedení","Přenosné, kapesní","Vyhotovenie","Prenosné, vreckové"],["Typické použití","Poznámky, výuka, schůzky","Typické použitie","Poznámky, výučba, stretnutia"],["AI funkce","Podle aplikace a dostupné služby","AI funkcie","Podľa aplikácie a dostupnej služby"]],"catalog_names":{"Kapesní AI diktafon S29A":"Vreckový AI diktafón S29A","S29A – kapesní AI diktafon":"S29A – vreckový AI diktafón"},"catalog_short_cs":"Mějte nápady, poznámky a podklady ze schůzek pohromadě. Kapesní diktafon S29A je určen pro pořizování zvukových záznamů, ke kterým se chcete později vrátit. Malé provedení snadno zařadíte do školní nebo pracovní výbavy. Podporované AI zpracování může podle aplikace pomoci s přepisem či shrnutím, původní nahrávka ale zůstává důležitým zdrojem souvislostí. Rozsah služby, jazyky a kapacitu úložiště vždy posuzujte pro konkrétní dodávanou variantu. Ruční poznámky někdy zachytí hesla, ale ztratí souvislosti. Zvukový záznam umožňuje vrátit se k původní formulaci a doplnit chybějící kontext.","catalog_short_t":"Majte nápady, poznámky a podklady zo stretnutí pohromade. Vreckový diktafón S29A je určený na vytváranie zvukových záznamov, ku ktorým sa chcete neskôr vrátiť. Malé vyhotovenie ľahko zaradíte do školskej alebo pracovnej výbavy. Podporované AI spracovanie môže podľa aplikácie pomôcť s prepisom či zhrnutím, pôvodná nahrávka však zostáva dôležitým zdrojom súvislostí. Rozsah služby, jazyky a kapacitu úložiska vždy posudzujte pre konkrétny dodávaný variant. Ručné poznámky niekedy zachytia kľúčové slová, no stratia súvislosti. Zvukový záznam umožňuje vrátiť sa k pôvodnej formulácii a doplniť chýbajúci kontext."},{"code":"OKL-009","name_cs":"Q18 – bezdrátová překladová sluchátka","name_t":"Q18 – bezdrôtové prekladové slúchadlá","short_cs_text":"Sluchátka Q18 spolupracují s kompatibilním překladovým softwarem. Aplikace zpracovává řeč a zpřístupňuje podporované jazyky a režimy rozhovoru. Rozsah překladu závisí na službě, připojení a konkrétním nastavení telefonu. Vedle překladového použití slouží sluchátka pro podporovaný poslech zvuku a telefonování. Dvojice sluchátek je uložena v přenosném pouzdře. Otevřené provedení je tvarované pro nasazení kolem ucha. Tvarované lůžko udržuje obě sluchátka pohromadě a chrání je při přenášení. Pouzdro tvoří součást nabíjecího řešení. Ovládání poslechu, hovoru a překladových funkcí se řídí podporou připojeného telefonu a aplikace.","short_t_text":"Slúchadlá Q18 spolupracujú s kompatibilným prekladovým softvérom. Aplikácia spracúva reč a sprístupňuje podporované jazyky a režimy rozhovoru. Rozsah prekladu závisí od služby, pripojenia a konkrétneho nastavenia telefónu. Okrem prekladového použitia slúžia slúchadlá na podporované počúvanie zvuku a telefonovanie. Pár slúchadiel je uložený v prenosnom puzdre. Otvorené vyhotovenie je tvarované na nasadenie okolo ucha. Tvarované lôžko drží obe slúchadlá pohromade a chráni ich pri prenášaní. Puzdro tvorí súčasť nabíjacieho riešenia. Ovládanie počúvania, hovoru a prekladových funkcií sa riadi podporou pripojeného telefónu a aplikácie.","short_t_html":"\n                            Slúchadlá Q18 spolupracujú s kompatibilným prekladovým softvérom. Aplikácia spracúva reč a sprístupňuje podporované jazyky a režimy rozhovoru. Rozsah prekladu závisí od služby, pripojenia a konkrétneho nastavenia telefónu. Okrem prekladového použitia slúžia slúchadlá na podporované počúvanie zvuku a telefonovanie. Pár slúchadiel je uložený v prenosnom puzdre. Otvorené vyhotovenie je tvarované na nasadenie okolo ucha. Tvarované lôžko drží obe slúchadlá pohromade a chráni ich pri prenášaní. Puzdro tvorí súčasť nabíjacieho riešenia. Ovládanie počúvania, hovoru a prekladových funkcií sa riadi podporou pripojeného telefónu a aplikácie.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Q18 – bezdrôtové prekladové slúchadlá</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Prekladové funkcie s aplikáciou</h3><p>Slúchadlá Q18 spolupracujú s kompatibilným prekladovým softvérom. Aplikácia spracúva reč a sprístupňuje podporované jazyky a režimy rozhovoru. Rozsah prekladu závisí od služby, pripojenia a konkrétneho nastavenia telefónu.</p><p style=\"margin-top:16px\">Prekladový reťazec zahŕňa zachytenie reči, jej rozpoznanie a prevod do zvoleného jazyka. Slúchadlá tvoria zvukovú časť zostavy, telefón poskytuje prostredie aplikácie. Jednotlivé kroky a spôsob odovzdávania prekladu sa odvíjajú od režimov, ktoré sprístupňuje konkrétna verzia používaného softvéru.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-009-function-1.jpg\" alt=\"Q18 – bezdrôtové prekladové slúchadlá – Prekladové funkcie s aplikáciou\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Bezdrôtové počúvanie a hovory</h3><p>Okrem prekladového použitia slúžia slúchadlá na podporované počúvanie zvuku a telefonovanie. Pár slúchadiel je uložený v prenosnom puzdre. Otvorené vyhotovenie je tvarované na nasadenie okolo ucha.</p><p style=\"margin-top:16px\">Zvukové funkcie využívajú pripojenie ku kompatibilnému zariadeniu, ktoré odovzdáva prehrávaný obsah alebo telefonický hovor. Konštrukcia okolo ucha drží slúchadlo na mieste a ponecháva jeho funkčné časti v nositeľnom vyhotovení. Prekladová služba dopĺňa túto základnú zvukovú zostavu prostredníctvom podporovanej mobilnej aplikácie.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-009-function-2.jpg\" alt=\"Q18 – bezdrôtové prekladové slúchadlá – Bezdrôtové počúvanie a hovory\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Puzdro na uloženie a nabíjanie</h3><p>Tvarované lôžko drží obe slúchadlá pohromade a chráni ich pri prenášaní. Puzdro tvorí súčasť nabíjacieho riešenia. Ovládanie počúvania, hovoru a prekladových funkcií sa riadi podporou pripojeného telefónu a aplikácie.</p><p style=\"margin-top:16px\">Oddelené miesta pre ľavú a pravú časť uľahčujú uloženie celého páru do jedného celku. Nabíjacie kontakty a zodpovedajúce lôžka prepájajú slúchadlá s puzdrom. Pri prenášaní zostávajú drobné časti pohromade, zatiaľ čo telefón naďalej zabezpečuje softvérové prostredie pre dostupné komunikačné a prekladové funkcie.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-009-function-3.jpg\" alt=\"Q18 – bezdrôtové prekladové slúchadlá – Puzdro na uloženie a nabíjanie\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie","Chytrá elektronika","Kategória","Inteligentná elektronika"],["Kategorie","Chytrá elektronika","Kategória","Inteligentná elektronika"],["Model","Q18","Model","Q18"],["Typ produktu","Bezdrátová překladová sluchátka","Typ produktu","Bezdrátová překladová sluchátka"],["Oblast použití","Poslech, hovory a překlad přes aplikaci","Oblasť použitia","Počúvanie, hovory a preklad cez aplikáciu"],["Spolupracující zařízení","Kompatibilní telefon","Spolupracujúce zariadenie","Kompatibilný telefón"],["Překladové funkce","Podle doprovodné aplikace","Prekladové funkcie","Podľa sprievodnej aplikácie"],["Jazyková podpora","Podle služby a režimu","Jazyková podpora","Podľa služby a režimu"]],"catalog_names":{"Bezdrátová překladová sluchátka Q18":"Bezdrôtové prekladové slúchadlá Q18","Q18 – bezdrátová překladová sluchátka":"Q18 – bezdrôtové prekladové slúchadlá"},"catalog_short_cs":"Propojte každodenní poslech s možnostmi kompatibilní překladové aplikace. Bezdrátová sluchátka Q18 poslouží pro hudbu, hovory a podporované režimy práce s cizím jazykem. Při cestování mohou být užitečnou oporou běžné domluvy, zatímco telefon zajišťuje potřebné softwarové zpracování. Záleží proto na jeho kompatibilitě, připojení a podmínkách služby. Před cestou si ověřte konkrétní jazyky i způsob konverzace, který aplikace podporuje. Porozumění mluvené řeči usnadní, když máte k dispozici další zdroj významu. Q18 lze používat s podporovanou překladovou aplikací a jejími dostupnými režimy.","catalog_short_t":"Prepojte každodenné počúvanie s možnosťami kompatibilnej prekladovej aplikácie. Bezdrôtové slúchadlá Q18 poslúžia na hudbu, hovory a podporované režimy práce s cudzím jazykom. Pri cestovaní môžu byť užitočnou oporou bežného dorozumievania, zatiaľ čo telefón zabezpečuje potrebné softvérové spracovanie. Záleží preto na jeho kompatibilite, pripojení a podmienkach služby. Pred cestou si overte konkrétne jazyky aj spôsob konverzácie, ktorý aplikácia podporuje. Porozumenie hovorenej reči uľahčí, keď máte k dispozícii ďalší zdroj významu. Q18 možno používať s podporovanou prekladovou aplikáciou a jej dostupnými režimami."},{"code":"OKL-010","name_cs":"R99 – chytrý prsten","name_t":"R99 – chytrý prsteň","short_cs_text":"R99 umísťuje snímací elektroniku na vnitřní stranu prstenu. Nositelné provedení poskytuje podklady o aktivitě a dalších podporovaných ukazatelích. Získaná data se zobrazují prostřednictvím kompatibilní mobilní aplikace. Doprovodný software pracuje s dostupnými záznamy ze senzorů a vytváří osobní přehled. Podporované sledování spánku a aktivity doplňuje každodenní používání. Výstupy jsou orientační údaje spotřební nositelné elektroniky. Snímače jsou zapuštěny do vnitřní části hladké obroučky. Prsten nemá klasický velký displej a přehled dat přesouvá do telefonu. Kompaktní konstrukce zachovává podobu osobního šperku a nositelného doplňku.","short_t_text":"R99 umiestňuje snímaciu elektroniku na vnútornú stranu prsteňa. Nositeľné vyhotovenie poskytuje podklady o aktivite a ďalších podporovaných ukazovateľoch. Získané údaje sa zobrazujú prostredníctvom kompatibilnej mobilnej aplikácie. Sprievodný softvér pracuje s dostupnými záznamami zo senzorov a vytvára osobný prehľad. Podporované sledovanie spánku a aktivity dopĺňa každodenné používanie. Výstupy sú orientačné údaje spotrebnej nositeľnej elektroniky. Snímače sú zapustené do vnútornej časti hladkej obrúčky. Prsteň nemá klasický veľký displej a prehľad údajov presúva do telefónu. Kompaktná konštrukcia zachováva podobu osobného šperku a nositeľného doplnku.","short_t_html":"\n                            R99 umiestňuje snímaciu elektroniku na vnútornú stranu prsteňa. Nositeľné vyhotovenie poskytuje podklady o aktivite a ďalších podporovaných ukazovateľoch. Získané údaje sa zobrazujú prostredníctvom kompatibilnej mobilnej aplikácie. Sprievodný softvér pracuje s dostupnými záznamami zo senzorov a vytvára osobný prehľad. Podporované sledovanie spánku a aktivity dopĺňa každodenné používanie. Výstupy sú orientačné údaje spotrebnej nositeľnej elektroniky. Snímače sú zapustené do vnútornej časti hladkej obrúčky. Prsteň nemá klasický veľký displej a prehľad údajov presúva do telefónu. Kompaktná konštrukcia zachováva podobu osobného šperku a nositeľného doplnku.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>R99 – chytrý prsteň</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Senzory v chytrom prsteni</h3><p>R99 umiestňuje snímaciu elektroniku na vnútornú stranu prsteňa. Nositeľné vyhotovenie poskytuje podklady o aktivite a ďalších podporovaných ukazovateľoch. Získané údaje sa zobrazujú prostredníctvom kompatibilnej mobilnej aplikácie.</p><p style=\"margin-top:16px\">Umiestnenie snímačov na vnútornej strane zabezpečuje ich kontakt s prstom pri nosení. Elektronika spracúva dostupné signály a odovzdáva podporované údaje aplikácii. Prsteň tak funguje ako zberná časť zostavy, zatiaľ čo podrobné zobrazenie a ďalšiu interpretáciu získaných informácií preberá pripojený telefón.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-010-function-1.jpg\" alt=\"R99 – chytrý prsteň – Senzory v chytrom prsteni\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Prehľad aktivity a odpočinku</h3><p>Sprievodný softvér pracuje s dostupnými záznamami zo senzorov a vytvára osobný prehľad. Podporované sledovanie spánku a aktivity dopĺňa každodenné používanie. Výstupy sú orientačné údaje spotrebnej nositeľnej elektroniky.</p><p style=\"margin-top:16px\">Záznamy z jednotlivých období umožňujú zobrazovať aktivitu a odpočinok v časových súvislostiach podľa možností aplikácie. Softvér prevádza dostupné údaje do prehľadov a odhadovaných ukazovateľov. Význam jednotlivých hodnôt vychádza z použitej metódy spracovania a z funkcií, ktoré konkrétne vyhotovenie prsteňa podporuje.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-010-function-2.jpg\" alt=\"R99 – chytrý prsteň – Prehľad aktivity a odpočinku\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Elektronika v uzavretej obrúčke</h3><p>Snímače sú zapustené do vnútornej časti hladkej obrúčky. Prsteň nemá klasický veľký displej a prehľad údajov presúva do telefónu. Kompaktná konštrukcia zachováva podobu osobného šperku a nositeľného doplnku.</p><p style=\"margin-top:16px\">Vonkajšia obrúčka tvorí súvislý nosný celok, vnútorná časť obsahuje funkčné snímacie prvky. Oddelenie zberu údajov a ich zobrazenia umožňuje zachovať malé rozmery nositeľného zariadenia. Telefón poskytuje väčšiu plochu na prehľady, nastavenia a čítanie informácií, ktoré by sa na samotnom prsteni zobrazovali ťažko.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-010-function-3.jpg\" alt=\"R99 – chytrý prsteň – Elektronika v uzavretej obrúčke\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Chytrá elektronika","Kategória:","Inteligentná elektronika"],["Kategorie:","Chytrá elektronika","Kategória:","Inteligentná elektronika"],["Model:","R99","Model:","R99"],["Typ produktu:","Chytrý prsten","Typ produktu:","Chytrý prsteň"],["Provedení:","Nositelné příslušenství na prst","Vyhotovenie:","Nositeľné príslušenstvo na prst"],["Volba varianty:","Podle velikosti prstenu","Výber variantu:","Podľa veľkosti prsteňa"],["Softwarové funkce:","Podle kompatibilní aplikace","Softvérové funkcie:","Podľa kompatibilnej aplikácie"],["Určení:","Spotřební nositelná elektronika","Určenie:","Spotrebná nositeľná elektronika"]],"catalog_names":{"Chytrý prsten R99":"Chytrý prsteň R99","R99 – chytrý prsten":"R99 – chytrý prsteň"},"catalog_short_cs":"Objevte nositelnou elektroniku v nenápadném formátu prstenu. R99 je alternativou pro uživatele, kteří dávají přednost malému doplňku před běžnými chytrými hodinkami. Při výběru záleží na správné velikosti, pohodlném usazení a podpoře doprovodné aplikace. Konkrétní funkce a zobrazované údaje se odvíjejí od dodávané varianty, nikoli pouze od vzhledu. Zajímavá volba pro zájemce o nové formáty každodenní elektroniky, kteří chtějí hlavní přehled sledovat v kompatibilním telefonu. Prsten poskytuje odlišný způsob nošení než náramek s displejem. Může vyhovovat uživatelům, kteří chtějí nenápadnější doplněk a nevadí jim pracovat s přehledem v telefonu.","catalog_short_t":"Objavte nositeľnú elektroniku v nenápadnom formáte prsteňa. R99 je alternatívou pre používateľov, ktorí uprednostňujú malý doplnok pred bežnými chytrými hodinkami. Pri výbere záleží na správnej veľkosti, pohodlnom usadení a podpore sprievodnej aplikácie. Konkrétne funkcie a zobrazované údaje sa odvíjajú od dodávaného variantu, nie iba od vzhľadu. Zaujímavá voľba pre záujemcov o nové formáty každodennej elektroniky, ktorí chcú hlavný prehľad sledovať v kompatibilnom telefóne. Prsteň poskytuje odlišný spôsob nosenia ako náramok s displejom. Môže vyhovovať používateľom, ktorí chcú nenápadnejší doplnok a nevadí im pracovať s prehľadom v telefóne."},{"code":"OKL-011","name_cs":"Digitální USB-C tester napájení","name_t":"Digitálny USB-C tester napájania","short_cs_text":"USB-C tester zobrazuje elektrické veličiny přímo v napájecí trase. Barevná obrazovka sdružuje aktuální napětí, proud a vypočtený výkon. Přístroj tvoří průchozí prvek mezi kompatibilním zdrojem, kabelem a napájeným zařízením. Tester pomáhá sledovat chování USB-C napájení a podporované nabíjecí protokoly. Údaje jsou dostupné bez samostatného počítačového monitoru. Konkrétní režim nabíjení vzniká dohodou zdroje, kabelu a připojeného zařízení. Průchozí konektory dovolují sledovat odběr při běžném napájení elektroniky. Změna zátěže se projeví na hodnotách obrazovky. Tester tak poskytuje přehled pro porovnání kompatibilních kabelů, nabíječek a USB-C příslušenství.","short_t_text":"USB-C tester zobrazuje elektrické veličiny priamo v napájacej trase. Farebná obrazovka združuje aktuálne napätie, prúd a vypočítaný výkon. Prístroj tvorí priechodný prvok medzi kompatibilným zdrojom, káblom a napájaným zariadením. Tester pomáha sledovať správanie USB-C napájania a podporované nabíjacie protokoly. Údaje sú dostupné bez samostatného počítačového monitora. Konkrétny režim nabíjania vzniká dohodou zdroja, kábla a pripojeného zariadenia. Priechodné konektory umožňujú sledovať odber pri bežnom napájaní elektroniky. Zmena záťaže sa prejaví na hodnotách na obrazovke. Tester tak poskytuje prehľad na porovnanie kompatibilných káblov, nabíjačiek a USB-C príslušenstva.","short_t_html":"\n                            USB-C tester zobrazuje elektrické veličiny priamo v napájacej trase. Farebná obrazovka združuje aktuálne napätie, prúd a vypočítaný výkon. Prístroj tvorí priechodný prvok medzi kompatibilným zdrojom, káblom a napájaným zariadením. Tester pomáha sledovať správanie USB-C napájania a podporované nabíjacie protokoly. Údaje sú dostupné bez samostatného počítačového monitora. Konkrétny režim nabíjania vzniká dohodou zdroja, kábla a pripojeného zariadenia. Priechodné konektory umožňujú sledovať odber pri bežnom napájaní elektroniky. Zmena záťaže sa prejaví na hodnotách na obrazovke. Tester tak poskytuje prehľad na porovnanie kompatibilných káblov, nabíjačiek a USB-C príslušenstva.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Digitálny USB-C tester napájania</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Napätie, prúd a výkon na displeji</h3><p>USB-C tester zobrazuje elektrické veličiny priamo v napájacej trase. Farebná obrazovka združuje aktuálne napätie, prúd a vypočítaný výkon. Prístroj tvorí priechodný prvok medzi kompatibilným zdrojom, káblom a napájaným zariadením.</p><p style=\"margin-top:16px\">Súčasné zobrazenie viacerých veličín prepája okamžitý odber s napätím zdroja. Výkon vyjadruje ich vzájomný vzťah a mení sa spolu s prevádzkou pripojenej záťaže. Displej tak ukazuje stav konkrétneho prepojenia v danom okamihu vrátane zmien počas nabíjania alebo prevádzky zariadenia.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-011-function-1.jpg\" alt=\"Digitálny USB-C tester napájania – Napätie, prúd a výkon na displeji\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Prehľad podporovaného nabíjania</h3><p>Tester pomáha sledovať správanie USB-C napájania a podporované nabíjacie protokoly. Údaje sú dostupné bez samostatného počítačového monitora. Konkrétny režim nabíjania vzniká dohodou zdroja, kábla a pripojeného zariadenia.</p><p style=\"margin-top:16px\">Dostupný napájací režim závisí od schopností všetkých častí prepojenia. Samotný konektor USB-C neurčuje výsledné napätie ani odoberaný výkon. Zobrazené hodnoty umožňujú rozlíšiť aktuálny prevádzkový stav od maximálneho výkonu uvedeného na zdroji, ktorý pripojená elektronika nemusí v každom okamihu využívať.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-011-function-2.jpg\" alt=\"Digitálny USB-C tester napájania – Prehľad podporovaného nabíjania\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Meranie v reálnej napájacej trase</h3><p>Priechodné konektory umožňujú sledovať odber pri bežnom napájaní elektroniky. Zmena záťaže sa prejaví na hodnotách na obrazovke. Tester tak poskytuje prehľad na porovnanie kompatibilných káblov, nabíjačiek a USB-C príslušenstva.</p><p style=\"margin-top:16px\">Umiestnenie testera do napájacej cesty prepája meranie s reálnou prevádzkou pripojeného zariadenia. Obrazovka sprístupňuje údaje bez rozpájania zostavy kvôli samostatnému odčítaniu. Rozdiely medzi jednotlivými prepojeniami možno posudzovať podľa zobrazovaných veličín v rozsahu, ktorý podporuje konkrétne vyhotovenie meradla.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-011-function-3.jpg\" alt=\"Digitálny USB-C tester napájania – Meranie v reálnej napájacej trase\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Měřicí technika a nářadí","Kategória:","Meracia technika a náradie"],["Kategorie:","Měřicí technika a nářadí","Kategória:","Meracia technika a náradie"],["Připojení:","USB C","Pripojenie:","USB C"],["Typ produktu:","Digitální tester napájení","Typ produktu:","Digitálny tester napájania"],["Rozhraní:","USB-C","Rozhranie:","USB-C"],["Základní účel:","Kontrola napětí a proudu","Základný účel:","Kontrola napätia a prúdu"],["Zobrazení:","Digitální","Zobrazenie:","Digitálne"],["Místo zapojení:","Kompatibilní napájecí cesta","Miesto zapojenia:","Kompatibilná napájacia cesta"],["Použití:","Orientační kontrola nabíjecí sestavy","Použitie:","Orientačná kontrola nabíjacej zostavy"]],"catalog_names":{"Digitální USB C tester napájení":"Digitálny USB C tester napájania","Digitální USB-C tester napájení":"Digitálny USB-C tester napájania"},"catalog_short_cs":"Zjistěte, jak se při nabíjení chová konkrétní sestava zdroje, kabelu a zařízení. Digitální USB-C tester slouží ke kontrole podporovaných elektrických veličin na kompatibilním propojení a pomáhá s orientačním porovnáváním nabíjecí výbavy. Využijete ho doma, při základní diagnostice i na pracovním stole. Místo odhadu podle samotné nabíjecí ikony získáte další informace o přenosu energie. Před zapojením vždy porovnejte napětí, proud a protokoly sestavy s limity konkrétního testeru. Telefon může zobrazovat nabíjení, aniž by tím popisoval chování celé sestavy. Tester vložený do podporované napájecí cesty umožňuje sledovat dostupné veličiny a porovnávat zdroje nebo kabely.","catalog_short_t":"Zistite, ako sa pri nabíjaní správa konkrétna zostava zdroja, kábla a zariadenia. Digitálny USB-C tester slúži na kontrolu podporovaných elektrických veličín na kompatibilnom prepojení a pomáha s orientačným porovnávaním nabíjacej výbavy. Využijete ho doma, pri základnej diagnostike aj na pracovnom stole. Namiesto odhadu podľa samotnej ikony nabíjania získate ďalšie informácie o prenose energie. Pred zapojením vždy porovnajte napätie, prúd a protokoly zostavy s limitmi konkrétneho testera. Telefón môže zobrazovať nabíjanie bez toho, aby tým opisoval správanie celej zostavy. Tester vložený do podporovanej napájacej cesty umožňuje sledovať dostupné veličiny a porovnávať zdroje alebo káble."},{"code":"OKL-012","name_cs":"Digitální kapesní váha s rozlišením 0,01 g","name_t":"Digitálna vrecková váha s rozlíšením 0,01 g","short_cs_text":"Digitální váha zobrazuje hmotnost v krocích po 0,01 g. Jemné rozlišení je určené pro práci s drobnými předměty. Hodnota rozlišení popisuje krok displeje, nikoli samostatnou záruku přesnosti každého měření. Kovová vážicí plocha doplňuje číselný displej a fyzická tlačítka. Funkce tárování odděluje hmotnost nádoby od vloženého obsahu. Výsledek je dostupný přímo na zařízení bez propojení s telefonem. Nízké tělo a průhledný kryt chrání vážicí plochu při uložení. Váha vytváří samostatné přenosné měřidlo pro drobné předměty a součástky. Kompaktní konstrukce spojuje plochu, displej a ovládání do jednoho celku.","short_t_text":"Digitálna váha zobrazuje hmotnosť v krokoch po 0,01 g. Jemné rozlíšenie je určené na prácu s drobnými predmetmi. Hodnota rozlíšenia opisuje krok displeja, nie samostatnú záruku presnosti každého merania. Kovová vážiaca plocha dopĺňa číselný displej a fyzické tlačidlá. Funkcia tárovania oddeľuje hmotnosť nádoby od vloženého obsahu. Výsledok je dostupný priamo na zariadení bez prepojenia s telefónom. Nízke telo a priehľadný kryt chránia vážiacu plochu pri uložení. Váha tvorí samostatné prenosné meradlo na drobné predmety a súčiastky. Kompaktná konštrukcia spája plochu, displej a ovládanie do jedného celku.","short_t_html":"\n                            Digitálna váha zobrazuje hmotnosť v krokoch po 0,01 g. Jemné rozlíšenie je určené na prácu s drobnými predmetmi. Hodnota rozlíšenia opisuje krok displeja, nie samostatnú záruku presnosti každého merania. Kovová vážiaca plocha dopĺňa číselný displej a fyzické tlačidlá. Funkcia tárovania oddeľuje hmotnosť nádoby od vloženého obsahu. Výsledok je dostupný priamo na zariadení bez prepojenia s telefónom. Nízke telo a priehľadný kryt chránia vážiacu plochu pri uložení. Váha tvorí samostatné prenosné meradlo na drobné predmety a súčiastky. Kompaktná konštrukcia spája plochu, displej a ovládanie do jedného celku.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Digitálna vrecková váha s rozlíšením 0,01 g</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Rozlíšenie 0,01 gramu</h3><p>Digitálna váha zobrazuje hmotnosť v krokoch po 0,01 g. Jemné rozlíšenie je určené na prácu s drobnými predmetmi. Hodnota rozlíšenia opisuje krok displeja, nie samostatnú záruku presnosti každého merania.</p><p style=\"margin-top:16px\">Číselný údaj rozlišuje malé prírastky hmotnosti a umožňuje sledovať zmenu pri postupnom pridávaní obsahu. Jemný krok displeja poskytuje podrobnejšie odčítanie ako váhy zobrazujúce celé gramy. Skutočný výsledok pritom vychádza z meracieho systému váhy a podmienok konkrétneho váženia, nie iba z počtu desatinných miest.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-012-function-1.jpg\" alt=\"Digitálna vrecková váha s rozlíšením 0,01 g – Rozlíšenie 0,01 gramu\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Vážiaca plocha a digitálne ovládanie</h3><p>Kovová vážiaca plocha dopĺňa číselný displej a fyzické tlačidlá. Funkcia tárovania oddeľuje hmotnosť nádoby od vloženého obsahu. Výsledok je dostupný priamo na zariadení bez prepojenia s telefónom.</p><p style=\"margin-top:16px\">Tárovanie nastaví východiskový údaj s nádobou na ploche, takže ďalšie odčítanie zodpovedá pridanému obsahu. Displej a tlačidlá sú oddelené od vážiacej časti a zostávajú prístupné aj s vloženým predmetom. Priame digitálne zobrazenie obmedzuje potrebu ručného prepočítavania rozdielu medzi hmotnosťou nádoby a celku.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-012-function-2.jpg\" alt=\"Digitálna vrecková váha s rozlíšením 0,01 g – Vážiaca plocha a digitálne ovládanie\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Vrecková konštrukcia s krytom</h3><p>Nízke telo a priehľadný kryt chránia vážiacu plochu pri uložení. Váha tvorí samostatné prenosné meradlo na drobné predmety a súčiastky. Kompaktná konštrukcia spája plochu, displej a ovládanie do jedného celku.</p><p style=\"margin-top:16px\">Kryt prekrýva pracovnú plochu pri prenášaní a pomáha ju oddeliť od ostatných uložených predmetov. Po otvorení je prístupná vážiaca časť aj panel s odčítaním. Samostatné vyhotovenie spája merací mechanizmus, napájanie a displej do prístroja, ktorý možno uložiť bez ďalšej zobrazovacej jednotky.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-012-function-3.jpg\" alt=\"Digitálna vrecková váha s rozlíšením 0,01 g – Vrecková konštrukcia s krytom\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Měřicí technika a nářadí","Kategória:","Meracia technika a náradie"],["Kategorie:","Měřicí technika a nářadí","Kategória:","Meracia technika a náradie"],["Rozlišení:","0,01 g","Rozlíšenie:","0,01 g"],["Typ produktu:","Digitální kapesní váha","Typ produktu:","Digitálna vrecková váha"],["Rozlišení zobrazení:","0,01 g","Rozlíšenie zobrazenia:","0,01 g"],["Měřená veličina:","Hmotnost","Meraná veličina:","Hmotnosť"],["Zobrazení:","Digitální","Zobrazenie:","Digitálne"],["Provedení:","Přenosné","Vyhotovenie:","Prenosné"],["Určení:","Vážení drobných předmětů","Určenie:","Váženie drobných predmetov"]],"catalog_names":{"Digitální kapesní váha 0,01 g":"Digitálna vrecková váha 0,01 g","Digitální kapesní váha s rozlišením 0,01 g":"Digitálna vrecková váha s rozlíšením 0,01 g"},"catalog_short_cs":"Když vážíte drobné předměty, i malý rozdíl může být důležitý. Kapesní digitální váha s rozlišením 0,01 g se hodí pro jemné součástky, sběratelské materiály a další úlohy, při kterých potřebujete přehledný číselný odečet. Kompaktní provedení snadno uložíte do pracovní výbavy a připravíte tam, kde právě pracujete. Pro použitelný výsledek ji položte na rovnou stabilní plochu a dodržujte limity konkrétní varianty. Rozlišení displeje přitom rozlišujte od skutečné přesnosti měření. Digitální odečet pomáhá porovnávat lehké předměty bez odhadování polohy mechanické stupnice. Krok 0,01 g umožňuje jemné zobrazení výsledku, sám ale nevyjadřuje maximální chybu měření.","catalog_short_t":"Keď vážite drobné predmety, aj malý rozdiel môže byť dôležitý. Vrecková digitálna váha s rozlíšením 0,01 g sa hodí na jemné súčiastky, zberateľské materiály a ďalšie úlohy, pri ktorých potrebujete prehľadné číselné odčítanie. Kompaktné vyhotovenie ľahko uložíte do pracovnej výbavy a pripravíte tam, kde práve pracujete. Na použiteľný výsledok ju položte na rovnú stabilnú plochu a dodržiavajte limity konkrétneho variantu. Rozlíšenie displeja pritom odlišujte od skutočnej presnosti merania. Digitálne odčítanie pomáha porovnávať ľahké predmety bez odhadovania polohy mechanickej stupnice. Krok 0,01 g umožňuje jemné zobrazenie výsledku, sám však nevyjadruje maximálnu chybu merania."},{"code":"OKL-013","name_cs":"Laserový dálkoměr pro digitální měření","name_t":"Laserový diaľkomer na digitálne meranie","short_cs_text":"Dálkoměr určuje vzdálenost pomocí laserového měřicího systému. Číselný výsledek zobrazuje přímo na obrazovce přístroje. Samostatné měření usnadňuje získání délkového údaje bez rozvíjení měřicí pásky přes celý prostor. Čelní panel sdružuje obrazovku a fyzická tlačítka pro dostupné režimy. Jednotlivé hodnoty jsou přístupné přímo na přístroji. Konstrukce měřidla je přizpůsobena ručnímu používání a rychlému odečtení výsledku. Laserová optika, elektronika a napájení jsou umístěny v jednom přenosném těle. Zadní část zahrnuje prostor pro baterie. Přístroj slouží pro digitální měření vzdáleností v rozsahu konkrétní dodané varianty.","short_t_text":"Diaľkomer určuje vzdialenosť pomocou laserového meracieho systému. Číselný výsledok zobrazuje priamo na obrazovke prístroja. Samostatné meranie uľahčuje získanie údaja o dĺžke bez rozvíjania meracieho pásma cez celý priestor. Čelný panel združuje obrazovku a fyzické tlačidlá pre dostupné režimy. Jednotlivé hodnoty sú prístupné priamo na prístroji. Konštrukcia meradla je prispôsobená ručnému používaniu a rýchlemu odčítaniu výsledku. Laserová optika, elektronika a napájanie sú umiestnené v jednom prenosnom tele. Zadná časť zahŕňa priestor na batérie. Prístroj slúži na digitálne meranie vzdialeností v rozsahu konkrétneho dodaného variantu.","short_t_html":"\n                            Diaľkomer určuje vzdialenosť pomocou laserového meracieho systému. Číselný výsledok zobrazuje priamo na obrazovke prístroja. Samostatné meranie uľahčuje získanie údaja o dĺžke bez rozvíjania meracieho pásma cez celý priestor. Čelný panel združuje obrazovku a fyzické tlačidlá pre dostupné režimy. Jednotlivé hodnoty sú prístupné priamo na prístroji. Konštrukcia meradla je prispôsobená ručnému používaniu a rýchlemu odčítaniu výsledku. Laserová optika, elektronika a napájanie sú umiestnené v jednom prenosnom tele. Zadná časť zahŕňa priestor na batérie. Prístroj slúži na digitálne meranie vzdialeností v rozsahu konkrétneho dodaného variantu.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Laserový diaľkomer na digitálne meranie</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Laserový princíp merania</h3><p>Diaľkomer určuje vzdialenosť pomocou laserového meracieho systému. Číselný výsledok zobrazuje priamo na obrazovke prístroja. Samostatné meranie uľahčuje získanie údaja o dĺžke bez rozvíjania meracieho pásma cez celý priestor.</p><p style=\"margin-top:16px\">Optické meranie spája zameranie sledovaného povrchu s elektronickým vyhodnotením vzdialenosti. Výstupom je číselný údaj, ktorý možno okamžite odčítať. Výsledok sa vzťahuje na meranú dráhu a na referenciu nastavenú na prístroji; použiteľnosť konkrétneho merania ovplyvňuje aj charakter povrchu a okolité svetlo.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-013-function-1.jpg\" alt=\"Laserový diaľkomer na digitálne meranie – Laserový princíp merania\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Displej a tlačidlové ovládanie</h3><p>Čelný panel združuje obrazovku a fyzické tlačidlá pre dostupné režimy. Jednotlivé hodnoty sú prístupné priamo na prístroji. Konštrukcia meradla je prispôsobená ručnému používaniu a rýchlemu odčítaniu výsledku.</p><p style=\"margin-top:16px\">Tlačidlový panel oddeľuje spúšťanie merania od čítania výslednej hodnoty. Zvolený režim určuje spôsob práce s dostupnými údajmi podľa funkcií konkrétneho variantu. Samostatná obrazovka ponecháva výsledok priamo pri meradle, takže na základné odčítanie nie je potrebný nadväzujúci telefón ani počítačové rozhranie.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-013-function-2.jpg\" alt=\"Laserový diaľkomer na digitálne meranie – Displej a tlačidlové ovládanie\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Kompaktné telo meradla</h3><p>Laserová optika, elektronika a napájanie sú umiestnené v jednom prenosnom tele. Zadná časť zahŕňa priestor na batérie. Prístroj slúži na digitálne meranie vzdialeností v rozsahu konkrétneho dodaného variantu.</p><p style=\"margin-top:16px\">Prenosná konštrukcia udržiava optickú a elektronickú časť v spoločnom puzdre. Napájanie z batériového priestoru umožňuje samostatný chod prístroja. Merací rozsah a dostupné režimy sú vlastnosťou daného modelu, zatiaľ čo kompaktné telo uľahčuje manipuláciu s celou zostavou pri digitálnom odčítaní vzdialeností.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-013-function-3.jpg\" alt=\"Laserový diaľkomer na digitálne meranie – Kompaktné telo meradla\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Měřicí technika a nářadí","Kategória:","Meracia technika a náradie"],["Kategorie:","Měřicí technika a nářadí","Kategória:","Meracia technika a náradie"],["Typ produktu:","Laserový digitální dálkoměr","Typ produktu:","Laserový digitálny diaľkomer"],["Měřená veličina:","Vzdálenost","Meraná veličina:","Vzdialenosť"],["Princip měření:","Laserový","Princíp merania:","Laserový"],["Zobrazení:","Digitální","Zobrazenie:","Digitálne"],["Typické použití:","Plánování interiéru a dílenské měření","Typické použitie:","Plánovanie interiéru a dielenské meranie"],["Provedení:","Ruční přenosné","Vyhotovenie:","Ručné prenosné"]],"catalog_names":{"Laserový digitální dálkoměr":"Laserový digitálny diaľkomer","Laserový dálkoměr pro digitální měření":"Laserový diaľkomer na digitálne meranie"},"catalog_short_cs":"Změřte vzdálenost bez zdlouhavého natahování pásma přes celou místnost. Laserový digitální dálkoměr se hodí při plánování interiéru, rozmísťování nábytku a běžných měřicích úlohách v domácnosti nebo dílně. Číselný odečet usnadňuje zapisování rozměrů a postupnou kontrolu více míst. Přístroj umístíte podle zvolené referenční hrany a zaměříte vhodný cílový povrch. Pro přesný pracovní postup zohledněte měřicí rozsah, podmínky okolí a funkce konkrétní varianty. Při přípravě nového uspořádání potřebujete rychle získat několik srovnatelných rozměrů. Dálkoměr pomůže změřit podporovanou vzdálenost a přečíst ji digitálně přímo na zařízení.","catalog_short_t":"Zmerajte vzdialenosť bez zdĺhavého naťahovania pásma cez celú miestnosť. Laserový digitálny diaľkomer sa hodí pri plánovaní interiéru, rozmiestňovaní nábytku a bežných meracích úlohách v domácnosti alebo dielni. Číselné odčítanie uľahčuje zapisovanie rozmerov a postupnú kontrolu viacerých miest. Prístroj umiestnite podľa zvolenej referenčnej hrany a zameriate vhodný cieľový povrch. Na presný pracovný postup zohľadnite merací rozsah, podmienky okolia a funkcie konkrétneho variantu. Pri príprave nového usporiadania potrebujete rýchlo získať niekoľko porovnateľných rozmerov. Diaľkomer pomôže zmerať podporovanú vzdialenosť a prečítať ju digitálne priamo na zariadení."},{"code":"OKL-014","name_cs":"Digitální tloušťkoměr pro kontrolu materiálů","name_t":"Digitálny hrúbkomer na kontrolu materiálov","short_cs_text":"Tloušťkoměr měří vzdálenost mezi protilehlými dotykovými plochami. Vložený materiál je sevřen měřicími kontakty a výsledek se zobrazuje digitálně. Konstrukce se hodí pro dostupná místa na plochých vzorcích, nikoli pro bezkontaktní měření povlaku. Samostatný číselný displej umožňuje číst výsledek přímo z měřicí hlavy. Tlačítka doplňují ovládání podporovaných funkcí měřidla. Mechanický rám drží měřicí kontakty v pevně dané vzájemné poloze. Páčka oddaluje pohyblivý kontakt pro vložení vzorku. Otevřený tvar rámu poskytuje přístup k okraji měřeného materiálu. Měřicí hlava a kontaktní části tvoří jeden ruční přístroj pro opakovaný odečet tloušťky.","short_t_text":"Hrúbkomer meria vzdialenosť medzi protiľahlými dotykovými plochami. Vložený materiál je zovretý meracími kontaktmi a výsledok sa zobrazuje digitálne. Konštrukcia sa hodí na dostupné miesta na plochých vzorkách, nie na bezkontaktné meranie povlaku. Samostatný číselný displej umožňuje čítať výsledok priamo z meracej hlavy. Tlačidlá dopĺňajú ovládanie podporovaných funkcií meradla. Mechanický rám drží meracie kontakty v pevne danej vzájomnej polohe. Páčka odďaľuje pohyblivý kontakt na vloženie vzorky. Otvorený tvar rámu poskytuje prístup k okraju meraného materiálu. Meracia hlava a kontaktné časti tvoria jeden ručný prístroj na opakované odčítanie hrúbky.","short_t_html":"\n                            Hrúbkomer meria vzdialenosť medzi protiľahlými dotykovými plochami. Vložený materiál je zovretý meracími kontaktmi a výsledok sa zobrazuje digitálne. Konštrukcia sa hodí na dostupné miesta na plochých vzorkách, nie na bezkontaktné meranie povlaku. Samostatný číselný displej umožňuje čítať výsledok priamo z meracej hlavy. Tlačidlá dopĺňajú ovládanie podporovaných funkcií meradla. Mechanický rám drží meracie kontakty v pevne danej vzájomnej polohe. Páčka odďaľuje pohyblivý kontakt na vloženie vzorky. Otvorený tvar rámu poskytuje prístup k okraju meraného materiálu. Meracia hlava a kontaktné časti tvoria jeden ručný prístroj na opakované odčítanie hrúbky.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Digitálny hrúbkomer na kontrolu materiálov</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Kontaktné meranie hrúbky</h3><p>Hrúbkomer meria vzdialenosť medzi protiľahlými dotykovými plochami. Vložený materiál je zovretý meracími kontaktmi a výsledok sa zobrazuje digitálne. Konštrukcia sa hodí na dostupné miesta na plochých vzorkách, nie na bezkontaktné meranie povlaku.</p><p style=\"margin-top:16px\">Výsledný údaj opisuje celkovú hrúbku vloženej vzorky medzi kontaktmi. Merací princíp vyžaduje prístup k obom protiľahlým stranám materiálu. Otvorená časť rámu určuje, ako ďaleko od okraja možno kontakty priložiť, a mechanické usporiadanie prevádza ich vzájomnú polohu na hodnotu na digitálne odčítanie.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-014-function-1.jpg\" alt=\"Digitálny hrúbkomer na kontrolu materiálov – Kontaktné meranie hrúbky\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Digitálne odčítanie hodnoty</h3><p>Samostatný číselný displej umožňuje čítať výsledok priamo z meracej hlavy. Tlačidlá dopĺňajú ovládanie podporovaných funkcií meradla. Mechanický rám drží meracie kontakty v pevne danej vzájomnej polohe.</p><p style=\"margin-top:16px\">Obrazovka sústreďuje údaj v mieste merania a odstraňuje potrebu odčítať jemné dieliky mechanickej stupnice. Pevná časť a pohyblivý kontakt tvoria základ meracieho usporiadania. Elektronická hlava zobrazuje ich vzdialenosť v podobe dostupnej hodnoty, ktorej rozlíšenie a rozsah vychádzajú z konkrétneho modelu.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-014-function-2.jpg\" alt=\"Digitálny hrúbkomer na kontrolu materiálov – Digitálne odčítanie hodnoty\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Rám s ovládacou páčkou</h3><p>Páčka odďaľuje pohyblivý kontakt na vloženie vzorky. Otvorený tvar rámu poskytuje prístup k okraju meraného materiálu. Meracia hlava a kontaktné časti tvoria jeden ručný prístroj na opakované odčítanie hrúbky.</p><p style=\"margin-top:16px\">Ovládacia páčka poskytuje priamy prístup k roztvoreniu meracieho priestoru. Po vložení vzorky sa kontakty opierajú o jej protiľahlé povrchy a vzniká podklad na odčítanie. Konštrukcia rámu zachováva vzájomné vedenie meracích častí, čo je podstatné najmä pri porovnávaní hrúbky viacerých drobných vzoriek.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-014-function-3.jpg\" alt=\"Digitálny hrúbkomer na kontrolu materiálov – Rám s ovládacou páčkou\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Měřicí technika a nářadí","Kategória:","Meracia technika a náradie"],["Kategorie:","Měřicí technika a nářadí","Kategória:","Meracia technika a náradie"],["Typ produktu:","Digitální tloušťkoměr","Typ produktu:","Digitálny hrúbkomer"],["Měřená veličina:","Tloušťka","Meraná veličina:","Hrúbka"],["Zobrazení:","Digitální","Zobrazenie:","Digitálne"],["Typické použití:","Kontrola vhodných materiálů a dílů","Typické použitie:","Kontrola vhodných materiálov a dielov"],["Provedení:","Ruční měřidlo","Vyhotovenie:","Ručné meradlo"],["Volba měřidla:","Podle materiálu a měřicího principu","Výber meradla:","Podľa materiálu a meracieho princípu"]],"catalog_names":{"Digitální tloušťkoměr pro měření materiálů":"Digitálny hrúbkomer na meranie materiálov","Digitální tloušťkoměr pro kontrolu materiálů":"Digitálny hrúbkomer na kontrolu materiálov"},"catalog_short_cs":"Získejte přehledný číselný odečet při kontrole tloušťky vhodných materiálů a drobných dílů. Digitální tloušťkoměr je praktickou součástí technické výbavy pro porovnávání vzorků, kontrolu rozměrů a opakované měřicí úlohy. Místo odhadu na stupnici pracujete s digitálně zobrazenou hodnotou. Správný výsledek závisí na vhodnosti měřidla pro daný materiál, čistotě měřicích ploch a správném usazení vzorku. Před prací ověřte rozsah a konstrukci konkrétní varianty. Když porovnáváte několik vzorků, číselné zobrazení usnadní zápis a hledání rozdílů. Tloušťkoměr může tvořit součást stálého pracovního postupu, při kterém měříte vždy na stejném místě a za stejných podmínek.","catalog_short_t":"Získajte prehľadné číselné odčítanie pri kontrole hrúbky vhodných materiálov a drobných dielov. Digitálny hrúbkomer je praktickou súčasťou technickej výbavy na porovnávanie vzoriek, kontrolu rozmerov a opakované meracie úlohy. Namiesto odhadu na stupnici pracujete s digitálne zobrazenou hodnotou. Správny výsledok závisí od vhodnosti meradla pre daný materiál, čistoty meracích plôch a správneho usadenia vzorky. Pred prácou overte rozsah a konštrukciu konkrétneho variantu. Keď porovnávate niekoľko vzoriek, číselné zobrazenie uľahčí zápis a hľadanie rozdielov. Hrúbkomer môže tvoriť súčasť stáleho pracovného postupu, pri ktorom meriate vždy na rovnakom mieste a za rovnakých podmienok."},{"code":"OKL-015","name_cs":"USB digitální mikroskop pro detailní pozorování","name_t":"USB digitálny mikroskop na detailné pozorovanie","short_cs_text":"Mikroskop převádí obraz z blízkosti objektivu do digitální podoby. Zvětšené zobrazení slouží k pozorování povrchů, součástek a jemných struktur. Výsledný obraz lze sledovat na kompatibilním připojeném zařízení. Světelné prvky v okolí objektivu osvětlují pozorované místo z malé vzdálenosti. Zaostřovací ovladač přizpůsobuje obraz poloze vzorku. Optika a snímací elektronika jsou soustředěny do kompaktní válcové části. Součástí provedení je polohovatelný držák se základnou. Podpírá mikroskop při detailním pozorování a ponechává prostor pod objektivem. USB propojení slouží pro podporované připojení k zařízení a napájení podle konkrétní konfigurace.","short_t_text":"Mikroskop prevádza obraz z blízkosti objektívu do digitálnej podoby. Zväčšené zobrazenie slúži na pozorovanie povrchov, súčiastok a jemných štruktúr. Výsledný obraz možno sledovať na kompatibilnom pripojenom zariadení. Svetelné prvky v okolí objektívu osvetľujú pozorované miesto z malej vzdialenosti. Zaostrovací ovládač prispôsobuje obraz polohe vzorky. Optika a snímacia elektronika sú sústredené do kompaktnej valcovej časti. Súčasťou vyhotovenia je polohovateľný držiak so základňou. Podopiera mikroskop pri detailnom pozorovaní a ponecháva priestor pod objektívom. USB prepojenie slúži na podporované pripojenie k zariadeniu a napájanie podľa konkrétnej konfigurácie.","short_t_html":"\n                            Mikroskop prevádza obraz z blízkosti objektívu do digitálnej podoby. Zväčšené zobrazenie slúži na pozorovanie povrchov, súčiastok a jemných štruktúr. Výsledný obraz možno sledovať na kompatibilnom pripojenom zariadení. Svetelné prvky v okolí objektívu osvetľujú pozorované miesto z malej vzdialenosti. Zaostrovací ovládač prispôsobuje obraz polohe vzorky. Optika a snímacia elektronika sú sústredené do kompaktnej valcovej časti. Súčasťou vyhotovenia je polohovateľný držiak so základňou. Podopiera mikroskop pri detailnom pozorovaní a ponecháva priestor pod objektívom. USB prepojenie slúži na podporované pripojenie k zariadeniu a napájanie podľa konkrétnej konfigurácie.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>USB digitálny mikroskop na detailné pozorovanie</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Digitálny obraz drobných detailov</h3><p>Mikroskop prevádza obraz z blízkosti objektívu do digitálnej podoby. Zväčšené zobrazenie slúži na pozorovanie povrchov, súčiastok a jemných štruktúr. Výsledný obraz možno sledovať na kompatibilnom pripojenom zariadení.</p><p style=\"margin-top:16px\">Snímacia časť zachytáva malú oblasť pred objektívom a prevádza ju na obraz dostupný v podporovanom softvéri. Zobrazenie prepája optické priblíženie s možnosťami pripojenej obrazovky. Pozorovateľný detail ovplyvňuje zaostrenie, vzdialenosť vzorky a rozlíšenie celej snímacej zostavy, nie iba veľkosť obrazu na displeji.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-015-function-1.jpg\" alt=\"USB digitálny mikroskop na detailné pozorovanie – Digitálny obraz drobných detailov\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Osvetlenie pri objektíve</h3><p>Svetelné prvky v okolí objektívu osvetľujú pozorované miesto z malej vzdialenosti. Zaostrovací ovládač prispôsobuje obraz polohe vzorky. Optika a snímacia elektronika sú sústredené do kompaktnej valcovej časti.</p><p style=\"margin-top:16px\">Svetlo umiestnené blízko optickej osi pomáha zobraziť jemnú štruktúru povrchu v zornom poli. Zaostrovacia časť upravuje ostrosť pre aktuálnu polohu pozorovaného predmetu. Zmena vzdialenosti a osvetlenia ovplyvňuje podobu detailu aj odleskov, ktoré sa pri sledovaní lesklých súčiastok objavujú v digitálnom obraze.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-015-function-2.jpg\" alt=\"USB digitálny mikroskop na detailné pozorovanie – Osvetlenie pri objektíve\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Stojanček na stabilné pozorovanie</h3><p>Súčasťou vyhotovenia je polohovateľný držiak so základňou. Podopiera mikroskop pri detailnom pozorovaní a ponecháva priestor pod objektívom. USB prepojenie slúži na podporované pripojenie k zariadeniu a napájanie podľa konkrétnej konfigurácie.</p><p style=\"margin-top:16px\">Držiak obmedzuje pohyb snímacej časti voči pozorovanému predmetu a umožňuje udržať zvolený pohľad. Základňa vytvára oporu celej zostavy, zatiaľ čo pracovný priestor zostáva pod objektívom. Káblové prepojenie prenáša obraz do podporovaného softvéru, ktorý sprístupňuje funkcie zodpovedajúce konkrétnemu systému a vyhotoveniu mikroskopu.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-015-function-3.jpg\" alt=\"USB digitálny mikroskop na detailné pozorovanie – Stojanček na stabilné pozorovanie\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Měřicí technika a nářadí","Kategória:","Meracia technika a náradie"],["Kategorie:","Měřicí technika a nářadí","Kategória:","Meracia technika a náradie"],["Typ produktu:","Digitální mikroskop","Typ produktu:","Digitálny mikroskop"],["Zobrazení:","Digitální obraz","Zobrazenie:","Digitálny obraz"],["Rozhraní:","USB podle varianty","Rozhranie:","USB podľa variantu"],["Určení:","Pozorování drobných objektů a povrchů","Určenie:","Pozorovanie drobných objektov a povrchov"],["Typické objekty:","Elektronika, mince a vzorky materiálů","Typické objekty:","Elektronika, mince a vzorky materiálov"],["Způsob práce:","Zaostření na stabilně umístěný objekt","Spôsob práce:","Zaostrenie na stabilne umiestnený objekt"]],"catalog_names":{"USB digitální mikroskop s displejem":"USB digitálny mikroskop s displejom","USB digitální mikroskop pro detailní pozorování":"USB digitálny mikroskop na detailné pozorovanie"},"catalog_short_cs":"Podívejte se blíž na elektronické součástky, strukturu povrchů, mince a další drobné objekty. Digitální mikroskop pomáhá zobrazit detaily, které při běžném pohledu snadno přehlédnete. Využijete ho při domácím poznávání, kontrole předmětů i drobné servisní práci. O výsledku rozhoduje správné zaostření, stabilní uchycení a vhodné osvětlení. Způsob zobrazení na displeji nebo připojeném zařízení se řídí konkrétní variantou a kompatibilním softwarem. Při prohlížení malého objektu nejprve vyberte místo, které chcete sledovat, a nastavte takovou vzdálenost, aby se dalo pohodlně zaostřit. Digitální zobrazení umožní pozorovat strukturu a porovnat jednotlivé části předmětu.","catalog_short_t":"Pozrite sa bližšie na elektronické súčiastky, štruktúru povrchov, mince a ďalšie drobné objekty. Digitálny mikroskop pomáha zobraziť detaily, ktoré pri bežnom pohľade ľahko prehliadnete. Využijete ho pri domácom objavovaní, kontrole predmetov aj drobnej servisnej práci. O výsledku rozhoduje správne zaostrenie, stabilné uchytenie a vhodné osvetlenie. Spôsob zobrazenia na displeji alebo pripojenom zariadení sa riadi konkrétnym variantom a kompatibilným softvérom. Pri prezeraní malého objektu najprv vyberte miesto, ktoré chcete sledovať, a nastavte takú vzdialenosť, aby sa dalo pohodlne zaostriť. Digitálne zobrazenie umožní pozorovať štruktúru a porovnať jednotlivé časti predmetu."},{"code":"OKL-016","name_cs":"Elektrický precizní šroubovák – servisní sada","name_t":"Elektrický precízny skrutkovač – servisná sada","short_cs_text":"Šroubovák používá kompaktní motorové provedení v úzkém těle. Dvojice tlačítek ovládá směr otáčení při šroubování a povolování. Nástroj je určen pro drobné šroubové spoje v elektronice a podobných mechanismech. Sada obsahuje výměnné precizní bity uložené v organizéru. Jejich výměna přizpůsobuje pracovní konec jednotlivým typům šroubů. Válcové tělo nabízí přímý úchop blízko osy šroubování. Nástroj a drobné součásti mají vlastní místa v přenosném pouzdře. Uspořádání drží příslušenství pohromadě při práci i uložení. Nabíjecí provedení omezuje potřebu vést při samotném šroubování napájecí kabel k ruce.","short_t_text":"Skrutkovač využíva kompaktné motorové vyhotovenie v úzkom tele. Dvojica tlačidiel ovláda smer otáčania pri skrutkovaní a povoľovaní. Nástroj je určený na drobné skrutkové spoje v elektronike a podobných mechanizmoch. Sada obsahuje vymeniteľné precízne bity uložené v organizéri. Ich výmena prispôsobuje pracovný koniec jednotlivým typom skrutiek. Valcové telo ponúka priamy úchop blízko osi skrutkovania. Nástroj a drobné súčasti majú vlastné miesta v prenosnom puzdre. Usporiadanie drží príslušenstvo pohromade pri práci aj uložení. Nabíjacie vyhotovenie obmedzuje potrebu viesť pri samotnom skrutkovaní napájací kábel k ruke.","short_t_html":"\n                            Skrutkovač využíva kompaktné motorové vyhotovenie v úzkom tele. Dvojica tlačidiel ovláda smer otáčania pri skrutkovaní a povoľovaní. Nástroj je určený na drobné skrutkové spoje v elektronike a podobných mechanizmoch. Sada obsahuje vymeniteľné precízne bity uložené v organizéri. Ich výmena prispôsobuje pracovný koniec jednotlivým typom skrutiek. Valcové telo ponúka priamy úchop blízko osi skrutkovania. Nástroj a drobné súčasti majú vlastné miesta v prenosnom puzdre. Usporiadanie drží príslušenstvo pohromade pri práci aj uložení. Nabíjacie vyhotovenie obmedzuje potrebu viesť pri samotnom skrutkovaní napájací kábel k ruke.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Elektrický precízny skrutkovač – servisná sada</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Elektrický pohon v precíznom pere</h3><p>Skrutkovač využíva kompaktné motorové vyhotovenie v úzkom tele. Dvojica tlačidiel ovláda smer otáčania pri skrutkovaní a povoľovaní. Nástroj je určený na drobné skrutkové spoje v elektronike a podobných mechanizmoch.</p><p style=\"margin-top:16px\">Motor prenáša otáčanie na nasadený bit a zabezpečuje opakovaný pohyb bez neustáleho otáčania celej rukoväte. Prepínanie smeru rozlišuje uťahovanie a povoľovanie spoja. Úzky profil nástroja sústreďuje ovládanie do jednej ruky a približuje úchop k pracovnému miestu v drobných elektronických zostavách.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-016-function-1.jpg\" alt=\"Elektrický precízny skrutkovač – servisná sada – Elektrický pohon v precíznom pere\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Vymeniteľné bity pre malé spoje</h3><p>Sada obsahuje vymeniteľné precízne bity uložené v organizéri. Ich výmena prispôsobuje pracovný koniec jednotlivým typom skrutiek. Valcové telo ponúka priamy úchop blízko osi skrutkovania.</p><p style=\"margin-top:16px\">Pracovný profil bitu vytvára spojenie medzi pohonom a hlavou skrutky. Vymeniteľné vyhotovenie umožňuje ponechať rovnakú rukoväť a meniť iba koncovú časť nástroja. Organizér oddeľuje jednotlivé bity do samostatných pozícií, takže ich tvary zostávajú prehľadné aj pri práci s väčším počtom malých spojov.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-016-function-2.jpg\" alt=\"Elektrický precízny skrutkovač – servisná sada – Vymeniteľné bity pre malé spoje\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Puzdro s usporiadaným príslušenstvom</h3><p>Nástroj a drobné súčasti majú vlastné miesta v prenosnom puzdre. Usporiadanie drží príslušenstvo pohromade pri práci aj uložení. Nabíjacie vyhotovenie obmedzuje potrebu viesť pri samotnom skrutkovaní napájací kábel k ruke.</p><p style=\"margin-top:16px\">Samostatné pozície v puzdre pomáhajú oddeliť bity od tela skrutkovača a obmedzujú ich voľný pohyb pri prenášaní. Celá sada zostáva uložená v jednom celku. Napájanie vstavaného pohonu je oddelené od okamihu skrutkovania, čo ponecháva pracovnú rukoväť počas manipulácie bez pripojeného kábla.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-016-function-3.jpg\" alt=\"Elektrický precízny skrutkovač – servisná sada – Puzdro s usporiadaným príslušenstvom\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Měřicí technika a nářadí","Kategória:","Meracia technika a náradie"],["Kategorie:","Měřicí technika a nářadí","Kategória:","Meracia technika a náradie"],["Typ produktu:","Elektrický precizní šroubovák","Typ produktu:","Elektrický precízny skrutkovač"],["Provedení:","Servisní sada","Vyhotovenie:","Servisná sada"],["Pohon:","Elektrický","Pohon:","Elektrický"],["Určení:","Drobné šroubové spoje","Určenie:","Drobné skrutkové spoje"],["Typické použití:","Servis a sestavování elektroniky","Typické použitie:","Servis a zostavovanie elektroniky"],["Pracovní nástroj:","Kompatibilní výměnný bit","Pracovný nástroj:","Kompatibilný vymeniteľný bit"]],"catalog_names":{"Elektrický precizní šroubovák servisní sada":"Elektrický precízny skrutkovač servisná sada","Elektrický precizní šroubovák – servisní sada":"Elektrický precízny skrutkovač – servisná sada"},"catalog_short_cs":"Zpříjemněte si práci s drobnými šrouby při sestavování a opravách elektroniky. Elektrický precizní šroubovák pomáhá při opakovaném šroubování a servisní sada poskytuje základ pro práci s podporovanými spoji. Uplatní se na pracovním stole hobby opraváře i při rozebírání vlastních zařízení. Správně zvolený bit, malý přítlak a kontrolované dotažení jsou důležitější než rychlost práce. Před použitím ověřte velikost a typ šroubu i možnosti konkrétního nástroje. Při rozebírání krytu nebo montáži menších částí se stejný pohyb opakuje mnohokrát. Elektrický pohon může tuto část práce usnadnit a pomoci zachovat plynulý postup.","catalog_short_t":"Spríjemnite si prácu s drobnými skrutkami pri zostavovaní a opravách elektroniky. Elektrický precízny skrutkovač pomáha pri opakovanom skrutkovaní a servisná sada poskytuje základ na prácu s podporovanými spojmi. Uplatní sa na pracovnom stole hobby opravára aj pri rozoberaní vlastných zariadení. Správne zvolený bit, malý prítlak a kontrolované dotiahnutie sú dôležitejšie ako rýchlosť práce. Pred použitím overte veľkosť a typ skrutky aj možnosti konkrétneho nástroja. Pri rozoberaní krytu alebo montáži menších častí sa rovnaký pohyb opakuje mnohokrát. Elektrický pohon môže túto časť práce uľahčiť a pomôcť zachovať plynulý postup."},{"code":"OKL-017","name_cs":"Kompaktní USB-C páječka pro elektroniku","name_t":"Kompaktná USB-C spájkovačka na elektroniku","short_cs_text":"Úzké tělo soustředí topnou část, ovládání a napájecí elektroniku do přenosného nástroje. Hrot přivádí teplo přímo na pájený spoj. USB-C připojení doplňuje napájecí řešení této kompaktní páječky. Tlačítka a indikační prvky jsou umístěny na horní straně pera. Podporované nastavení je dostupné bez samostatné velké stanice. Tvar rukojeti umožňuje vést hrot při práci s drobnými elektronickými spoji. Úzký pracovní hrot je doplněn odkládacím příslušenstvím podle vyobrazeného provedení. Přenosný formát sdružuje potřebné části do malé sestavy. Nástroj je zaměřen na drobné pájení elektroniky a jemné pracovní spoje.","short_t_text":"Úzke telo sústreďuje vyhrievaciu časť, ovládanie a napájaciu elektroniku do prenosného nástroja. Hrot privádza teplo priamo na spájkovaný spoj. USB-C pripojenie dopĺňa napájacie riešenie tejto kompaktnej spájkovačky. Tlačidlá a indikačné prvky sú umiestnené na hornej strane pera. Podporované nastavenie je dostupné bez samostatnej veľkej stanice. Tvar rukoväte umožňuje viesť hrot pri práci s drobnými elektronickými spojmi. Úzky pracovný hrot je doplnený odkladacím príslušenstvom podľa zobrazeného vyhotovenia. Prenosný formát združuje potrebné časti do malej zostavy. Nástroj je zameraný na drobné spájkovanie elektroniky a jemné pracovné spoje.","short_t_html":"\n                            Úzke telo sústreďuje vyhrievaciu časť, ovládanie a napájaciu elektroniku do prenosného nástroja. Hrot privádza teplo priamo na spájkovaný spoj. USB-C pripojenie dopĺňa napájacie riešenie tejto kompaktnej spájkovačky. Tlačidlá a indikačné prvky sú umiestnené na hornej strane pera. Podporované nastavenie je dostupné bez samostatnej veľkej stanice. Tvar rukoväte umožňuje viesť hrot pri práci s drobnými elektronickými spojmi. Úzky pracovný hrot je doplnený odkladacím príslušenstvom podľa zobrazeného vyhotovenia. Prenosný formát združuje potrebné časti do malej zostavy. Nástroj je zameraný na drobné spájkovanie elektroniky a jemné pracovné spoje.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Kompaktná USB-C spájkovačka na elektroniku</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Kompaktné spájkovacie pero</h3><p>Úzke telo sústreďuje vyhrievaciu časť, ovládanie a napájaciu elektroniku do prenosného nástroja. Hrot privádza teplo priamo na spájkovaný spoj. USB-C pripojenie dopĺňa napájacie riešenie tejto kompaktnej spájkovačky.</p><p style=\"margin-top:16px\">Spájkovací hrot tvorí pracovné rozhranie medzi vyhrievacou časťou nástroja a spájanými miestami. Teplo prenesené do spoja umožňuje prácu so spájkou na drobných vodičoch a elektronických vývodoch. Konektor USB-C privádza napájanie, ktorého požiadavky sa riadia konkrétnym vyhotovením spájkovačky a použitým zdrojom.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-017-function-1.jpg\" alt=\"Kompaktná USB-C spájkovačka na elektroniku – Kompaktné spájkovacie pero\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Ilustračné zobrazenie funkcie</figcaption></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Ovládanie na tele nástroja</h3><p>Tlačidlá a indikačné prvky sú umiestnené na hornej strane pera. Podporované nastavenie je dostupné bez samostatnej veľkej stanice. Tvar rukoväte umožňuje viesť hrot pri práci s drobnými elektronickými spojmi.</p><p style=\"margin-top:16px\">Umiestnenie ovládacích prvkov priamo pri rukoväti sústreďuje dostupné nastavenia do samotného nástroja. Indikácia odovzdáva informácie o podporovanom prevádzkovom stave. Spájkovacie pero tak spája pracovný hrot a ovládanie v jednej prenosnej časti, pričom zdroj a prívodný kábel tvoria nadväzujúcu napájaciu zostavu.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-017-function-2.jpg\" alt=\"Kompaktná USB-C spájkovačka na elektroniku – Ovládanie na tele nástroja\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Hrot a odkladacie príslušenstvo</h3><p>Úzky pracovný hrot je doplnený odkladacím príslušenstvom podľa zobrazeného vyhotovenia. Prenosný formát združuje potrebné časti do malej zostavy. Nástroj je zameraný na drobné spájkovanie elektroniky a jemné pracovné spoje.</p><p style=\"margin-top:16px\">Tvar hrotu sústreďuje prenos tepla na obmedzenú pracovnú plochu. Odkladacia časť poskytuje vyhradenú oporu pre nástroj medzi jednotlivými spojmi. Celkové usporiadanie zostavy vychádza z kompaktného formátu pera, ktorý ponecháva vyhrievaciu časť priamo pri ruke a napájanie privádza cez pripojený kábel.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-017-function-3.jpg\" alt=\"Kompaktná USB-C spájkovačka na elektroniku – Hrot a odkladacie príslušenstvo\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Ilustračné zobrazenie funkcie</figcaption></figure></section></article>\n                            ","params":[["Kategorie:","Měřicí technika a nářadí","Kategória:","Meracia technika a náradie"],["Kategorie:","Měřicí technika a nářadí","Kategória:","Meracia technika a náradie"],["Připojení:","USB C","Pripojenie:","USB C"],["Typ produktu:","Kompaktní páječka","Typ produktu:","Kompaktná spájkovačka"],["Rozhraní:","USB-C","Rozhranie:","USB-C"],["Určení:","Pájení elektroniky","Určenie:","Spájkovanie elektroniky"],["Pracovní část:","Pájecí hrot","Pracovná časť:","Spájkovací hrot"],["Typické použití:","Vlastní projekty a drobný servis","Typické použitie:","Vlastné projekty a drobný servis"],["Pracovní prostředí:","Bezpečně připravené pracoviště","Pracovné prostredie:","Bezpečne pripravené pracovisko"]],"catalog_names":{"Kompaktní USB C páječka":"Kompaktná USB C spájkovačka","Kompaktní USB-C páječka pro elektroniku":"Kompaktná USB-C spájkovačka na elektroniku"},"catalog_short_cs":"Připravte si kompaktní nástroj pro drobné pájení při stavbě a opravách elektroniky. USB-C páječka se snadno zařadí do vývojářské nebo servisní výbavy a nezabere místo jako velká stolní stanice. Hodí se pro uživatele, kteří chtějí pracovat na vlastních projektech s odpovídajícím napájením a bezpečně připravenou plochou. Konkrétní výkon, hrot a teplotní režimy se řídí dodávanou variantou. Samotný konektor USB-C neurčuje požadavky na napájecí zdroj. Páječku využijete u menších zapojení a servisních úloh, kterým odpovídá její výkon i použitý hrot. Před prací připravte pevný držák, nehořlavou podložku a vhodné větrání.","catalog_short_t":"Pripravte si kompaktný nástroj na drobné spájkovanie pri stavbe a opravách elektroniky. USB-C spájkovačka sa ľahko zaradí do vývojárskej alebo servisnej výbavy a nezaberie miesto ako veľká stolová stanica. Hodí sa pre používateľov, ktorí chcú pracovať na vlastných projektoch s primeraným napájaním a bezpečne pripravenou plochou. Konkrétny výkon, hrot a teplotné režimy sa riadia dodávaným variantom. Samotný konektor USB-C neurčuje požiadavky na napájací zdroj. Spájkovačku využijete pri menších zapojeniach a servisných úlohách, ktorým zodpovedá jej výkon aj použitý hrot. Pred prácou pripravte pevný držiak, nehorľavú podložku a vhodné vetranie."},{"code":"OKL-018","name_cs":"Kapesní digitální osciloskop pro měření signálů","name_t":"Vreckový digitálny osciloskop na meranie signálov","short_cs_text":"Kapesní osciloskop zobrazuje změnu elektrického signálu v čase. Obrazovka kombinuje vykreslený průběh s hodnotami podporovaných měřicích funkcí. Zařízení slouží pro orientaci v signálu, jeho periodě a tvaru při výuce i hobby elektronice. Fyzická tlačítka jsou umístěna vedle displeje pro přístup k měřicím nastavením. Naměřený průběh je dostupný bez notebooku. Kompaktní provedení spojuje vstup měření, zpracování a zobrazení do jednoho přístroje. Výklopná opěra usnadňuje stolní odečet obrazovky. Měřicí vedení připojuje osciloskop k testovanému bodu. Nabíjecí provedení a malé tělo doplňují přenosné použití v rozsahu podporovaného vstupu.","short_t_text":"Vreckový osciloskop zobrazuje zmenu elektrického signálu v čase. Obrazovka kombinuje vykreslený priebeh s hodnotami podporovaných meracích funkcií. Zariadenie slúži na orientáciu v signáli, jeho perióde a tvare pri výučbe aj v hobby elektronike. Fyzické tlačidlá sú umiestnené vedľa displeja a sprístupňujú nastavenia merania. Nameraný priebeh je dostupný bez notebooku. Kompaktné vyhotovenie spája vstup merania, spracovanie a zobrazenie do jedného prístroja. Výklopná opierka uľahčuje odčítanie z obrazovky na stole. Meracie vedenie pripája osciloskop k testovanému bodu. Nabíjateľné vyhotovenie a malé telo dopĺňajú prenosné použitie v rozsahu podporovaného vstupu.","short_t_html":"\n                            Vreckový osciloskop zobrazuje zmenu elektrického signálu v čase. Obrazovka kombinuje vykreslený priebeh s hodnotami podporovaných meracích funkcií. Zariadenie slúži na orientáciu v signáli, jeho perióde a tvare pri výučbe aj v hobby elektronike. Fyzické tlačidlá sú umiestnené vedľa displeja a sprístupňujú nastavenia merania. Nameraný priebeh je dostupný bez notebooku. Kompaktné vyhotovenie spája vstup merania, spracovanie a zobrazenie do jedného prístroja. Výklopná opierka uľahčuje odčítanie z obrazovky na stole. Meracie vedenie pripája osciloskop k testovanému bodu. Nabíjateľné vyhotovenie a malé telo dopĺňajú prenosné použitie v rozsahu podporovaného vstupu.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Vreckový digitálny osciloskop na meranie signálov</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Priebeh signálu priamo na obrazovke</h3><p>Vreckový osciloskop zobrazuje zmenu elektrického signálu v čase. Obrazovka kombinuje vykreslený priebeh s hodnotami podporovaných meracích funkcií. Zariadenie slúži na orientáciu v signáli, jeho perióde a tvare pri výučbe aj v hobby elektronike.</p><p style=\"margin-top:16px\">Vodorovná os obrazu predstavuje časový priebeh, zvislá zasa zodpovedá zmene sledovanej elektrickej veličiny. Tvar krivky ukazuje opakovanie, impulzy alebo zmeny úrovne v rámci možností prístroja. Zobrazený výsledok závisí od nastavenia časovej základne, citlivosti vstupu a vlastností meraného signálu.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-018-function-1.jpg\" alt=\"Vreckový digitálny osciloskop na meranie signálov – Priebeh signálu priamo na obrazovke\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Ovládanie samostatného meradla</h3><p>Fyzické tlačidlá sú umiestnené vedľa displeja a sprístupňujú nastavenia merania. Nameraný priebeh je dostupný bez notebooku. Kompaktné vyhotovenie spája vstup merania, spracovanie a zobrazenie do jedného prístroja.</p><p style=\"margin-top:16px\">Nastavenie merania určuje, akú časť signálu obrazovka vykreslí a v akej mierke. Fyzické ovládacie prvky sprístupňujú podporované zmeny priamo pri zobrazenej krivke. Samostatná elektronika prepája snímanie a spracovanie so zobrazovacou časťou, takže základný prehľad o signáli vzniká priamo v prístroji.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-018-function-2.jpg\" alt=\"Vreckový digitálny osciloskop na meranie signálov – Ovládanie samostatného meradla\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Stojanček a prenosná konštrukcia</h3><p>Výklopná opierka uľahčuje odčítanie z obrazovky na stole. Meracie vedenie pripája osciloskop k testovanému bodu. Nabíjateľné vyhotovenie a malé telo dopĺňajú prenosné použitie v rozsahu podporovaného vstupu.</p><p style=\"margin-top:16px\">Opierka udržiava obrazovku v naklonenej polohe a umožňuje čítať priebeh bez držania prístroja v ruke. Sonda a vedenie tvoria elektrickú cestu medzi vstupom a sledovaným obvodom. Prípustné napätie, frekvenčný rozsah a spôsob pripojenia vychádzajú z parametrov konkrétneho variantu osciloskopu.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-018-function-3.jpg\" alt=\"Vreckový digitálny osciloskop na meranie signálov – Stojanček a prenosná konštrukcia\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Měřicí technika a nářadí","Kategória:","Meracia technika a náradie"],["Kategorie:","Měřicí technika a nářadí","Kategória:","Meracia technika a náradie"],["Typ produktu:","Digitální osciloskop","Typ produktu:","Digitálny osciloskop"],["Provedení:","Kapesní, přenosné","Vyhotovenie:","Vreckové, prenosné"],["Sledovaný obsah:","Elektrický průběh v čase","Sledovaný obsah:","Elektrický priebeh v čase"],["Zobrazení:","Digitální displej","Zobrazenie:","Digitálny displej"],["Určení:","Základní diagnostika a výuka","Určenie:","Základná diagnostika a výučba"],["Použití:","V rámci limitů přístroje a sondy","Použitie:","V rámci limitov prístroja a sondy"]],"catalog_names":{"Kapesní digitální osciloskop pro měření signálů":"Vreckový digitálny osciloskop na meranie signálov"},"catalog_short_cs":"Podívejte se, jak se elektrický signál mění v čase. Kapesní digitální osciloskop pomáhá při základní diagnostice elektroniky, výuce a ověřování vlastních zapojení. Na obrazovce získáte průběh, který běžné číselné měření nevystihne stejným způsobem. Kompaktní provedení snadno připravíte u pracovního stolu. Před připojením vždy porovnejte úroveň a charakter signálu s povolenými limity přístroje i sondy; použití se řídí skutečným modelem dodávané varianty. Číselná hodnota napětí nemusí říci, zda signál pulzuje nebo jak vypadá jeho tvar. Osciloskop pomůže zobrazit změny v čase a lépe porozumět chování jednoduchého obvodu.","catalog_short_t":"Pozrite sa, ako sa elektrický signál mení v čase. Vreckový digitálny osciloskop pomáha pri základnej diagnostike elektroniky, výučbe a overovaní vlastných zapojení. Na obrazovke získate priebeh, ktorý bežné číselné meranie nevystihne rovnakým spôsobom. Kompaktné vyhotovenie ľahko pripravíte pri pracovnom stole. Pred pripojením vždy porovnajte úroveň a charakter signálu s povolenými limitmi prístroja aj sondy; použitie sa riadi skutočným modelom dodávaného variantu. Číselná hodnota napätia nemusí prezradiť, či signál pulzuje alebo ako vyzerá jeho tvar. Osciloskop pomôže zobraziť zmeny v čase a lepšie porozumieť správaniu jednoduchého obvodu."},{"code":"OKL-019","name_cs":"Endoskopická kamera USB-C pro inspekci dutin","name_t":"Endoskopická kamera USB-C na inšpekciu dutín","short_cs_text":"Malá snímací hlava umožňuje nahlédnout do dutin a omezeně přístupných míst. Obraz se přenáší kabelem do kompatibilního zařízení. Konstrukce odděluje místo snímání od obrazovky, na které uživatel sleduje výsledek. Kabelové připojení spojuje kameru s podporovaným telefonem nebo počítačem. USB-C varianta využívá kompatibilní systém a software pro zobrazení obrazu. Ovládací část je umístěna na vedení mezi snímací hlavou a připojovaným zařízením. Světelné prvky v okolí objektivu osvětlují blízký prostor před kamerou. Úzká hlava a ohebné vedení zpřístupňují pohled za kryt nebo do dutiny. Výsledný detail souvisí se vzdáleností povrchu, světlem a ostřicími vlastnostmi kamery.","short_t_text":"Malá snímacia hlava umožňuje nahliadnuť do dutín a obmedzene prístupných miest. Obraz sa prenáša káblom do kompatibilného zariadenia. Konštrukcia oddeľuje miesto snímania od obrazovky, na ktorej používateľ sleduje výsledok. Káblové pripojenie spája kameru s podporovaným telefónom alebo počítačom. Variant USB-C využíva kompatibilný systém a softvér na zobrazenie obrazu. Ovládacia časť je umiestnená na vedení medzi snímacou hlavou a pripájaným zariadením. Svetelné prvky v okolí objektívu osvetľujú blízky priestor pred kamerou. Úzka hlava a ohybné vedenie sprístupňujú pohľad za kryt alebo do dutiny. Výsledný detail súvisí so vzdialenosťou povrchu, svetlom a zaostrovacími vlastnosťami kamery.","short_t_html":"\n                            Malá snímacia hlava umožňuje nahliadnuť do dutín a obmedzene prístupných miest. Obraz sa prenáša káblom do kompatibilného zariadenia. Konštrukcia oddeľuje miesto snímania od obrazovky, na ktorej používateľ sleduje výsledok. Káblové pripojenie spája kameru s podporovaným telefónom alebo počítačom. Variant USB-C využíva kompatibilný systém a softvér na zobrazenie obrazu. Ovládacia časť je umiestnená na vedení medzi snímacou hlavou a pripájaným zariadením. Svetelné prvky v okolí objektívu osvetľujú blízky priestor pred kamerou. Úzka hlava a ohybné vedenie sprístupňujú pohľad za kryt alebo do dutiny. Výsledný detail súvisí so vzdialenosťou povrchu, svetlom a zaostrovacími vlastnosťami kamery.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Endoskopická kamera USB-C na inšpekciu dutín</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Kamera na konci ohybného kábla</h3><p>Malá snímacia hlava umožňuje nahliadnuť do dutín a obmedzene prístupných miest. Obraz sa prenáša káblom do kompatibilného zariadenia. Konštrukcia oddeľuje miesto snímania od obrazovky, na ktorej používateľ sleduje výsledok.</p><p style=\"margin-top:16px\">Ohybné vedenie prenáša snímaciu časť mimo priameho dosahu telefónu alebo počítača. Kamerová hlava zachytáva priestor pred objektívom a zobrazovacie zariadenie ponecháva mimo kontrolovanej dutiny. Vďaka tomuto rozdeleniu možno sledovať povrchy za hranou otvoru alebo vo vnútri krytu v dosahu káblovej sondy.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-019-function-1.jpg\" alt=\"Endoskopická kamera USB-C na inšpekciu dutín – Kamera na konci ohybného kábla\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Pripojenie USB-C</h3><p>Káblové pripojenie spája kameru s podporovaným telefónom alebo počítačom. Variant USB-C využíva kompatibilný systém a softvér na zobrazenie obrazu. Ovládacia časť je umiestnená na vedení medzi snímacou hlavou a pripájaným zariadením.</p><p style=\"margin-top:16px\">Fyzický konektor tvorí iba jednu časť požadovaného prepojenia. Obraz musí podporovať aj systém pripojeného zariadenia a používaný zobrazovací softvér. Kábel prenáša dáta medzi snímacou časťou a hostiteľským zariadením, ktoré obraz spracuje a sprístupní na vlastnej obrazovke prostredníctvom kompatibilnej aplikácie.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-019-function-2.jpg\" alt=\"Endoskopická kamera USB-C na inšpekciu dutín – Pripojenie USB-C\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Osvetlenie pri snímacej hlave</h3><p>Svetelné prvky v okolí objektívu osvetľujú blízky priestor pred kamerou. Úzka hlava a ohybné vedenie sprístupňujú pohľad za kryt alebo do dutiny. Výsledný detail súvisí so vzdialenosťou povrchu, svetlom a zaostrovacími vlastnosťami kamery.</p><p style=\"margin-top:16px\">Blízke osvetlenie dopĺňa kameru v priestore, kam okolité svetlo často nedosahuje. Umiestnenie svetelných prvkov okolo objektívu sústreďuje svetlo do zorného poľa. Lesklý povrch môže vytvárať odrazy a príliš malá vzdialenosť mení čitateľnosť detailu podľa zaostrovacieho rozsahu konkrétnej snímacej hlavy.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-019-function-3.jpg\" alt=\"Endoskopická kamera USB-C na inšpekciu dutín – Osvetlenie pri snímacej hlave\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Endoskopy a inspekční kamery","Kategória:","Endoskopy a inšpekčné kamery"],["Kategorie:","Endoskopy a inspekční kamery","Kategória:","Endoskopy a inšpekčné kamery"],["Připojení:","USB-C","Pripojenie:","USB-C"],["Typ produktu:","Endoskopická inspekční kamera","Typ produktu:","Endoskopická inšpekčná kamera"],["Přenášený obsah:","Obraz","Prenášaný obsah:","Obraz"],["Určení:","Vizuální kontrola přístupných dutin","Určenie:","Vizuálna kontrola prístupných dutín"],["Spolupracující zařízení:","Kompatibilní telefon nebo počítač","Spolupracujúce zariadenie:","Kompatibilný telefón alebo počítač"],["Způsob použití:","Inspekční sonda","Spôsob použitia:","Inšpekčná sonda"]],"catalog_names":{"Endoskopická kamera USB C":"Endoskopická kamera USB C","Endoskopická kamera USB-C pro inspekci dutin":"Endoskopická kamera USB-C na inšpekciu dutín"},"catalog_short_cs":"Zkontrolujte místa, kam běžným pohledem nevidíte. Endoskopická kamera USB-C slouží k vizuální prohlídce vhodných dutin, prostoru za nábytkem a přístupných částí mechaniky. Úzká sonda přivede pohled blíž k místu kontroly a obraz zobrazíte na podporovaném zařízení. Hodí se pro domácí údržbu, hledání překážek i orientační kontrolu instalací. Před použitím ověřte kompatibilitu telefonu nebo počítače, požadavky na aplikaci a podmínky, pro které je konkrétní sonda určena. Než začnete rozebírat větší část zařízení, může pomoci obyčejná vizuální kontrola. Inspekční sonda umožňuje prohlédnout dostupné místo a lépe rozhodnout o dalším postupu.","catalog_short_t":"Skontrolujte miesta, kam bežným pohľadom nevidíte. Endoskopická kamera USB-C slúži na vizuálnu prehliadku vhodných dutín, priestoru za nábytkom a prístupných častí mechaniky. Úzka sonda priblíži pohľad k miestu kontroly a obraz zobrazíte na podporovanom zariadení. Hodí sa na domácu údržbu, hľadanie prekážok aj orientačnú kontrolu inštalácií. Pred použitím overte kompatibilitu telefónu alebo počítača, požiadavky na aplikáciu a podmienky, na ktoré je konkrétna sonda určená. Skôr než začnete rozoberať väčšiu časť zariadenia, môže pomôcť obyčajná vizuálna kontrola. Inšpekčná sonda umožňuje prezrieť dostupné miesto a lepšie sa rozhodnúť o ďalšom postupe."},{"code":"OKL-020","name_cs":"Wi-Fi endoskopická kamera pro inspekční kontrolu","name_t":"Wi-Fi endoskopická kamera na inšpekčnú kontrolu","short_cs_text":"Wi-Fi modul přenáší obraz z endoskopické kamery do kompatibilní aplikace. Telefon může sloužit jako zobrazovací jednotka oddělená od kabelu se sondou. Tato konstrukce usnadňuje sledování obrazu při manipulaci se snímací hlavou. Kamera je umístěna na konci ohebného vedení. Malá hlava se dostane do míst, kam běžný fotoaparát telefonu nedohlédne. Vedení propojuje sondu s bezdrátovým modulem a přivádí potřebné napájení. Světelné prvky kolem objektivu osvětlují prostor bez samostatné velké lampy. Modul sdružuje bezdrátovou komunikaci a fyzické ovládání podporovaných funkcí. Obraz je určen pro inspekční kontrolu povrchů v dosahu sondy.","short_t_text":"Modul Wi-Fi prenáša obraz z endoskopickej kamery do kompatibilnej aplikácie. Telefón môže slúžiť ako zobrazovacia jednotka oddelená od kábla so sondou. Táto konštrukcia uľahčuje sledovanie obrazu pri manipulácii so snímacou hlavou. Kamera je umiestnená na konci ohybného vedenia. Malá hlava sa dostane na miesta, kam bežný fotoaparát telefónu nedovidí. Vedenie prepája sondu s bezdrôtovým modulom a privádza potrebné napájanie. Svetelné prvky okolo objektívu osvetľujú priestor bez samostatnej veľkej lampy. Modul združuje bezdrôtovú komunikáciu a fyzické ovládanie podporovaných funkcií. Obraz je určený na inšpekčnú kontrolu povrchov v dosahu sondy.","short_t_html":"\n                            Modul Wi-Fi prenáša obraz z endoskopickej kamery do kompatibilnej aplikácie. Telefón môže slúžiť ako zobrazovacia jednotka oddelená od kábla so sondou. Táto konštrukcia uľahčuje sledovanie obrazu pri manipulácii so snímacou hlavou. Kamera je umiestnená na konci ohybného vedenia. Malá hlava sa dostane na miesta, kam bežný fotoaparát telefónu nedovidí. Vedenie prepája sondu s bezdrôtovým modulom a privádza potrebné napájanie. Svetelné prvky okolo objektívu osvetľujú priestor bez samostatnej veľkej lampy. Modul združuje bezdrôtovú komunikáciu a fyzické ovládanie podporovaných funkcií. Obraz je určený na inšpekčnú kontrolu povrchov v dosahu sondy.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Wi-Fi endoskopická kamera na inšpekčnú kontrolu</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Bezdrôtový obraz v telefóne</h3><p>Modul Wi-Fi prenáša obraz z endoskopickej kamery do kompatibilnej aplikácie. Telefón môže slúžiť ako zobrazovacia jednotka oddelená od kábla so sondou. Táto konštrukcia uľahčuje sledovanie obrazu pri manipulácii so snímacou hlavou.</p><p style=\"margin-top:16px\">Bezdrôtové spojenie prepája zobrazovaciu časť zostavy s modulom endoskopu. Snímacia hlava zostáva pripojená vlastným vedením, takže bezdrôtový prenos sa týka cesty medzi modulom a telefónom. Aplikácia prijíma obraz a sprístupňuje dostupné funkcie podľa kompatibility zariadenia a použitej verzie softvéru.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-020-function-1.jpg\" alt=\"Wi-Fi endoskopická kamera na inšpekčnú kontrolu – Bezdrôtový obraz v telefóne\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Káblová sonda na inšpekčný pohľad</h3><p>Kamera je umiestnená na konci ohybného vedenia. Malá hlava sa dostane na miesta, kam bežný fotoaparát telefónu nedovidí. Vedenie prepája sondu s bezdrôtovým modulom a privádza potrebné napájanie.</p><p style=\"margin-top:16px\">Vedenie umožňuje meniť polohu snímacej hlavy nezávisle od obrazovky telefónu. Objektív poskytuje pohľad z konca sondy, zatiaľ čo modul zabezpečuje ďalší prenos. Výsledný záber určuje poloha hlavy a jej optické vlastnosti, ktoré ovplyvňujú viditeľnú oblasť aj čitateľnosť blízkych povrchových detailov.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-020-function-2.jpg\" alt=\"Wi-Fi endoskopická kamera na inšpekčnú kontrolu – Káblová sonda na inšpekčný pohľad\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Osvetlenie a ovládací modul</h3><p>Svetelné prvky okolo objektívu osvetľujú priestor bez samostatnej veľkej lampy. Modul združuje bezdrôtovú komunikáciu a fyzické ovládanie podporovaných funkcií. Obraz je určený na inšpekčnú kontrolu povrchov v dosahu sondy.</p><p style=\"margin-top:16px\">Osvetlenie a kamera tvoria spoločnú snímaciu časť pre prostredie s obmedzeným prístupom okolitého svetla. Modul oddeľuje napájacie a komunikačné funkcie od úzkeho konca sondy. Celok prenáša bežný obraz povrchu pred objektívom, ktorého kvalita závisí od vzdialenosti, svetla a vlastností pozorovaného materiálu.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-020-function-3.jpg\" alt=\"Wi-Fi endoskopická kamera na inšpekčnú kontrolu – Osvetlenie a ovládací modul\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Endoskopy a inspekční kamery","Kategória:","Endoskopy a inšpekčné kamery"],["Kategorie:","Endoskopy a inspekční kamery","Kategória:","Endoskopy a inšpekčné kamery"],["Připojení:","Wi-Fi","Pripojenie:","Wi-Fi"],["Typ produktu:","Endoskopická inspekční kamera","Typ produktu:","Endoskopická inšpekčná kamera"],["Přenášený obsah:","Obraz","Prenášaný obsah:","Obraz"],["Určení:","Vizuální kontrola přístupných dutin","Určenie:","Vizuálna kontrola prístupných dutín"],["Spolupracující zařízení:","Kompatibilní mobilní zařízení","Spolupracujúce zariadenie:","Kompatibilné mobilné zariadenie"],["Software:","Aplikace pro konkrétní kameru","Softvér:","Aplikácia pre konkrétnu kameru"]],"catalog_names":{"Endoskopická kamera WiFi":"Endoskopická kamera WiFi","Wi-Fi endoskopická kamera pro inspekční kontrolu":"Wi-Fi endoskopická kamera na inšpekčnú kontrolu"},"catalog_short_cs":"Podívejte se do hůře přístupných míst a zobrazte si obraz na kompatibilním mobilním zařízení. Wi-Fi endoskopická kamera pomáhá s orientační kontrolou dutin, mechaniky a instalací bez přímého datového kabelu do telefonu. Je praktická při domácí údržbě i hledání příčiny obtíží před rozebíráním. Sonda musí rozměry a odolností odpovídat kontrolovanému prostředí. Před prací si vyzkoušejte připojení, aplikaci a zaostření, abyste v samotné dutině věděli, co obraz ukazuje. Pohled dovnitř může pomoci rozhodnout, zda je další zásah potřeba a odkud k němu přistoupit. Sondu zavádějte pomalu a průběžně sledujte směr pohybu.","catalog_short_t":"Pozrite sa do ťažšie prístupných miest a zobrazte si obraz na kompatibilnom mobilnom zariadení. Wi-Fi endoskopická kamera pomáha s orientačnou kontrolou dutín, mechaniky a inštalácií bez priameho dátového kábla do telefónu. Je praktická pri domácej údržbe aj pri hľadaní príčiny problémov pred rozoberaním. Sonda musí rozmermi a odolnosťou zodpovedať kontrolovanému prostrediu. Pred prácou si vyskúšajte pripojenie, aplikáciu a zaostrenie, aby ste v samotnej dutine vedeli, čo obraz ukazuje. Pohľad dovnútra môže pomôcť rozhodnúť, či je ďalší zásah potrebný a odkiaľ k nemu pristúpiť. Sondu zavádzajte pomaly a priebežne sledujte smer pohybu."},{"code":"OKL-021","name_cs":"NFC karta pro Google recenze","name_t":"NFC karta na Google recenzie","short_cs_text":"NFC nosič obsahuje odkaz na cílovou stránku s hodnocením firmy. Kompatibilní telefon načte uloženou informaci z malé vzdálenosti a otevře dostupný odkaz. Samotná recenze zůstává rozhodnutím zákazníka na příslušné platformě. Karta nebo stojánkové provedení zpřístupňuje odkaz přímo na místě. Potisk označuje účel NFC plochy a místo pro přiložení telefonu. Nosič slouží k předání odkazu a nevyžaduje vlastní displej. Elektronický čip uchovává podporovaný NFC záznam. Nastavený odkaz propojuje fyzický předmět s online profilem firmy. Pro používání této funkce je potřeba telefon s podporou NFC a možnost otevřít cílovou webovou stránku.","short_t_text":"NFC nosič obsahuje odkaz na cieľovú stránku s hodnotením firmy. Kompatibilný telefón načíta uloženú informáciu z malej vzdialenosti a otvorí dostupný odkaz. Samotná recenzia zostáva rozhodnutím zákazníka na príslušnej platforme. Karta alebo vyhotovenie so stojančekom sprístupňuje odkaz priamo na mieste. Potlač označuje účel NFC plochy a miesto na priloženie telefónu. Nosič slúži na odovzdanie odkazu a nevyžaduje vlastný displej. Elektronický čip uchováva podporovaný NFC záznam. Nastavený odkaz prepája fyzický predmet s online profilom firmy. Na používanie tejto funkcie je potrebný telefón s podporou NFC a možnosť otvoriť cieľovú webovú stránku.","short_t_html":"\n                            NFC nosič obsahuje odkaz na cieľovú stránku s hodnotením firmy. Kompatibilný telefón načíta uloženú informáciu z malej vzdialenosti a otvorí dostupný odkaz. Samotná recenzia zostáva rozhodnutím zákazníka na príslušnej platforme. Karta alebo vyhotovenie so stojančekom sprístupňuje odkaz priamo na mieste. Potlač označuje účel NFC plochy a miesto na priloženie telefónu. Nosič slúži na odovzdanie odkazu a nevyžaduje vlastný displej. Elektronický čip uchováva podporovaný NFC záznam. Nastavený odkaz prepája fyzický predmet s online profilom firmy. Na používanie tejto funkcie je potrebný telefón s podporou NFC a možnosť otvoriť cieľovú webovú stránku.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>NFC karta na Google recenzie</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Odkaz na recenzie cez NFC</h3><p>NFC nosič obsahuje odkaz na cieľovú stránku s hodnotením firmy. Kompatibilný telefón načíta uloženú informáciu z malej vzdialenosti a otvorí dostupný odkaz. Samotná recenzia zostáva rozhodnutím zákazníka na príslušnej platforme.</p><p style=\"margin-top:16px\">Prenos odovzdá telefónu uložený webový odkaz, ktorý vedie na nastavený firemný profil alebo príslušnú stránku hodnotenia. NFC tým skracuje cestu medzi fyzickým kontaktným miestom a online formulárom. Obsah profilu, prihlásenie používateľa a samotné odoslanie hodnotenia zabezpečuje cieľová platforma v telefóne.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-021-function-1.jpg\" alt=\"NFC karta na Google recenzie – Odkaz na recenzie cez NFC\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Fyzický nosič pre kontaktné miesto</h3><p>Karta alebo vyhotovenie so stojančekom sprístupňuje odkaz priamo na mieste. Potlač označuje účel NFC plochy a miesto na priloženie telefónu. Nosič slúži na odovzdanie odkazu a nevyžaduje vlastný displej.</p><p style=\"margin-top:16px\">Viditeľný motív prepája označenie služby s miestom, kde telefón načítava záznam čipu. Fyzický formát ponecháva odkaz dostupný bez toho, aby ho bolo potrebné vypisovať na samostatnom displeji. Karta slúži ako trvalý nosič informácie a prepája návštevu prevádzky s dostupným webovým prostredím na hodnotenie firmy.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-021-function-2.jpg\" alt=\"NFC karta na Google recenzie – Fyzický nosič pre kontaktné miesto\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Zápis informácie do čipu</h3><p>Elektronický čip uchováva podporovaný NFC záznam. Nastavený odkaz prepája fyzický predmet s online profilom firmy. Na používanie tejto funkcie je potrebný telefón s podporou NFC a možnosť otvoriť cieľovú webovú stránku.</p><p style=\"margin-top:16px\">Uložený záznam obsahuje informáciu pre kompatibilnú NFC čítačku v telefóne. Čip odovzdáva odkaz, zatiaľ čo otvorenie a načítanie stránky prebieha v prostredí mobilného zariadenia. Fyzická karta teda neuchováva samotné recenzie ani nepridáva hodnotenia do profilu; poskytuje cestu k nastavenému online cieľu.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-021-function-3.jpg\" alt=\"NFC karta na Google recenzie – Zápis informácie do čipu\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Praktické vychytávky","Kategória:","Praktické vychytávky"],["Kategorie:","Praktické vychytávky","Kategória:","Praktické vychytávky"],["Připojení:","NFC","Pripojenie:","NFC"],["Typ produktu:","NFC karta","Typ produktu:","NFC karta"],["Účel:","Zpřístupnění odkazu pro Google recenze","Účel:","Sprístupnenie odkazu na Google recenzie"],["Technologie:","NFC","Technológia:","NFC"],["Spolupracující zařízení:","Telefon s podporou čtení NFC","Spolupracujúce zariadenie:","Telefón s podporou čítania NFC"],["Cílová služba:","Google recenze","Cieľová služba:","Google recenzie"],["Způsob použití:","Přiložení kompatibilního telefonu","Spôsob použitia:","Priloženie kompatibilného telefónu"]],"catalog_names":{"NFC karta pro Google recenze":"NFC karta na Google recenzie"},"catalog_short_cs":"Usnadněte zákazníkům cestu k hodnocení vašeho podniku. NFC karta může po přiložení kompatibilního telefonu otevřít nastavený odkaz na stránku pro recenzi a omezit zdlouhavé vyhledávání provozovny. Hodí se k recepci, pokladně nebo místu předání služby. Největší smysl má tehdy, když ji nabídnete spokojenému i kritickému zákazníkovi stejně přirozeně a necháte hodnocení na něm. Karta recenzi sama nevytvoří; pouze zpřístupní odpovídající odkaz. Zákazník nemusí ručně hledat správnou pobočku, pokud karta otevírá její konkrétní recenzní stránku. Přiložení telefonu může celý postup zjednodušit na několik běžných kroků.","catalog_short_t":"Uľahčite zákazníkom cestu k hodnoteniu vášho podniku. NFC karta môže po priložení kompatibilného telefónu otvoriť nastavený odkaz na stránku s recenziou a obmedziť zdĺhavé vyhľadávanie prevádzky. Hodí sa na recepciu, k pokladnici alebo na miesto odovzdania služby. Najväčší zmysel má vtedy, keď ju ponúknete spokojnému aj kritickému zákazníkovi rovnako prirodzene a hodnotenie necháte na ňom. Karta recenziu sama nevytvorí; iba sprístupní zodpovedajúci odkaz. Zákazník nemusí ručne hľadať správnu pobočku, ak karta otvára jej konkrétnu stránku na recenzie. Priloženie telefónu môže celý postup zjednodušiť na niekoľko bežných krokov."},{"code":"OKL-022","name_cs":"Mini termotiskárna Bluetooth na poznámky","name_t":"Mini termotlačiareň Bluetooth na poznámky","short_cs_text":"Mini tiskárna vytváří obraz zahříváním kompatibilního termopapíru. Tisk proto nevyžaduje klasickou inkoustovou náplň. Výstup slouží pro poznámky, jednoduchou grafiku a další podklady v rozsahu podporovaném aplikací. Telefon předává tiskový obsah prostřednictvím podporovaného bezdrátového připojení. Aplikace připravuje text, obrázek nebo předlohu pro úzký papírový výstup. Rozměry a černobílá technologie určují výslednou podobu vytištěného materiálu. Papír je uložen v těle tiskárny a vystupuje přední štěrbinou. Malá konstrukce sdružuje tiskový mechanismus i zásobu média. Přenosný formát je přizpůsoben krátkým poznámkám a drobným pracovním či studijním výstupům.","short_t_text":"Mini tlačiareň vytvára obraz zahrievaním kompatibilného termopapiera. Tlač preto nevyžaduje klasickú atramentovú náplň. Výstup slúži na poznámky, jednoduchú grafiku a ďalšie podklady v rozsahu, ktorý podporuje aplikácia. Telefón odovzdáva obsah na tlač prostredníctvom podporovaného bezdrôtového pripojenia. Aplikácia pripravuje text, obrázok alebo predlohu pre úzky papierový výstup. Rozmery a čiernobiela technológia určujú výslednú podobu vytlačeného materiálu. Papier je uložený v tele tlačiarne a vychádza prednou štrbinou. Malá konštrukcia združuje tlačový mechanizmus aj zásobu média. Prenosný formát je prispôsobený krátkym poznámkam a drobným pracovným či študijným výstupom.","short_t_html":"\n                            Mini tlačiareň vytvára obraz zahrievaním kompatibilného termopapiera. Tlač preto nevyžaduje klasickú atramentovú náplň. Výstup slúži na poznámky, jednoduchú grafiku a ďalšie podklady v rozsahu, ktorý podporuje aplikácia. Telefón odovzdáva obsah na tlač prostredníctvom podporovaného bezdrôtového pripojenia. Aplikácia pripravuje text, obrázok alebo predlohu pre úzky papierový výstup. Rozmery a čiernobiela technológia určujú výslednú podobu vytlačeného materiálu. Papier je uložený v tele tlačiarne a vychádza prednou štrbinou. Malá konštrukcia združuje tlačový mechanizmus aj zásobu média. Prenosný formát je prispôsobený krátkym poznámkam a drobným pracovným či študijným výstupom.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Mini termotlačiareň Bluetooth na poznámky</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Tlač tepelnou technológiou</h3><p>Mini tlačiareň vytvára obraz zahrievaním kompatibilného termopapiera. Tlač preto nevyžaduje klasickú atramentovú náplň. Výstup slúži na poznámky, jednoduchú grafiku a ďalšie podklady v rozsahu, ktorý podporuje aplikácia.</p><p style=\"margin-top:16px\">Tlačová hlava vytvára tmavé body na tepelne citlivej vrstve papiera. Skladaním týchto bodov vzniká text alebo čiernobiely obrázok v šírke podporovaného média. Spotrebným materiálom je zodpovedajúca papierová rolka, zatiaľ čo samotná technológia vytvárania obrazu pracuje bez samostatnej kazety s atramentom.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-022-function-1.jpg\" alt=\"Mini termotlačiareň Bluetooth na poznámky – Tlač tepelnou technológiou\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Bluetooth a mobilná aplikácia</h3><p>Telefón odovzdáva obsah na tlač prostredníctvom podporovaného bezdrôtového pripojenia. Aplikácia pripravuje text, obrázok alebo predlohu pre úzky papierový výstup. Rozmery a čiernobiela technológia určujú výslednú podobu vytlačeného materiálu.</p><p style=\"margin-top:16px\">Digitálna predloha sa pred tlačou prevádza do podoby zodpovedajúcej možnostiam tlačiarne. Text a grafika tak zdieľajú rovnaký čiernobiely výstup na úzkom páse. Dostupné šablóny, úpravy predlohy a spôsob odoslania úlohy vychádzajú z konkrétnej aplikácie, ktorú telefón používa na komunikáciu s tlačiarňou.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-022-function-2.jpg\" alt=\"Mini termotlačiareň Bluetooth na poznámky – Bluetooth a mobilná aplikácia\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Kompaktné telo a papierová rolka</h3><p>Papier je uložený v tele tlačiarne a vychádza prednou štrbinou. Malá konštrukcia združuje tlačový mechanizmus aj zásobu média. Prenosný formát je prispôsobený krátkym poznámkam a drobným pracovným či študijným výstupom.</p><p style=\"margin-top:16px\">Vnútorné uloženie rolky vedie papier cez tlačový mechanizmus k výstupnému otvoru. Zostava ponecháva zásobu média a pracovnú časť v jednom tele. Výsledná tlač má podobu úzkeho pásu s obsahom pripraveným v telefóne, pričom dĺžku a formát konkrétnej úlohy ovplyvňujú možnosti aplikácie a média.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-022-function-3.jpg\" alt=\"Mini termotlačiareň Bluetooth na poznámky – Kompaktné telo a papierová rolka\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Praktické vychytávky","Kategória:","Praktické vychytávky"],["Kategorie:","Praktické vychytávky","Kategória:","Praktické vychytávky"],["Připojení:","Bluetooth","Pripojenie:","Bluetooth"],["Typ produktu:","Mini termotiskárna","Typ produktu:","Mini termotlačiareň"],["Technologie tisku:","Termální","Technológia tlače:","Termálna"],["Tiskové médium:","Kompatibilní termopapír","Tlačové médium:","Kompatibilný termopapier"],["Ovládání:","Prostřednictvím kompatibilní aplikace","Ovládanie:","Prostredníctvom kompatibilnej aplikácie"],["Určení:","Poznámky a menší kreativní výstupy","Určenie:","Poznámky a menšie kreatívne výstupy"]],"catalog_names":{"Mini termotiskárna Bluetooth":"Mini termotlačiareň Bluetooth","Mini termotiskárna Bluetooth na poznámky":"Mini termotlačiareň Bluetooth na poznámky"},"catalog_short_cs":"Přeneste krátké poznámky, jednoduché motivy a pracovní podklady z telefonu na papír. Mini termotiskárna Bluetooth využívá termální tisk bez inkoustových kazet a ovládá se prostřednictvím kompatibilní aplikace. Kompaktní provedení se hodí na pracovní stůl, ke studiu i pro menší kreativní projekty. Výsledek a dostupné šablony se řídí aplikací a vhodným termopapírem. Praktický doplněk, když chcete mít vybrané informace rychle po ruce i mimo obrazovku telefonu. Krátký seznam, jednoduchý obrázek nebo vlastní poznámka mohou mít praktické místo vedle počítače i ve studijním sešitě. Mini tiskárna se zaměřuje právě na takové drobné výstupy.","catalog_short_t":"Preneste krátke poznámky, jednoduché motívy a pracovné podklady z telefónu na papier. Mini termotlačiareň Bluetooth využíva termálnu tlač bez atramentových kaziet a ovláda sa prostredníctvom kompatibilnej aplikácie. Kompaktné vyhotovenie sa hodí na pracovný stôl, na štúdium aj na menšie kreatívne projekty. Výsledok a dostupné šablóny sa riadia aplikáciou a vhodným termopapierom. Praktický doplnok, keď chcete mať vybrané informácie rýchlo poruke aj mimo obrazovky telefónu. Krátky zoznam, jednoduchý obrázok alebo vlastná poznámka môžu mať praktické miesto vedľa počítača aj v študijnom zošite. Mini tlačiareň sa zameriava práve na takéto drobné výstupy."},{"code":"OKL-023","name_cs":"Bezdrátový HDMI adaptér pro sdílení obrazu","name_t":"Bezdrôtový HDMI adaptér na zdieľanie obrazu","short_cs_text":"Dongle se připojuje do HDMI vstupu kompatibilní televize, monitoru nebo projektoru. Přijímá podporované bezdrátové sdílení obrazu z mobilního zařízení nebo počítače. Jde o přijímač u obrazovky, nikoli o sadu samostatného vysílače a přijímače. Kompatibilní zdroj může sdílet obrazovku, prezentaci nebo podporovaný mediální obsah. Způsob propojení závisí na systému zdrojového zařízení a podporovaném režimu přijímače. Dostupnost přehrávání chráněného obsahu se řídí konkrétní službou a protokolem. Krátké HDMI vedení propojuje kruhové tělo přijímače s obrazovkou. Napájení a nastavení připojení tvoří součást provozu donglu. Malé provedení ponechává hlavní zobrazovací plochu televize nebo monitoru volnou.","short_t_text":"Dongle sa pripája do HDMI vstupu kompatibilného televízora, monitora alebo projektora. Prijíma podporované bezdrôtové zdieľanie obrazu z mobilného zariadenia alebo počítača. Ide o prijímač pri obrazovke, nie o súpravu samostatného vysielača a prijímača. Kompatibilný zdroj môže zdieľať obrazovku, prezentáciu alebo podporovaný multimediálny obsah. Spôsob prepojenia závisí od systému zdrojového zariadenia a podporovaného režimu prijímača. Dostupnosť prehrávania chráneného obsahu sa riadi konkrétnou službou a protokolom. Krátke HDMI vedenie prepája okrúhle telo prijímača s obrazovkou. Napájanie a nastavenie pripojenia sú súčasťou prevádzky donglu. Malé vyhotovenie ponecháva hlavnú zobrazovaciu plochu televízora alebo monitora voľnú.","short_t_html":"\n                            Dongle sa pripája do HDMI vstupu kompatibilného televízora, monitora alebo projektora. Prijíma podporované bezdrôtové zdieľanie obrazu z mobilného zariadenia alebo počítača. Ide o prijímač pri obrazovke, nie o súpravu samostatného vysielača a prijímača. Kompatibilný zdroj môže zdieľať obrazovku, prezentáciu alebo podporovaný multimediálny obsah. Spôsob prepojenia závisí od systému zdrojového zariadenia a podporovaného režimu prijímača. Dostupnosť prehrávania chráneného obsahu sa riadi konkrétnou službou a protokolom. Krátke HDMI vedenie prepája okrúhle telo prijímača s obrazovkou. Napájanie a nastavenie pripojenia sú súčasťou prevádzky donglu. Malé vyhotovenie ponecháva hlavnú zobrazovaciu plochu televízora alebo monitora voľnú.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Bezdrôtový HDMI adaptér na zdieľanie obrazu</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>HDMI prijímač k obrazovke</h3><p>Dongle sa pripája do HDMI vstupu kompatibilného televízora, monitora alebo projektora. Prijíma podporované bezdrôtové zdieľanie obrazu z mobilného zariadenia alebo počítača. Ide o prijímač pri obrazovke, nie o súpravu samostatného vysielača a prijímača.</p><p style=\"margin-top:16px\">HDMI časť odovzdáva prijatý obsah pripojenému zobrazovaciemu zariadeniu. Telefón alebo počítač tvorí zdroj bezdrôtového prenosu a musí podporovať kompatibilný režim zdieľania. Prijímač tak vytvára spojenie medzi bezdrôtovým zdrojom obsahu a obrazovkou, ktorá používa štandardný káblový vstup HDMI.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-023-function-1.jpg\" alt=\"Bezdrôtový HDMI adaptér na zdieľanie obrazu – HDMI prijímač k obrazovke\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Bezdrôtové zrkadlenie obsahu</h3><p>Kompatibilný zdroj môže zdieľať obrazovku, prezentáciu alebo podporovaný multimediálny obsah. Spôsob prepojenia závisí od systému zdrojového zariadenia a podporovaného režimu prijímača. Dostupnosť prehrávania chráneného obsahu sa riadi konkrétnou službou a protokolom.</p><p style=\"margin-top:16px\">Pri zrkadlení sa na cieľovej obrazovke zobrazuje obsah odovzdávaný zdrojovým zariadením. Výsledné správanie ovplyvňuje prenosový protokol, systém a konkrétna aplikácia. Podpora bežnej plochy alebo prezentácie preto sama osebe neurčuje dostupnosť každej streamovacej služby, ktorej obsah môže využívať ďalšiu ochranu prehrávania.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-023-function-2.jpg\" alt=\"Bezdrôtový HDMI adaptér na zdieľanie obrazu – Bezdrôtové zrkadlenie obsahu\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Kompaktné telo s HDMI káblom</h3><p>Krátke HDMI vedenie prepája okrúhle telo prijímača s obrazovkou. Napájanie a nastavenie pripojenia sú súčasťou prevádzky donglu. Malé vyhotovenie ponecháva hlavnú zobrazovaciu plochu televízora alebo monitora voľnú.</p><p style=\"margin-top:16px\">Krátky kábel oddeľuje telo prijímača od samotného konektora obrazovky. Prijímacia elektronika zostáva pri televízore, monitore alebo projektore a využíva zodpovedajúce napájanie. Zobrazovacie zariadenie preberá obraz cez svoj HDMI vstup, zatiaľ čo bezdrôtové prepojenie sa nastavuje medzi zdrojovým zariadením a prijímačom.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-023-function-3.jpg\" alt=\"Bezdrôtový HDMI adaptér na zdieľanie obrazu – Kompaktné telo s HDMI káblom\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Praktické vychytávky","Kategória:","Praktické vychytávky"],["Kategorie:","Praktické vychytávky","Kategória:","Praktické vychytávky"],["Připojení:","HDMI","Pripojenie:","HDMI"],["Typ produktu:","Bezdrátový HDMI adaptér","Typ produktu:","Bezdrôtový HDMI adaptér"],["Obrazové rozhraní:","HDMI","Obrazové rozhranie:","HDMI"],["Přenášený obsah:","Podporovaný obrazový signál","Prenášaný obsah:","Podporovaný obrazový signál"],["Určení:","Sdílení obrazu na monitor nebo TV","Určenie:","Zdieľanie obrazu na monitor alebo TV"],["Typické použití:","Prezentace a domácí multimédia","Typické použitie:","Prezentácie a domáce multimédiá"],["Kompatibilita:","Podle konkrétního přenosového režimu","Kompatibilita:","Podľa konkrétneho prenosového režimu"]],"catalog_names":{"Bezdrátový HDMI adaptér pro sdílení obrazu":"Bezdrôtový HDMI adaptér na zdieľanie obrazu"},"catalog_short_cs":"Přeneste obraz z podporovaného zařízení na větší obrazovku bez dlouhého HDMI kabelu přes místnost. Bezdrátový HDMI adaptér se hodí pro prezentace, sdílení obsahu a domácí multimédia. Při výběru je důležitá kompatibilita zdroje, přijímače a použitého přenosového režimu. Snazší zapojení oceníte tam, kde nechcete pokaždé přestavovat celou pracovní plochu. Rozlišení, latence a podpora streamovacích služeb se řídí konkrétní variantou, nikoli pouze označením HDMI. Prezentaci nebo vybraný obsah lze pohodlněji ukázat na televizi či monitoru než na malém displeji. Adaptér slouží jako součást bezdrátové přenosové cesty a u podporované sestavy omezuje potřebu dlouhého obrazového kabelu.","catalog_short_t":"Preneste obraz z podporovaného zariadenia na väčšiu obrazovku bez dlhého HDMI kábla cez miestnosť. Bezdrôtový HDMI adaptér sa hodí na prezentácie, zdieľanie obsahu a domáce multimédiá. Pri výbere je dôležitá kompatibilita zdroja, prijímača a použitého prenosového režimu. Jednoduchšie zapojenie oceníte tam, kde nechcete zakaždým prestavovať celú pracovnú plochu. Rozlíšenie, latencia a podpora streamovacích služieb sa riadia konkrétnym variantom, nie iba označením HDMI. Prezentáciu alebo vybraný obsah možno pohodlnejšie ukázať na televízore či monitore než na malom displeji. Adaptér slúži ako súčasť bezdrôtovej prenosovej cesty a pri podporovanej zostave obmedzuje potrebu dlhého obrazového kábla."},{"code":"OKL-024","name_cs":"RGB Pixel Clock – LED hodiny na pracovní stůl","name_t":"RGB Pixel Clock – LED hodiny na pracovný stôl","short_cs_text":"RGB Pixel Clock používá několik samostatných barevných zobrazovacích polí. Na jednotlivých částech se mohou zobrazovat číslice nebo podporované obrazové motivy. Výsledkem je členěný digitální panel s výrazným technickým vzhledem. Digitální zobrazení propojuje praktický časový údaj s dekorativním obsahem. Podoba motivů závisí na možnostech konkrétního softwaru a nastavení. Samostatná pole umožňují rozdělit zobrazovaný obsah do vizuálně oddělených částí. Displeje jsou zasazeny do společného podlouhlého těla s průhlednými a kovově působícími částmi. Boční podpěry drží panel na stole. Barevný obraz doplňuje vzhled konstrukce a vytváří samostatný prvek pracovního či herního prostoru.","short_t_text":"RGB Pixel Clock používa niekoľko samostatných farebných zobrazovacích polí. Na jednotlivých častiach sa môžu zobrazovať číslice alebo podporované obrazové motívy. Výsledkom je členený digitálny panel s výrazným technickým vzhľadom. Digitálne zobrazenie prepája praktický časový údaj s dekoratívnym obsahom. Podoba motívov závisí od možností konkrétneho softvéru a nastavenia. Samostatné polia umožňujú rozdeliť zobrazovaný obsah do vizuálne oddelených častí. Displeje sú zasadené do spoločného podlhovastého tela s priehľadnými a kovovo pôsobiacimi časťami. Bočné podpery držia panel na stole. Farebný obraz dopĺňa vzhľad konštrukcie a vytvára samostatný prvok pracovného či herného priestoru.","short_t_html":"\n                            RGB Pixel Clock používa niekoľko samostatných farebných zobrazovacích polí. Na jednotlivých častiach sa môžu zobrazovať číslice alebo podporované obrazové motívy. Výsledkom je členený digitálny panel s výrazným technickým vzhľadom. Digitálne zobrazenie prepája praktický časový údaj s dekoratívnym obsahom. Podoba motívov závisí od možností konkrétneho softvéru a nastavenia. Samostatné polia umožňujú rozdeliť zobrazovaný obsah do vizuálne oddelených častí. Displeje sú zasadené do spoločného podlhovastého tela s priehľadnými a kovovo pôsobiacimi časťami. Bočné podpery držia panel na stole. Farebný obraz dopĺňa vzhľad konštrukcie a vytvára samostatný prvok pracovného či herného priestoru.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>RGB Pixel Clock – LED hodiny na pracovný stôl</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Viac farebných obrazoviek vedľa seba</h3><p>RGB Pixel Clock používa niekoľko samostatných farebných zobrazovacích polí. Na jednotlivých častiach sa môžu zobrazovať číslice alebo podporované obrazové motívy. Výsledkom je členený digitálny panel s výrazným technickým vzhľadom.</p><p style=\"margin-top:16px\">Členenie obrazovej plochy vytvára rad samostatne vnímaných modulov namiesto jednej súvislej ciferníkovej dosky. Každé pole sa podieľa na celkovom motíve a farebnosť zvýrazňuje jednotlivé časti zobrazenia. Pri hodinovom motíve možno rozdelenie využiť na číslice, pri podporovanej grafike na vzájomne nadväzujúce obrazové prvky.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-024-function-1.jpg\" alt=\"RGB Pixel Clock – LED hodiny na pracovný stôl – Viac farebných obrazoviek vedľa seba\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Čas a obrazové motívy</h3><p>Digitálne zobrazenie prepája praktický časový údaj s dekoratívnym obsahom. Podoba motívov závisí od možností konkrétneho softvéru a nastavenia. Samostatné polia umožňujú rozdeliť zobrazovaný obsah do vizuálne oddelených častí.</p><p style=\"margin-top:16px\">Vzhľad časového údaja vychádza z elektronicky vytváraného obrazu. Farebné motívy menia podobu panelu bez výmeny fyzických číslic alebo čelných častí. Dostupné kombinácie obsahu určuje firmvér a nastavenie daného vyhotovenia, ktoré prepája jednotlivé polia do spoločného zobrazenia stolových digitálnych hodín.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-024-function-2.jpg\" alt=\"RGB Pixel Clock – LED hodiny na pracovný stôl – Čas a obrazové motívy\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Stolová konštrukcia s technickými detailmi</h3><p>Displeje sú zasadené do spoločného podlhovastého tela s priehľadnými a kovovo pôsobiacimi časťami. Bočné podpery držia panel na stole. Farebný obraz dopĺňa vzhľad konštrukcie a vytvára samostatný prvok pracovného či herného priestoru.</p><p style=\"margin-top:16px\">Podlhovasté usporiadanie zdôrazňuje rytmus obrazových polí a ich pravidelné rozostupy. Priehľadné časti nechávajú vyniknúť vnútorné členenie, zatiaľ čo podpery udržiavajú obrazovky v pevnej vzájomnej polohe. Konštrukcia tvorí spoločnú základňu pre elektronické hodiny, ktoré zároveň fungujú ako farebný dekoratívny panel na stole.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-024-function-3.jpg\" alt=\"RGB Pixel Clock – LED hodiny na pracovný stôl – Stolová konštrukcia s technickými detailmi\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Designové gadgety","Kategória:","Dizajnové gadgety"],["Kategorie:","Designové gadgety","Kategória:","Dizajnové gadgety"],["Model:","RGB Pixel Clock","Model:","RGB Pixel Clock"],["Typ produktu:","Digitální stolní hodiny","Typ produktu:","Digitálne stolové hodiny"],["Označení:","RGB Pixel Clock","Označenie:","RGB Pixel Clock"],["Vzhled zobrazení:","Pixelová estetika","Vzhľad zobrazenia:","Pixelová estetika"],["Barevné provedení:","RGB motiv","Farebné vyhotovenie:","RGB motív"],["Umístění:","Pracovní stůl nebo police","Umiestnenie:","Pracovný stôl alebo polica"],["Úloha v interiéru:","Zobrazení času a dekorace","Úloha v interiéri:","Zobrazenie času a dekorácia"]],"catalog_names":{"LED hodiny RGB Pixel Clock":"LED hodiny RGB Pixel Clock","RGB Pixel Clock – LED hodiny na pracovní stůl":"RGB Pixel Clock – LED hodiny na pracovný stôl"},"catalog_short_cs":"Doplňte pracovní stůl nebo herní sestavu o výrazný digitální prvek. Hodiny RGB Pixel Clock spojují zobrazení času s pixelovou estetikou a barevným světlem. Hodí se do interiéru, kde má technika plnit praktickou i dekorativní roli. Při umístění zvažte čitelnost, okolní osvětlení a to, zda chcete mít displej v přímém zorném poli. Dostupné motivy, změny barev a případná aplikace se řídí skutečným modelem dodávané varianty. Digitální hodiny mohou fungovat také jako vizuální doplněk celého pracovního prostoru. Pixelová estetika dobře zapadne vedle elektroniky a vytvoří zajímavý protiklad k běžnému číselníku.","catalog_short_t":"Doplňte pracovný stôl alebo hernú zostavu o výrazný digitálny prvok. Hodiny RGB Pixel Clock spájajú zobrazenie času s pixelovou estetikou a farebným svetlom. Hodia sa do interiéru, kde má technika plniť praktickú aj dekoratívnu úlohu. Pri umiestnení zvážte čitateľnosť, okolité osvetlenie a to, či chcete mať displej v priamom zornom poli. Dostupné motívy, zmeny farieb a prípadná aplikácia sa riadia skutočným modelom dodávaného variantu. Digitálne hodiny môžu fungovať aj ako vizuálny doplnok celého pracovného priestoru. Pixelová estetika dobre zapadne vedľa elektroniky a vytvorí zaujímavý kontrast k bežnému ciferníku."},{"code":"OKL-025","name_cs":"Cyberpunk City Lamp – designová LED dekorace","name_t":"Cyberpunk City Lamp – dizajnová LED dekorácia","short_cs_text":"Cyberpunk City Lamp zobrazuje technicky laděnou městskou scénu v kompaktní dekoraci. Vrstvené prvky vytvářejí uličky, výškové úrovně a dojem hloubky. Otevřený pohled dovnitř odhaluje drobné architektonické detaily. Světelné body zvýrazňují jednotlivé části miniatury. Modré a další barevné akcenty navazují na styl nočního futuristického města. Osvětlení je součástí dekorativního efektu modelu. Vnější rám drží prostorovou scénu pohromadě a umožňuje její prohlížení z různých úhlů. Přední a boční pohled odhalují odlišné vrstvy modelu. Dekorace tak kombinuje drobnou architekturu, technické prvky a světelnou atmosféru v jednom stolním objektu.","short_t_text":"Cyberpunk City Lamp zobrazuje technicky ladenú mestskú scénu v kompaktnej dekorácii. Vrstvené prvky vytvárajú uličky, výškové úrovne a dojem hĺbky. Otvorený pohľad dovnútra odhaľuje drobné architektonické detaily. Svetelné body zvýrazňujú jednotlivé časti miniatúry. Modré a ďalšie farebné akcenty nadväzujú na štýl nočného futuristického mesta. Osvetlenie je súčasťou dekoratívneho efektu modelu. Vonkajší rám drží priestorovú scénu pohromade a umožňuje ju prezerať z rôznych uhlov. Predný a bočný pohľad odhaľujú odlišné vrstvy modelu. Dekorácia tak kombinuje drobnú architektúru, technické prvky a svetelnú atmosféru v jednom stolovom objekte.","short_t_html":"\n                            Cyberpunk City Lamp zobrazuje technicky ladenú mestskú scénu v kompaktnej dekorácii. Vrstvené prvky vytvárajú uličky, výškové úrovne a dojem hĺbky. Otvorený pohľad dovnútra odhaľuje drobné architektonické detaily. Svetelné body zvýrazňujú jednotlivé časti miniatúry. Modré a ďalšie farebné akcenty nadväzujú na štýl nočného futuristického mesta. Osvetlenie je súčasťou dekoratívneho efektu modelu. Vonkajší rám drží priestorovú scénu pohromade a umožňuje ju prezerať z rôznych uhlov. Predný a bočný pohľad odhaľujú odlišné vrstvy modelu. Dekorácia tak kombinuje drobnú architektúru, technické prvky a svetelnú atmosféru v jednom stolovom objekte.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Cyberpunk City Lamp – dizajnová LED dekorácia</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Priestorová mestská miniatúra</h3><p>Cyberpunk City Lamp zobrazuje technicky ladenú mestskú scénu v kompaktnej dekorácii. Vrstvené prvky vytvárajú uličky, výškové úrovne a dojem hĺbky. Otvorený pohľad dovnútra odhaľuje drobné architektonické detaily.</p><p style=\"margin-top:16px\">Jednotlivé časti scény sú usporiadané v rôznych vzdialenostiach od predného pohľadu. Toto vrstvenie vytvára priestorový charakter modelu a umožňuje vnímať menšie objekty v súvislosti s okolitou architektúrou. Technické tvary a hustejšie členenie nadväzujú na vizuálnu podobu futuristického mesta v malom stolovom formáte.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-025-function-1.jpg\" alt=\"Cyberpunk City Lamp – dizajnová LED dekorácia – Priestorová mestská miniatúra\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>LED svetlo vo vnútri scény</h3><p>Svetelné body zvýrazňujú jednotlivé časti miniatúry. Modré a ďalšie farebné akcenty nadväzujú na štýl nočného futuristického mesta. Osvetlenie je súčasťou dekoratívneho efektu modelu.</p><p style=\"margin-top:16px\">Nasvietenie oddeľuje vybrané detaily od tmavších častí scény a zdôrazňuje jej hĺbku. Farebné akcenty menia vnímanie hrán, otvorov a jednotlivých architektonických vrstiev. Svetlo je určené predovšetkým na vytvorenie atmosféry vo vnútri miniatúry a dopĺňa fyzickú štruktúru modelu o ďalší viditeľný prvok.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-025-function-2.jpg\" alt=\"Cyberpunk City Lamp – dizajnová LED dekorácia – LED svetlo vo vnútri scény\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Uzavretý objekt s niekoľkými pohľadmi</h3><p>Vonkajší rám drží priestorovú scénu pohromade a umožňuje ju prezerať z rôznych uhlov. Predný a bočný pohľad odhaľujú odlišné vrstvy modelu. Dekorácia tak kombinuje drobnú architektúru, technické prvky a svetelnú atmosféru v jednom stolovom objekte.</p><p style=\"margin-top:16px\">Priestorové vyhotovenie odkrýva pri zmene smeru pohľadu inú skladbu detailov. Vonkajšia konštrukcia rámuje scénu a vymedzuje jej kompaktný rozmer. Jednotlivé vrstvy zostávajú mechanickou súčasťou dekorácie, zatiaľ čo vstavané svetelné prvky zvýrazňujú motív a prepájajú architektúru modelu s jeho večerným vizuálnym efektom.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-025-function-3.jpg\" alt=\"Cyberpunk City Lamp – dizajnová LED dekorácia – Uzavretý objekt s niekoľkými pohľadmi\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Designové gadgety","Kategória:","Dizajnové gadgety"],["Kategorie:","Designové gadgety","Kategória:","Dizajnové gadgety"],["Model:","Cyberpunk City Lamp","Model:","Cyberpunk City Lamp"],["Typ produktu:","Designová LED dekorace","Typ produktu:","Dizajnová LED dekorácia"],["Označení:","Cyberpunk City Lamp","Označenie:","Cyberpunk City Lamp"],["Vizuální motiv:","Futuristické město / sci-fi","Vizuálny motív:","Futuristické mesto / sci-fi"],["Světelná technologie:","LED","Svetelná technológia:","LED"],["Umístění:","Stůl nebo police v interiéru","Umiestnenie:","Stôl alebo polica v interiéri"],["Primární účel:","Dekorativní osvětlení","Primárny účel:","Dekoratívne osvetlenie"]],"catalog_names":{"LED dekorace Cyberpunk City Lamp":"LED dekorácia Cyberpunk City Lamp","Cyberpunk City Lamp – designová LED dekorace":"Cyberpunk City Lamp – dizajnová LED dekorácia"},"catalog_short_cs":"Vytvořte na stole malý světelný akcent inspirovaný futuristickou městskou estetikou. Cyberpunk City Lamp je LED dekorace pro pracovní kout, herní sestavu nebo polici s technickými doplňky. Zaujme především jako atmosférický prvek, který dotváří vzhled interiéru i mimo hlavní osvětlení. Při výběru místa zvažte pohledové strany, přístup k napájení a vztah k ostatním zdrojům světla. Konkrétní režimy a způsob ovládání se řídí dodávanou variantou. Detailní dekorace dokáže změnit dojem z pracovního kouta bez zásahu do celého interiéru. Inspirace městem a sci-fi estetikou se hodí vedle klávesnice, modelů nebo technických sbírek.","catalog_short_t":"Vytvorte na stole malý svetelný akcent inšpirovaný futuristickou mestskou estetikou. Cyberpunk City Lamp je LED dekorácia do pracovného kútika, hernej zostavy alebo na policu s technickými doplnkami. Zaujme predovšetkým ako atmosférický prvok, ktorý dotvára vzhľad interiéru aj mimo hlavného osvetlenia. Pri výbere miesta zvážte pohľadové strany, prístup k napájaniu a vzťah k ostatným zdrojom svetla. Konkrétne režimy a spôsob ovládania sa riadia dodávaným variantom. Detailná dekorácia dokáže zmeniť dojem z pracovného kútika bez zásahu do celého interiéru. Inšpirácia mestom a sci-fi estetikou sa hodí vedľa klávesnice, modelov alebo technických zbierok."},{"code":"OKL-026","name_cs":"Retro LED hodiny ve stylu Nixie","name_t":"Retro LED hodiny v štýle Nixie","short_cs_text":"Hodiny rozdělují časový údaj do řady samostatných zobrazovacích prvků. Jejich vzhled odkazuje na historické číslicové výbojky. Jde o moderní elektronické zobrazení ve stylu Nixie, jehož vizuální charakter vytvářejí digitální motivy. Jednotlivé displeje zobrazují barevné číslice a další podporované grafické motivy. Průhledné kryty dávají každému prvku prostorový vzhled. Změna obrazu tak ovlivňuje charakter celého časového panelu. Řada zobrazovacích modulů je upevněna na podlouhlé základně. Ta propojuje elektroniku a drží jednotlivé prvky v rovnoměrných odstupech. Konstrukce kombinuje praktické digitální hodiny s výrazným dekorativním objektem.","short_t_text":"Hodiny rozdeľujú časový údaj do radu samostatných zobrazovacích prvkov. Ich vzhľad odkazuje na historické číslicové výbojky. Ide o moderné elektronické zobrazenie v štýle Nixie, ktorého vizuálny charakter vytvárajú digitálne motívy. Jednotlivé displeje zobrazujú farebné číslice a ďalšie podporované grafické motívy. Priehľadné kryty dávajú každému prvku priestorový vzhľad. Zmena obrazu tak ovplyvňuje charakter celého časového panela. Rad zobrazovacích modulov je upevnený na podlhovastej základni. Tá prepája elektroniku a drží jednotlivé prvky v rovnomerných odstupoch. Konštrukcia kombinuje praktické digitálne hodiny s výrazným dekoratívnym objektom.","short_t_html":"\n                            Hodiny rozdeľujú časový údaj do radu samostatných zobrazovacích prvkov. Ich vzhľad odkazuje na historické číslicové výbojky. Ide o moderné elektronické zobrazenie v štýle Nixie, ktorého vizuálny charakter vytvárajú digitálne motívy. Jednotlivé displeje zobrazujú farebné číslice a ďalšie podporované grafické motívy. Priehľadné kryty dávajú každému prvku priestorový vzhľad. Zmena obrazu tak ovplyvňuje charakter celého časového panela. Rad zobrazovacích modulov je upevnený na podlhovastej základni. Tá prepája elektroniku a drží jednotlivé prvky v rovnomerných odstupoch. Konštrukcia kombinuje praktické digitálne hodiny s výrazným dekoratívnym objektom.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Retro LED hodiny v štýle Nixie</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Samostatné číslice v štýle Nixie</h3><p>Hodiny rozdeľujú časový údaj do radu samostatných zobrazovacích prvkov. Ich vzhľad odkazuje na historické číslicové výbojky. Ide o moderné elektronické zobrazenie v štýle Nixie, ktorého vizuálny charakter vytvárajú digitálne motívy.</p><p style=\"margin-top:16px\">Rozdelenie časového údaja do oddelených prvkov zachováva charakteristický vzhľad radu svietiacich číslic. Elektronicky vytváraný motív pritom určuje skutočnú podobu zobrazenia. Retro dojem vychádza zo spojenia tvaru krytov, rozostupov jednotlivých častí a grafiky, ktorá pripomína vzhľad historických číslicových prístrojov.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-026-function-1.jpg\" alt=\"Retro LED hodiny v štýle Nixie – Samostatné číslice v štýle Nixie\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Digitálne motívy v priehľadných krytoch</h3><p>Jednotlivé displeje zobrazujú farebné číslice a ďalšie podporované grafické motívy. Priehľadné kryty dávajú každému prvku priestorový vzhľad. Zmena obrazu tak ovplyvňuje charakter celého časového panela.</p><p style=\"margin-top:16px\">Zobrazená číslica je tvorená digitálnym obrazom vo vnútri konkrétneho modulu. Priehľadný kryt oddeľuje jednotlivé prvky a zdôrazňuje ich výšku nad základňou. Farba a kresba motívu sa podieľajú na výslednom vzhľade hodín v rozsahu možností softvéru, ktorý riadi zobrazenie jednotlivých častí.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-026-function-2.jpg\" alt=\"Retro LED hodiny v štýle Nixie – Digitálne motívy v priehľadných krytoch\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Spoločná stolová základňa</h3><p>Rad zobrazovacích modulov je upevnený na podlhovastej základni. Tá prepája elektroniku a drží jednotlivé prvky v rovnomerných odstupoch. Konštrukcia kombinuje praktické digitálne hodiny s výrazným dekoratívnym objektom.</p><p style=\"margin-top:16px\">Základňa zjednocuje rad modulov do jedného stolového zariadenia a zabezpečuje ich mechanické usporiadanie. Pravidelné rozmiestnenie podporuje čitateľnosť oddelených číslic ako spoločného časového údaja. Podlhovastá konštrukcia zároveň ponecháva každý prvok vizuálne samostatný, čo je charakteristickou súčasťou dekoratívneho vzhľadu tohto typu hodín.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-026-function-3.jpg\" alt=\"Retro LED hodiny v štýle Nixie – Spoločná stolová základňa\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Designové gadgety","Kategória:","Dizajnové gadgety"],["Kategorie:","Designové gadgety","Kategória:","Dizajnové gadgety"],["Typ produktu:","Stolní digitální hodiny","Typ produktu:","Stolové digitálne hodiny"],["Vizuální styl:","Nixie style","Vizuálny štýl:","Nixie style"],["Světelná technologie:","LED","Svetelná technológia:","LED"],["Primární funkce:","Zobrazení času","Primárna funkcia:","Zobrazenie času"],["Umístění:","Pracovní stůl nebo police","Umiestnenie:","Pracovný stôl alebo polica"],["Konstrukční poznámka:","LED stylizace, ne potvrzené výbojky Nixie","Konštrukčná poznámka:","LED štylizácia, nie potvrdené výbojky Nixie"]],"catalog_names":{"Retro LED hodiny Nixie style":"Retro LED hodiny Nixie style","Retro LED hodiny ve stylu Nixie":"Retro LED hodiny v štýle Nixie"},"catalog_short_cs":"Propojte vzhled historických číslic s moderním LED provedením. Stolní hodiny ve stylu Nixie jsou výrazným doplňkem pracovního stolu, knihovny nebo interiéru s technickou estetikou. Nabízejí jiný vizuální zážitek než běžný plochý displej a nechávají vyniknout samotné zobrazení času. Jde o LED stylizaci, nikoli automaticky o originální plynové výbojky Nixie. Při výběru místa zvažte čitelnost, okolní světlo a pohodlný přístup k ovládání. Výrazné samostatné číslice připomínají dobu měřicí techniky a prvních elektronických přístrojů. LED pojetí tento vizuální jazyk využívá v dekorativním produktu pro současný interiér.","catalog_short_t":"Prepojte vzhľad historických číslic s moderným LED vyhotovením. Stolové hodiny v štýle Nixie sú výrazným doplnkom pracovného stola, knižnice alebo interiéru s technickou estetikou. Ponúkajú iný vizuálny zážitok než bežný plochý displej a nechávajú vyniknúť samotné zobrazenie času. Ide o LED štylizáciu, nie automaticky o originálne plynové výbojky Nixie. Pri výbere miesta zvážte čitateľnosť, okolité svetlo a pohodlný prístup k ovládaniu. Výrazné samostatné číslice pripomínajú dobu meracej techniky a prvých elektronických prístrojov. LED poňatie tento vizuálny jazyk využíva v dekoratívnom produkte pre súčasný interiér."},{"code":"OKL-027","name_cs":"Ferrofluid Display – magnetická dekorace","name_t":"Ferrofluid Display – magnetická dekorácia","short_cs_text":"Ferrofluid obsahuje jemné magnetické částice rozptýlené v kapalině. Magnetické pole ovlivňuje jeho rozložení a může na povrchu vytvářet výrazné struktury. Změna působení magnetu se projeví přímo v pohybu kapaliny. Průhledná nádoba umožňuje pozorovat přesuny tmavé kapaliny a její rozhraní s okolním prostředím. Kapalina se podle polohy magnetu shlukuje, prodlužuje nebo rozlévá. Zobrazený tvar vzniká fyzikálním působením, nikoli animací na obrazovce. Dekorace zpřístupňuje neobvyklé chování magnetické kapaliny v malém stolním formátu. Skleněná nádoba odděluje kapalinu od okolí a zůstává uzavřená. Tato varianta představuje manuální magnetickou dekoraci bez automatického příslibu reakce na hudbu.","short_t_text":"Ferrofluid obsahuje jemné magnetické častice rozptýlené v kvapaline. Magnetické pole ovplyvňuje jeho rozloženie a môže na povrchu vytvárať výrazné štruktúry. Zmena pôsobenia magnetu sa prejaví priamo v pohybe kvapaliny. Priehľadná nádoba umožňuje pozorovať presuny tmavej kvapaliny a jej rozhranie s okolitým prostredím. Kvapalina sa podľa polohy magnetu zhlukuje, predlžuje alebo rozlieva. Zobrazený tvar vzniká fyzikálnym pôsobením, nie animáciou na obrazovke. Dekorácia sprístupňuje neobvyklé správanie magnetickej kvapaliny v malom stolovom formáte. Sklenená nádoba oddeľuje kvapalinu od okolia a zostáva uzavretá. Tento variant predstavuje manuálnu magnetickú dekoráciu bez automatického prísľubu reakcie na hudbu.","short_t_html":"\n                            Ferrofluid obsahuje jemné magnetické častice rozptýlené v kvapaline. Magnetické pole ovplyvňuje jeho rozloženie a môže na povrchu vytvárať výrazné štruktúry. Zmena pôsobenia magnetu sa prejaví priamo v pohybe kvapaliny. Priehľadná nádoba umožňuje pozorovať presuny tmavej kvapaliny a jej rozhranie s okolitým prostredím. Kvapalina sa podľa polohy magnetu zhlukuje, predlžuje alebo rozlieva. Zobrazený tvar vzniká fyzikálnym pôsobením, nie animáciou na obrazovke. Dekorácia sprístupňuje neobvyklé správanie magnetickej kvapaliny v malom stolovom formáte. Sklenená nádoba oddeľuje kvapalinu od okolia a zostáva uzavretá. Tento variant predstavuje manuálnu magnetickú dekoráciu bez automatického prísľubu reakcie na hudbu.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Ferrofluid Display – magnetická dekorácia</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Magnetická kvapalina reagujúca na pole</h3><p>Ferrofluid obsahuje jemné magnetické častice rozptýlené v kvapaline. Magnetické pole ovplyvňuje jeho rozloženie a môže na povrchu vytvárať výrazné štruktúry. Zmena pôsobenia magnetu sa prejaví priamo v pohybe kvapaliny.</p><p style=\"margin-top:16px\">Tvar povrchu vzniká spoločným pôsobením magnetického poľa a vlastností kvapaliny. Pri zmene polohy magnetu sa mení aj rozloženie sily vo vnútri nádoby. Tmavá náplň tak vytvára pohyblivé útvary, ktorých podoba súvisí s okamžitou polohou magnetu a s geometriou uzavretého priestoru.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-027-function-1.jpg\" alt=\"Ferrofluid Display – magnetická dekorácia – Magnetická kvapalina reagujúca na pole\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Ilustračné zobrazenie funkcie</figcaption></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Premenlivé tvary v uzavretej nádobe</h3><p>Priehľadná nádoba umožňuje pozorovať presuny tmavej kvapaliny a jej rozhranie s okolitým prostredím. Kvapalina sa podľa polohy magnetu zhlukuje, predlžuje alebo rozlieva. Zobrazený tvar vzniká fyzikálnym pôsobením, nie animáciou na obrazovke.</p><p style=\"margin-top:16px\">Priehľadné steny poskytujú priamy pohľad na skutočný materiál a jeho premenu. Kontrast tmavej kvapaliny voči okoliu zvýrazňuje menšie zhluky a zmeny ich tvaru. Každý pohyb magnetu môže zmeniť rovnováhu vo vnútri nádoby a vytvoriť odlišnú priestorovú štruktúru bez elektronicky vykresľovaného obrazu.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-027-function-2.jpg\" alt=\"Ferrofluid Display – magnetická dekorácia – Premenlivé tvary v uzavretej nádobe\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Ilustračné zobrazenie funkcie</figcaption></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Názorná ukážka magnetizmu</h3><p>Dekorácia sprístupňuje neobvyklé správanie magnetickej kvapaliny v malom stolovom formáte. Sklenená nádoba oddeľuje kvapalinu od okolia a zostáva uzavretá. Tento variant predstavuje manuálnu magnetickú dekoráciu bez automatického prísľubu reakcie na hudbu.</p><p style=\"margin-top:16px\">Manuálne ovplyvnenie magnetickým poľom prepája viditeľnú zmenu s pohybom magnetu. Uzavretá nádoba udržiava náplň vo vnútri a umožňuje sledovať jej správanie cez priehľadnú stenu. Celok predstavuje fyzickú ukážku interakcie materiálu s magnetickým poľom, ktorej efekt vzniká priamo pohybom a preskupovaním kvapaliny.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-027-function-3.jpg\" alt=\"Ferrofluid Display – magnetická dekorácia – Názorná ukážka magnetizmu\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Ilustračné zobrazenie funkcie</figcaption></figure></section></article>\n                            ","params":[["Kategorie:","Designové gadgety","Kategória:","Dizajnové gadgety"],["Kategorie:","Designové gadgety","Kategória:","Dizajnové gadgety"],["Typ produktu:","Ferrofluidní dekorace","Typ produktu:","Ferrofluidná dekorácia"],["Označení:","Ferrofluid Display","Označenie:","Ferrofluid Display"],["Pracovní médium:","Magnetická kapalina – ferrofluid","Pracovné médium:","Magnetická kvapalina – ferrofluid"],["Fyzikální princip:","Reakce na magnetické pole","Fyzikálny princíp:","Reakcia na magnetické pole"],["Účel:","Dekorace a názorné pozorování","Účel:","Dekorácia a názorné pozorovanie"],["Umístění:","Stabilní plocha v interiéru","Umiestnenie:","Stabilná plocha v interiéri"]],"catalog_names":{"Ferrofluid Display magnetická dekorace":"Ferrofluid Display magnetická dekorácia","Ferrofluid Display – magnetická dekorace":"Ferrofluid Display – magnetická dekorácia"},"catalog_short_cs":"Přidejte pracovnímu stolu drobný fyzikální experiment. Ferrofluid Display využívá magnetickou kapalinu, která při působení magnetického pole mění tvar a vytváří neobvyklé struktury. Hodí se jako dekorace i jako názorný podnět k objevování vlastností magnetismu. Zaujme uživatele, kteří dávají přednost skutečnému fyzikálnímu efektu před běžnou světelnou animací. Způsob ovlivňování kapaliny a konkrétní ovládání se řídí konstrukcí dodávaného výrobku. Ferrofluid obsahuje jemné magnetické částice rozptýlené v kapalině. Při vhodném působení pole se jeho povrch může uspořádat do výrazných struktur.","catalog_short_t":"Pridajte pracovnému stolu drobný fyzikálny experiment. Ferrofluid Display využíva magnetickú kvapalinu, ktorá pri pôsobení magnetického poľa mení tvar a vytvára neobvyklé štruktúry. Hodí sa ako dekorácia aj ako názorný podnet na objavovanie vlastností magnetizmu. Zaujme používateľov, ktorí uprednostňujú skutočný fyzikálny efekt pred bežnou svetelnou animáciou. Spôsob ovplyvňovania kvapaliny a konkrétne ovládanie sa riadia konštrukciou dodávaného výrobku. Ferrofluid obsahuje jemné magnetické častice rozptýlené v kvapaline. Pri vhodnom pôsobení poľa sa jeho povrch môže usporiadať do výrazných štruktúr."},{"code":"OKL-028","name_cs":"Levitující LED žárovka – magnetická stolní lampa","name_t":"Levitujúca LED žiarovka – magnetická stolová lampa","short_cs_text":"Magnetické působení udržuje žárovkový světelný prvek nad podstavcem. Mezi oběma částmi zůstává viditelná mezera. Konstrukce tak vytváří skutečný prostorový levitační efekt bez pevného ramene mezi žárovkou a základnou. Průhledná baňka odhaluje světelnou část a doplňuje tvar klasické žárovky. Rozsvícení zvýrazňuje plovoucí objekt i mezeru nad základnou. Lampa slouží jako dekorativní světelný prvek interiéru. Podstavec obsahuje elektroniku pro provoz magnetické sestavy a připojení napájení. Žárovka tvoří oddělenou pohyblivou část. Dřevěně působící povrch základny doplňuje průhledné a kovové části světelného objektu.","short_t_text":"Magnetické pôsobenie udržiava žiarovkový svetelný prvok nad podstavcom. Medzi oboma časťami zostáva viditeľná medzera. Konštrukcia tak vytvára skutočný priestorový levitačný efekt bez pevného ramena medzi žiarovkou a základňou. Priehľadná banka odhaľuje svetelnú časť a dopĺňa tvar klasickej žiarovky. Rozsvietenie zvýrazňuje plávajúci objekt aj medzeru nad základňou. Lampa slúži ako dekoratívny svetelný prvok interiéru. Podstavec obsahuje elektroniku na prevádzku magnetickej zostavy a pripojenie napájania. Žiarovka tvorí oddelenú pohyblivú časť. Povrch základne s drevenou optikou dopĺňa priehľadné a kovové časti svetelného objektu.","short_t_html":"\n                            Magnetické pôsobenie udržiava žiarovkový svetelný prvok nad podstavcom. Medzi oboma časťami zostáva viditeľná medzera. Konštrukcia tak vytvára skutočný priestorový levitačný efekt bez pevného ramena medzi žiarovkou a základňou. Priehľadná banka odhaľuje svetelnú časť a dopĺňa tvar klasickej žiarovky. Rozsvietenie zvýrazňuje plávajúci objekt aj medzeru nad základňou. Lampa slúži ako dekoratívny svetelný prvok interiéru. Podstavec obsahuje elektroniku na prevádzku magnetickej zostavy a pripojenie napájania. Žiarovka tvorí oddelenú pohyblivú časť. Povrch základne s drevenou optikou dopĺňa priehľadné a kovové časti svetelného objektu.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Levitujúca LED žiarovka – magnetická stolová lampa</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Svetelný prvok nad základňou</h3><p>Magnetické pôsobenie udržiava žiarovkový svetelný prvok nad podstavcom. Medzi oboma časťami zostáva viditeľná medzera. Konštrukcia tak vytvára skutočný priestorový levitačný efekt bez pevného ramena medzi žiarovkou a základňou.</p><p style=\"margin-top:16px\">Levitačná zostava vyvažuje pôsobiace sily tak, aby svetelná časť zostávala oddelená od podstavca. Viditeľná medzera je súčasťou skutočného mechanického usporiadania lampy. Žiarovkový prvok a základňa vytvárajú dve oddelené časti, ktorých vzájomná poloha určuje charakter celého dekoratívneho efektu.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-028-function-1.jpg\" alt=\"Levitujúca LED žiarovka – magnetická stolová lampa – Svetelný prvok nad základňou\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>LED svetlo v dekoratívnej žiarovke</h3><p>Priehľadná banka odhaľuje svetelnú časť a dopĺňa tvar klasickej žiarovky. Rozsvietenie zvýrazňuje plávajúci objekt aj medzeru nad základňou. Lampa slúži ako dekoratívny svetelný prvok interiéru.</p><p style=\"margin-top:16px\">Priehľadné vyhotovenie umožňuje vidieť svetelnú časť vo vnútri banky a súčasne sledovať jej polohu nad podstavcom. Svetlo zvýrazňuje obrys žiarovky a okolitý priestor. Kombinácia známeho tvaru banky s magnetickým zavesením vytvára stolovú dekoráciu, ktorej účinok stojí na skutočnej medzere medzi časťami.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-028-function-2.jpg\" alt=\"Levitujúca LED žiarovka – magnetická stolová lampa – LED svetlo v dekoratívnej žiarovke\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Podstavec a napájacie riešenie</h3><p>Podstavec obsahuje elektroniku na prevádzku magnetickej zostavy a pripojenie napájania. Žiarovka tvorí oddelenú pohyblivú časť. Povrch základne s drevenou optikou dopĺňa priehľadné a kovové časti svetelného objektu.</p><p style=\"margin-top:16px\">Napájací prívod vedie do základne, ktorá tvorí pevnú časť zostavy. Jej telo zároveň vymedzuje plochu pod levitujúcim prvkom a nesie prevádzkovú elektroniku. Spojenie pevného podstavca a oddelenej svetelnej časti určuje priestorové usporiadanie lampy aj jej výrazný vzhľad pri pohľade z rôznych strán.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-028-function-3.jpg\" alt=\"Levitujúca LED žiarovka – magnetická stolová lampa – Podstavec a napájacie riešenie\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Designové gadgety","Kategória:","Dizajnové gadgety"],["Kategorie:","Designové gadgety","Kategória:","Dizajnové gadgety"],["Typ produktu:","Levitující stolní lampa","Typ produktu:","Levitujúca stolová lampa"],["Světelný prvek:","LED žárovka","Svetelný prvok:","LED žiarovka"],["Princip:","Magnetická levitace","Princíp:","Magnetická levitácia"],["Sestava:","Základna a levitující část","Zostava:","Základňa a levitujúca časť"],["Primární účel:","Dekorativní osvětlení","Primárny účel:","Dekoratívne osvetlenie"],["Umístění:","Rovná stabilní plocha v interiéru","Umiestnenie:","Rovná stabilná plocha v interiéri"]],"catalog_names":{"Levitující LED žárovka magnetická stolní lampa":"Levitujúca LED žiarovka magnetická stolová lampa","Levitující LED žárovka – magnetická stolní lampa":"Levitujúca LED žiarovka – magnetická stolová lampa"},"catalog_short_cs":"Světelný bod, který upoutá pozornost i bez výrazných barev. Levitující LED žárovka využívá magnetický princip k vznášení nad základnou a tvoří originální dekorativní prvek interiéru. Hodí se na pracovní stůl, komodu nebo místo, kde může vyniknout její neobvyklé provedení. Při uvádění do provozu je důležité správné usazení a stabilní podklad. Konkrétní způsob napájení, vyvážení a ovládání se řídí dodávanou variantou a jejím návodem. Vizuální efekt vychází z magnetického působení, které při správném nastavení drží světelnou část nad podstavcem. Vzhled se tak liší od běžné lampy s viditelnou podpěrou.","catalog_short_t":"Svetelný bod, ktorý upúta pozornosť aj bez výrazných farieb. Levitujúca LED žiarovka využíva magnetický princíp na vznášanie sa nad základňou a tvorí originálny dekoratívny prvok interiéru. Hodí sa na pracovný stôl, komodu alebo miesto, kde môže vyniknúť jej neobvyklé vyhotovenie. Pri uvádzaní do prevádzky je dôležité správne usadenie a stabilný podklad. Konkrétny spôsob napájania, vyváženia a ovládania sa riadi dodávaným variantom a jeho návodom. Vizuálny efekt vychádza z magnetického pôsobenia, ktoré pri správnom nastavení drží svetelnú časť nad podstavcom. Vzhľad sa tak líši od bežnej lampy s viditeľnou podperou."},{"code":"OKL-029","name_cs":"3D holografický LED ventilátor pro prezentace","name_t":"3D holografický LED ventilátor na prezentácie","short_cs_text":"LED prvky na pohybujících se ramenech vytvářejí rychle se opakující světelný vzor. Díky setrvačnosti vidění vzniká dojem souvislého obrazu. Tento princip umožňuje zobrazovat motivy a animace s efektem obrazu ve volném prostoru. Řídicí elektronika časuje rozsvěcení LED podle zobrazovaného obsahu. Výsledkem je dvourozměrná světelná plocha s výrazným prostorovým dojmem vhodně připravené grafiky. Nejde o skutečný objemový hologram pozorovatelný stejně ze všech směrů. Zařízení tvoří centrální motorová část a ramena osazená světelnými prvky. Elektronika propojuje pohyb ramen se zobrazovaným vzorem. Otevřená rotující konstrukce je určena pro pevnou instalaci s řešením ochrany odpovídajícím konkrétnímu modelu.","short_t_text":"LED prvky na pohybujúcich sa ramenách vytvárajú rýchlo sa opakujúci svetelný vzor. Vďaka zotrvačnosti videnia vzniká dojem súvislého obrazu. Tento princíp umožňuje zobrazovať motívy a animácie s efektom obrazu vo voľnom priestore. Riadiaca elektronika časuje rozsvecovanie LED podľa zobrazovaného obsahu. Výsledkom je dvojrozmerná svetelná plocha s výrazným priestorovým dojmom vhodne pripravenej grafiky. Nejde o skutočný objemový hologram pozorovateľný rovnako zo všetkých smerov. Zariadenie tvorí centrálna motorová časť a ramená osadené svetelnými prvkami. Elektronika prepája pohyb ramien so zobrazovaným vzorom. Otvorená rotujúca konštrukcia je určená na pevnú inštaláciu s riešením ochrany zodpovedajúcim konkrétnemu modelu.","short_t_html":"\n                            LED prvky na pohybujúcich sa ramenách vytvárajú rýchlo sa opakujúci svetelný vzor. Vďaka zotrvačnosti videnia vzniká dojem súvislého obrazu. Tento princíp umožňuje zobrazovať motívy a animácie s efektom obrazu vo voľnom priestore. Riadiaca elektronika časuje rozsvecovanie LED podľa zobrazovaného obsahu. Výsledkom je dvojrozmerná svetelná plocha s výrazným priestorovým dojmom vhodne pripravenej grafiky. Nejde o skutočný objemový hologram pozorovateľný rovnako zo všetkých smerov. Zariadenie tvorí centrálna motorová časť a ramená osadené svetelnými prvkami. Elektronika prepája pohyb ramien so zobrazovaným vzorom. Otvorená rotujúca konštrukcia je určená na pevnú inštaláciu s riešením ochrany zodpovedajúcim konkrétnemu modelu.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>3D holografický LED ventilátor na prezentácie</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Rotujúce LED na vytvorenie súvislého obrazu</h3><p>LED prvky na pohybujúcich sa ramenách vytvárajú rýchlo sa opakujúci svetelný vzor. Vďaka zotrvačnosti videnia vzniká dojem súvislého obrazu. Tento princíp umožňuje zobrazovať motívy a animácie s efektom obrazu vo voľnom priestore.</p><p style=\"margin-top:16px\">Každá svietiaca časť počas otáčania prechádza rôznymi miestami zobrazovacej plochy. Presné načasovanie svetla skladá jednotlivé body do viditeľného motívu. Obraz preto vzniká kombináciou mechanického pohybu a elektronického riadenia, pričom rýchlo opakovaný svetelný priebeh vníma pozorovateľ ako celok namiesto oddelených ramien.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-029-function-1.jpg\" alt=\"3D holografický LED ventilátor na prezentácie – Rotujúce LED na vytvorenie súvislého obrazu\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Ilustračné zobrazenie funkcie</figcaption></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Animácie a vlastné obrazové motívy</h3><p>Riadiaca elektronika časuje rozsvecovanie LED podľa zobrazovaného obsahu. Výsledkom je dvojrozmerná svetelná plocha s výrazným priestorovým dojmom vhodne pripravenej grafiky. Nejde o skutočný objemový hologram pozorovateľný rovnako zo všetkých smerov.</p><p style=\"margin-top:16px\">Obsah s vhodným pozadím a tieňovaním môže zvýrazniť dojem samostatného predmetu v priestore. Skutočná zobrazovacia oblasť však zostáva viazaná na dráhu rotujúcich LED. Podobu animácie určuje pripravený súbor a možnosti riadiacej elektroniky, ktorá prevádza obrazové informácie na časované rozsvecovanie jednotlivých svetelných bodov.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-029-function-2.jpg\" alt=\"3D holografický LED ventilátor na prezentácie – Animácie a vlastné obrazové motívy\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Ilustračné zobrazenie funkcie</figcaption></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Viacramenná konštrukcia</h3><p>Zariadenie tvorí centrálna motorová časť a ramená osadené svetelnými prvkami. Elektronika prepája pohyb ramien so zobrazovaným vzorom. Otvorená rotujúca konštrukcia je určená na pevnú inštaláciu s riešením ochrany zodpovedajúcim konkrétnemu modelu.</p><p style=\"margin-top:16px\">Centrálna časť zabezpečuje pohyb a ramená nesú svetelné body na vykresľovanie obsahu. Ich vzájomné usporiadanie tvorí funkčnú zobrazovaciu zostavu s pohyblivými časťami. Spôsob uchytenia a ochranné riešenie nadväzujú na konkrétny model, pretože priestor okolo rotujúcich ramien je zároveň pracovnou oblasťou zariadenia.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-029-function-3.jpg\" alt=\"3D holografický LED ventilátor na prezentácie – Viacramenná konštrukcia\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Ilustračné zobrazenie funkcie</figcaption></figure></section></article>\n                            ","params":[["Kategorie:","Designové gadgety","Kategória:","Dizajnové gadgety"],["Kategorie:","Designové gadgety","Kategória:","Dizajnové gadgety"],["Typ produktu:","Holografický LED ventilátor","Typ produktu:","Holografický LED ventilátor"],["Princip zobrazení:","Rotující LED a setrvačnost vidění","Princíp zobrazenia:","Rotujúce LED a zotrvačnosť videnia"],["Zobrazovaný obsah:","Podporované animace a obrazové motivy","Zobrazovaný obsah:","Podporované animácie a obrazové motívy"],["Umístění:","Vhodná instalace v interiéru","Umiestnenie:","Vhodná inštalácia v interiéri"],["Účel:","Vizuální prezentace a dekorace","Účel:","Vizuálna prezentácia a dekorácia"],["Konstrukce:","Zařízení s pohybujícími se částmi","Konštrukcia:","Zariadenie s pohybujúcimi sa časťami"]],"catalog_names":{"3D holografický LED ventilátor":"3D holografický LED ventilátor","3D holografický LED ventilátor pro prezentace":"3D holografický LED ventilátor na prezentácie"},"catalog_short_cs":"Vytvořte poutavou vizuální prezentaci, která působí jako obraz ve vzduchu. Holografický LED ventilátor využívá rotující světelné prvky a vhodně připravený obsah k neobvyklému prostorovému dojmu. Uplatní se v interiérové dekoraci, na výstavce nebo při prezentaci produktů. Výsledek závisí na animaci, pozadí a pozici diváka. Před instalací ověřte způsob montáže, ochranu pohybujících se částí a možnosti nahrávání obsahu u konkrétní varianty. Vnímání rychle se opakujícího světelného vzoru umožňuje vytvořit dojem souvislého obrazu. Označení holografický ventilátor se používá pro tento typ prezentace, neznamená však automaticky skutečný objemový hologram viditelný stejně ze všech směrů.","catalog_short_t":"Vytvorte pútavú vizuálnu prezentáciu, ktorá pôsobí ako obraz vo vzduchu. Holografický LED ventilátor využíva rotujúce svetelné prvky a vhodne pripravený obsah na vytvorenie neobvyklého priestorového dojmu. Uplatní sa v interiérovej dekorácii, na výstave alebo pri prezentácii produktov. Výsledok závisí od animácie, pozadia a pozície diváka. Pred inštaláciou overte spôsob montáže, ochranu pohybujúcich sa častí a možnosti nahrávania obsahu pri konkrétnom variante. Vnímanie rýchlo sa opakujúceho svetelného vzoru umožňuje vytvoriť dojem súvislého obrazu. Označenie holografický ventilátor sa používa pre tento typ prezentácie, neznamená však automaticky skutočný objemový hologram viditeľný rovnako zo všetkých smerov."},{"code":"OKL-030","name_cs":"WANBO X5 Pro – chytrý Full HD projektor","name_t":"WANBO X5 Pro – chytrý Full HD projektor","short_cs_text":"WANBO X5 Pro používá zobrazovací rozlišení 1920 × 1080 pixelů. Projekce přenáší obraz na plátno nebo vhodný povrch a vytváří velkou zobrazovací plochu. Nativní počet pixelů popisuje fyzické rozlišení obrazu projektoru. Automatické zaostření upravuje ostrost promítaného obrazu. Optická část je umístěna na čele zařízení a doplněna elektronickým řízením. Funkce zjednodušuje přípravu projekce při změně polohy projektoru. Projektor propojuje zobrazovací část s podporovanými chytrými funkcemi a vstupy pro obsah. Zadní panel sdružuje konektory a větrací otvory. Široké stolní tělo této edice má tmavé provedení s jemným zlatým akcentem na čelní hraně.","short_t_text":"WANBO X5 Pro používa zobrazovacie rozlíšenie 1920 × 1080 pixelov. Projekcia prenáša obraz na plátno alebo vhodný povrch a vytvára veľkú zobrazovaciu plochu. Natívny počet pixelov opisuje fyzické rozlíšenie obrazu projektora. Automatické zaostrenie upravuje ostrosť premietaného obrazu. Optická časť je umiestnená na čele zariadenia a doplnená elektronickým riadením. Funkcia zjednodušuje prípravu projekcie pri zmene polohy projektora. Projektor prepája zobrazovaciu časť s podporovanými chytrými funkciami a vstupmi pre obsah. Zadný panel združuje konektory a vetracie otvory. Široké stolové telo tejto edície má tmavé vyhotovenie s jemným zlatým akcentom na čelnej hrane.","short_t_html":"\n                            WANBO X5 Pro používa zobrazovacie rozlíšenie 1920 × 1080 pixelov. Projekcia prenáša obraz na plátno alebo vhodný povrch a vytvára veľkú zobrazovaciu plochu. Natívny počet pixelov opisuje fyzické rozlíšenie obrazu projektora. Automatické zaostrenie upravuje ostrosť premietaného obrazu. Optická časť je umiestnená na čele zariadenia a doplnená elektronickým riadením. Funkcia zjednodušuje prípravu projekcie pri zmene polohy projektora. Projektor prepája zobrazovaciu časť s podporovanými chytrými funkciami a vstupmi pre obsah. Zadný panel združuje konektory a vetracie otvory. Široké stolové telo tejto edície má tmavé vyhotovenie s jemným zlatým akcentom na čelnej hrane.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>WANBO X5 Pro – chytrý Full HD projektor</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Natívne Full HD rozlíšenie</h3><p>WANBO X5 Pro používa zobrazovacie rozlíšenie 1920 × 1080 pixelov. Projekcia prenáša obraz na plátno alebo vhodný povrch a vytvára veľkú zobrazovaciu plochu. Natívny počet pixelov opisuje fyzické rozlíšenie obrazu projektora.</p><p style=\"margin-top:16px\">Full HD panel vytvára obraz z pevne danej siete pixelov, ktorá určuje jeho základnú jemnosť. Premietaná plocha je oddelená od tela zariadenia a jej veľkosť súvisí s projekčným usporiadaním. Čitateľnosť jemných detailov sa tak odvíja od rozlíšenia, zaostrenia a podmienok na projekčnom povrchu.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-030-function-1.jpg\" alt=\"WANBO X5 Pro – chytrý Full HD projektor – Natívne Full HD rozlíšenie\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Automatické zaostrovanie</h3><p>Automatické zaostrenie upravuje ostrosť premietaného obrazu. Optická časť je umiestnená na čele zariadenia a doplnená elektronickým riadením. Funkcia zjednodušuje prípravu projekcie pri zmene polohy projektora.</p><p style=\"margin-top:16px\">Zaostrovanie prispôsobuje optické zobrazenie vzdialenosti medzi projektorom a projekčnou plochou. Správne zaostrený obraz pomáha rozlíšiť drobný text a hrany objektov v rámci natívneho rozlíšenia. Automatické riadenie tejto časti nadväzuje na umiestnenie prístroja a obmedzuje potrebu ručnej manipulácie so zaostrovacím mechanizmom.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-030-function-2.jpg\" alt=\"WANBO X5 Pro – chytrý Full HD projektor – Automatické zaostrovanie\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Chytré prehrávanie a konektory</h3><p>Projektor prepája zobrazovaciu časť s podporovanými chytrými funkciami a vstupmi pre obsah. Zadný panel združuje konektory a vetracie otvory. Široké stolové telo tejto edície má tmavé vyhotovenie s jemným zlatým akcentom na čelnej hrane.</p><p style=\"margin-top:16px\">Prehrávacia časť a fyzické vstupy tvoria rôzne cesty na privedenie podporovaného obsahu do projekčného systému. Dostupnosť konkrétnej aplikácie alebo formátu vychádza z výbavy danej edície. Vetracia časť odvádza teplo z prevádzkovej elektroniky a zadné konektory sústreďujú pripojenie v jednej časti tela.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-030-function-3.jpg\" alt=\"WANBO X5 Pro – chytrý Full HD projektor – Chytré prehrávanie a konektory\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Projektory a obraz","Kategória:","Projektory a obraz"],["Výrobce:","WANBO","Výrobca:","WANBO"],["Kategorie:","Projektory a obraz","Kategória:","Projektory a obraz"],["Model:","X5 Pro","Model:","X5 Pro"],["Rozlišení:","Full HD","Rozlíšenie:","Full HD"],["Typ produktu:","Chytrý domácí projektor","Typ produktu:","Chytrý domáci projektor"],["Nativní rozlišení:","1920 × 1080 px","Natívne rozlíšenie:","1920 × 1080 px"],["Třída rozlišení:","Full HD","Trieda rozlíšenia:","Full HD"],["Ostření:","Automatické","Zaostrovanie:","Automatické"],["Určení:","Domácí promítání","Určenie:","Domáce premietanie"],["Projekční plocha:","Vhodná stěna nebo plátno","Projekčná plocha:","Vhodná stena alebo plátno"]],"catalog_names":{"Chytrý Full HD projektor WANBO X5 Pro":"Chytrý Full HD projektor WANBO X5 Pro","WANBO X5 Pro – chytrý Full HD projektor":"WANBO X5 Pro – chytrý Full HD projektor"},"catalog_short_cs":"Proměňte vybranou stěnu nebo projekční plátno ve větší obraz pro filmy a společné sledování. WANBO X5 Pro spojuje nativní Full HD rozlišení s automatickým ostřením a chytrými funkcemi. Hodí se pro domácí kino, které nechcete omezit na běžnou velikost televizoru. Při umístění zvažte vzdálenost, plochu a okolní světlo. Dostupnost aplikací, rozhraní a přesné parametry posuzujte podle dodávané verze X5 Pro, protože jednotlivé edice nemusejí být shodné. Nativní rozlišení 1920 × 1080 pixelů tvoří základ detailního obrazu při sledování vhodného obsahu. Výsledný dojem ale ovlivňuje také projekční plocha, vzdálenost a zatemnění.","catalog_short_t":"Premeňte vybranú stenu alebo projekčné plátno na veľký obraz na sledovanie filmov a spoločné pozeranie. WANBO X5 Pro spája natívne Full HD rozlíšenie s automatickým zaostrovaním a chytrými funkciami. Hodí sa na domáce kino, ktoré nechcete obmedziť na bežnú veľkosť televízora. Pri umiestnení zvážte vzdialenosť, plochu a okolité svetlo. Dostupnosť aplikácií, rozhraní a presné parametre posudzujte podľa dodávanej verzie X5 Pro, pretože jednotlivé edície nemusia byť zhodné. Natívne rozlíšenie 1920 × 1080 pixelov tvorí základ detailného obrazu pri sledovaní vhodného obsahu. Výsledný dojem však ovplyvňuje aj projekčná plocha, vzdialenosť a zatemnenie."},{"code":"OKL-031","name_cs":"Retro hodinky s průhledným pouzdrem a digitálním displejem","name_t":"Retro hodinky s priehľadným puzdrom a digitálnym displejom","short_cs_text":"Hodinky kombinují klasické analogové ručičky s malou digitální částí. Oba způsoby zobrazení jsou umístěny pod společným krycím sklem. Tmavý číselník vytváří kontrast k ručičkám a průhlednému tělu. Fyzická tlačítka jsou dostupná po stranách pouzdra. Slouží k ovládání podporovaných nastavení a funkcí digitální části. Ciferník, elektronika a ovládací prvky tvoří samostatné náramkové zařízení bez nutnosti telefonu. Tvarované pouzdro doplňuje průhledný řemínek s nastavitelným zapínáním. Otevřená struktura materiálu zvýrazňuje technický vzhled hodinek. Řemínek drží ciferník na zápěstí a umožňuje upravit obvod podle polohy přezky.","short_t_text":"Hodinky kombinujú klasické analógové ručičky s malou digitálnou časťou. Oba spôsoby zobrazenia sú umiestnené pod spoločným krycím sklom. Tmavý ciferník vytvára kontrast k ručičkám a priehľadnému telu. Fyzické tlačidlá sú dostupné po stranách puzdra. Slúžia na ovládanie podporovaných nastavení a funkcií digitálnej časti. Ciferník, elektronika a ovládacie prvky tvoria samostatné náramkové zariadenie bez nutnosti telefónu. Tvarované puzdro dopĺňa priehľadný remienok s nastaviteľným zapínaním. Otvorená štruktúra materiálu zvýrazňuje technický vzhľad hodiniek. Remienok drží ciferník na zápästí a umožňuje upraviť obvod podľa polohy pracky.","short_t_html":"\n                            Hodinky kombinujú klasické analógové ručičky s malou digitálnou časťou. Oba spôsoby zobrazenia sú umiestnené pod spoločným krycím sklom. Tmavý ciferník vytvára kontrast k ručičkám a priehľadnému telu. Fyzické tlačidlá sú dostupné po stranách puzdra. Slúžia na ovládanie podporovaných nastavení a funkcií digitálnej časti. Ciferník, elektronika a ovládacie prvky tvoria samostatné náramkové zariadenie bez nutnosti telefónu. Tvarované puzdro dopĺňa priehľadný remienok s nastaviteľným zapínaním. Otvorená štruktúra materiálu zvýrazňuje technický vzhľad hodiniek. Remienok drží ciferník na zápästí a umožňuje upraviť obvod podľa polohy pracky.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Retro hodinky s priehľadným puzdrom a digitálnym displejom</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Ručičky a digitálny údaj v jednom ciferníku</h3><p>Hodinky kombinujú klasické analógové ručičky s malou digitálnou časťou. Oba spôsoby zobrazenia sú umiestnené pod spoločným krycím sklom. Tmavý ciferník vytvára kontrast k ručičkám a priehľadnému telu.</p><p style=\"margin-top:16px\">Analógová časť udáva čas polohou ručičiek, digitálna časť pracuje s číselným zobrazením dostupných údajov. Obe vrstvy zdieľajú jeden ciferník a zostávajú viditeľné na zápästí. Ich kombinácia prepája tradičný spôsob odčítania s elektronickým panelom, ktorého obsah určuje zvolený režim hodiniek.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-031-function-1.jpg\" alt=\"Retro hodinky s priehľadným puzdrom a digitálnym displejom – Ručičky a digitálny údaj v jednom ciferníku\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Ilustračné zobrazenie funkcie</figcaption></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Bočné tlačidlá na ovládanie</h3><p>Fyzické tlačidlá sú dostupné po stranách puzdra. Slúžia na ovládanie podporovaných nastavení a funkcií digitálnej časti. Ciferník, elektronika a ovládacie prvky tvoria samostatné náramkové zariadenie bez nutnosti telefónu.</p><p style=\"margin-top:16px\">Bočné umiestnenie ovládania ponecháva čelnú plochu pre ciferník a jeho čítanie. Tlačidlá odovzdávajú povely vstavanej elektronike bez dotykového panela alebo mobilnej aplikácie. Zmena dostupného zobrazenia a nastavenia prebieha priamo na hodinkách podľa funkcií, ktoré podporuje konkrétny mechanizmus digitálnej časti.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-031-function-2.jpg\" alt=\"Retro hodinky s priehľadným puzdrom a digitálnym displejom – Bočné tlačidlá na ovládanie\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Ilustračné zobrazenie funkcie</figcaption></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Priehľadné puzdro a remienok</h3><p>Tvarované puzdro dopĺňa priehľadný remienok s nastaviteľným zapínaním. Otvorená štruktúra materiálu zvýrazňuje technický vzhľad hodiniek. Remienok drží ciferník na zápästí a umožňuje upraviť obvod podľa polohy pracky.</p><p style=\"margin-top:16px\">Priesvitné časti nechávajú vyniknúť obrys puzdra a väzbu medzi ciferníkom a remienkom. Prackové zapínanie vytvára nastaviteľný uzavretý obvod okolo zápästia. Puzdro sústreďuje zobrazovaciu aj ovládaciu časť, zatiaľ čo remienok zabezpečuje jej mechanické uchytenie v polohe vhodnej na priebežné čítanie času.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-031-function-3.jpg\" alt=\"Retro hodinky s priehľadným puzdrom a digitálnym displejom – Priehľadné puzdro a remienok\" width=\"1200\" height=\"1200\" loading=\"lazy\"><figcaption>Ilustračné zobrazenie funkcie</figcaption></figure></section></article>\n                            ","params":[["Kategorie:","Chytrá elektronika","Kategória:","Inteligentná elektronika"],["Kategorie:","Chytrá elektronika","Kategória:","Inteligentná elektronika"],["Typ produktu:","Analogově-digitální náramkové hodinky","Typ produktu:","Analógovo-digitálne náramkové hodinky"],["Zobrazení:","Ručičky a digitální displej","Zobrazenie:","Ručičky a digitálny displej"],["Primární funkce:","Zobrazení času","Primárna funkcia:","Zobrazenie času"],["Způsob nošení:","Na zápěstí","Spôsob nosenia:","Na zápästí"],["Určení:","Každodenní spotřební doplněk","Určenie:","Každodenný spotrebný doplnok"]],"catalog_names":{"Digitální retro hodinky s LED displejem":"Digitálne retro hodinky s LED displejom"},"catalog_short_cs":"Doplňte každodenní výbavu o jednoduchý retro prvek. Digitální hodinky s LED zobrazením staví na číselném odečtu času a výrazné elektronické estetice. Hodí se pro uživatele, kteří dávají přednost nápaditému digitálnímu vzhledu před klasickými ručičkami. Při výběru zvažte pohodlí na zápěstí, čitelnost a způsob aktivace displeje. Další funkce, typ napájení i případná ochrana proti vodě se řídí konkrétním provedením, nikoli pouze obecným označením retro hodinky. Číselný displej připomíná dobu, kdy elektronické hodinky představovaly výraznou změnu oproti tradičnímu ciferníku. Současné provedení může tento styl doplnit do běžného oblečení bez potřeby dalších chytrých funkcí.","catalog_short_t":"Doplňte každodennú výbavu o jednoduchý retro prvok. Digitálne hodinky s LED zobrazením stavajú na číselnom odčítaní času a výraznej elektronickej estetike. Hodia sa pre používateľov, ktorí uprednostňujú nápaditý digitálny vzhľad pred klasickými ručičkami. Pri výbere zvážte pohodlie na zápästí, čitateľnosť a spôsob aktivácie displeja. Ďalšie funkcie, typ napájania aj prípadná ochrana proti vode sa riadia konkrétnym vyhotovením, nie iba všeobecným označením retro hodinky. Číselný displej pripomína dobu, keď elektronické hodinky predstavovali výraznú zmenu oproti tradičnému ciferníku. Súčasné vyhotovenie môže tento štýl doplniť k bežnému oblečeniu bez potreby ďalších chytrých funkcií."},{"code":"OKL-032","name_cs":"Mini termokamera pro orientační kontrolu","name_t":"Mini termokamera na orientačnú kontrolu","short_cs_text":"Termokamera převádí snímané tepelné záření do barevného obrazu. Různé barvy ukazují rozdíly mezi pozorovanými částmi povrchu. Zobrazení doplňuje běžnou vizuální prohlídku o další informace o zahřívání předmětu. Vestavěný displej ukazuje aktuální teplotní obraz přímo na zařízení. Podporované palety mění způsob barevného rozlišení sledované scény. Samostatné provedení nevyžaduje držet telefon jako hlavní zobrazovací jednotku. Malé tělo soustředí snímací část, displej a ovládání do přenosné kamery. Hodí se pro orientační pozorování tepelných rozdílů na technice i v domácnosti. Údaj se vztahuje k povrchu a závisí také na jeho emisivitě a odrazech okolního záření.","short_t_text":"Termokamera prevádza snímané tepelné žiarenie na farebný obraz. Rôzne farby ukazujú rozdiely medzi pozorovanými časťami povrchu. Zobrazenie dopĺňa bežnú vizuálnu prehliadku o ďalšie informácie o zahrievaní predmetu. Vstavaný displej ukazuje aktuálny teplotný obraz priamo na zariadení. Podporované palety menia spôsob farebného rozlíšenia sledovanej scény. Samostatné vyhotovenie nevyžaduje držať telefón ako hlavnú zobrazovaciu jednotku. Malé telo sústreďuje snímaciu časť, displej a ovládanie do prenosnej kamery. Hodí sa na orientačné pozorovanie tepelných rozdielov na technike aj v domácnosti. Údaj sa vzťahuje na povrch a závisí aj od jeho emisivity a odrazov okolitého žiarenia.","short_t_html":"\n                            Termokamera prevádza snímané tepelné žiarenie na farebný obraz. Rôzne farby ukazujú rozdiely medzi pozorovanými časťami povrchu. Zobrazenie dopĺňa bežnú vizuálnu prehliadku o ďalšie informácie o zahrievaní predmetu. Vstavaný displej ukazuje aktuálny teplotný obraz priamo na zariadení. Podporované palety menia spôsob farebného rozlíšenia sledovanej scény. Samostatné vyhotovenie nevyžaduje držať telefón ako hlavnú zobrazovaciu jednotku. Malé telo sústreďuje snímaciu časť, displej a ovládanie do prenosnej kamery. Hodí sa na orientačné pozorovanie tepelných rozdielov na technike aj v domácnosti. Údaj sa vzťahuje na povrch a závisí aj od jeho emisivity a odrazov okolitého žiarenia.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Mini termokamera na orientačnú kontrolu</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Teplotný obraz povrchu</h3><p>Termokamera prevádza snímané tepelné žiarenie na farebný obraz. Rôzne farby ukazujú rozdiely medzi pozorovanými časťami povrchu. Zobrazenie dopĺňa bežnú vizuálnu prehliadku o ďalšie informácie o zahrievaní predmetu.</p><p style=\"margin-top:16px\">Tepelný snímač zachytáva infračervené žiarenie prichádzajúce z pozorovanej scény. Elektronika prevádza dostupné údaje na obraz, v ktorom možno rozlišovať teplejšie a chladnejšie oblasti. Výstup ukazuje rozloženie povrchových tepelných rozdielov v zornom poli a jeho interpretácia vychádza aj z vlastností konkrétneho materiálu.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-032-function-1.jpg\" alt=\"Mini termokamera na orientačnú kontrolu – Teplotný obraz povrchu\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Farebné palety na vlastnej obrazovke</h3><p>Vstavaný displej ukazuje aktuálny teplotný obraz priamo na zariadení. Podporované palety menia spôsob farebného rozlíšenia sledovanej scény. Samostatné vyhotovenie nevyžaduje držať telefón ako hlavnú zobrazovaciu jednotku.</p><p style=\"margin-top:16px\">Farebné priradenie prevádza teplotné rozdiely na vizuálne odlišné odtiene. Zvolená paleta mení podobu zobrazenia rovnakej scény, nie samotný princíp snímania. Vlastná obrazovka prepája pohľad na predmet s okamžitým odčítaním tepelného obrazu a ponecháva celú zobrazovaciu zostavu v jednom ručnom prístroji.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-032-function-2.jpg\" alt=\"Mini termokamera na orientačnú kontrolu – Farebné palety na vlastnej obrazovke\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Kompaktné ručné vyhotovenie</h3><p>Malé telo sústreďuje snímaciu časť, displej a ovládanie do prenosnej kamery. Hodí sa na orientačné pozorovanie tepelných rozdielov na technike aj v domácnosti. Údaj sa vzťahuje na povrch a závisí aj od jeho emisivity a odrazov okolitého žiarenia.</p><p style=\"margin-top:16px\">Ručne vedená kamera umožňuje porovnávať viditeľné tepelné oblasti medzi rôznymi časťami predmetu. Snímaná informácia sa vzťahuje na žiarenie prichádzajúce z povrchu, takže lesklé materiály môžu v obraze odrážať aj okolie. Kamera poskytuje ďalší pohľad na prevádzkové zahrievanie v medziach svojich parametrov a podporovaných funkcií.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-032-function-3.jpg\" alt=\"Mini termokamera na orientačnú kontrolu – Kompaktné ručné vyhotovenie\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Měřicí technika a nářadí","Kategória:","Meracia technika a náradie"],["Kategorie:","Měřicí technika a nářadí","Kategória:","Meracia technika a náradie"],["Typ produktu:","Mini termokamera","Typ produktu:","Mini termokamera"],["Princip:","Termální zobrazení povrchů","Princíp:","Termálne zobrazenie povrchov"],["Provedení:","Kompaktní","Vyhotovenie:","Kompaktné"],["Účel:","Orientační kontrola teplotních rozdílů","Účel:","Orientačná kontrola teplotných rozdielov"],["Pozorovaný objekt:","Povrch zařízení nebo materiálu","Pozorovaný objekt:","Povrch zariadenia alebo materiálu"],["Interpretace:","Podle emisivity a okolních podmínek","Interpretácia:","Podľa emisivity a okolitých podmienok"]],"catalog_names":{"Mini termokamera":"Mini termokamera","Mini termokamera pro orientační kontrolu":"Mini termokamera na orientačnú kontrolu"},"catalog_short_cs":"Objevte teplotní rozdíly, které běžným pohledem neuvidíte. Mini termokamera se hodí pro orientační kontrolu povrchů, zařízení a míst, která chcete porovnat z hlediska zahřívání. Tepelné zobrazení může pomoci vybrat oblast pro další prověření a lépe dokumentovat rozdíly mezi jednotlivými stavy. Výsledky vždy souvisejí s materiálem, podmínkami a nastavením přístroje. Kompaktní provedení nenahrazuje odborný postup při přesné diagnostice a neznamená pohled skrz stěnu. Teplotní obraz zobrazuje rozdíly, které se při běžné vizuální prohlídce nemusí projevit. Může ukázat místo odlišného zahřívání nebo pomoci porovnat stav před změnou a po ní.","catalog_short_t":"Objavte teplotné rozdiely, ktoré bežným pohľadom neuvidíte. Mini termokamera sa hodí na orientačnú kontrolu povrchov, zariadení a miest, ktoré chcete porovnať z hľadiska zahrievania. Tepelné zobrazenie môže pomôcť vybrať oblasť na ďalšie preverenie a lepšie zdokumentovať rozdiely medzi jednotlivými stavmi. Výsledky vždy súvisia s materiálom, podmienkami a nastavením prístroja. Kompaktné vyhotovenie nenahrádza odborný postup pri presnej diagnostike a neznamená pohľad cez stenu. Teplotný obraz zobrazuje rozdiely, ktoré sa pri bežnej vizuálnej prehliadke nemusia prejaviť. Môže ukázať miesto odlišného zahrievania alebo pomôcť porovnať stav pred zmenou a po nej."},{"code":"OKL-033","name_cs":"Univerzální tester elektronických součástek","name_t":"Univerzálny tester elektronických súčiastok","short_cs_text":"Tester pracuje s vybranými samostatnými elektronickými součástkami. Připojený prvek vyhodnotí v rozsahu podporovaných režimů a výsledek zobrazí na obrazovce. Tato funkce usnadňuje základní třídění a orientační kontrolu drobných dílů. Číselné a grafické údaje na displeji propojují rozpoznaný typ součástky s dostupnými hodnotami. Výsledek je přístupný přímo na přístroji. Vlastní obrazovka a ovládací prvek vytvářejí samostatnou pomůcku pro výuku i hobby elektroniku. Páčková patice usnadňuje připojení vývodů podporovaných součástek. Průhledný kryt ponechává viditelnou desku a současně drží konstrukci přístroje pohromadě. Tester je určen pro odpojené a připravené součástky v přípustném měřicím rozsahu.","short_t_text":"Tester pracuje s vybranými samostatnými elektronickými súčiastkami. Pripojený prvok vyhodnotí v rozsahu podporovaných režimov a výsledok zobrazí na obrazovke. Táto funkcia uľahčuje základné triedenie a orientačnú kontrolu drobných dielov. Číselné a grafické údaje na displeji prepájajú rozpoznaný typ súčiastky s dostupnými hodnotami. Výsledok je prístupný priamo na prístroji. Vlastná obrazovka a ovládací prvok vytvárajú samostatnú pomôcku na výučbu aj hobby elektroniku. Páčková pätica uľahčuje pripojenie vývodov podporovaných súčiastok. Priehľadný kryt ponecháva viditeľnú dosku a súčasne drží konštrukciu prístroja pohromade. Tester je určený na odpojené a pripravené súčiastky v prípustnom meracom rozsahu.","short_t_html":"\n                            Tester pracuje s vybranými samostatnými elektronickými súčiastkami. Pripojený prvok vyhodnotí v rozsahu podporovaných režimov a výsledok zobrazí na obrazovke. Táto funkcia uľahčuje základné triedenie a orientačnú kontrolu drobných dielov. Číselné a grafické údaje na displeji prepájajú rozpoznaný typ súčiastky s dostupnými hodnotami. Výsledok je prístupný priamo na prístroji. Vlastná obrazovka a ovládací prvok vytvárajú samostatnú pomôcku na výučbu aj hobby elektroniku. Páčková pätica uľahčuje pripojenie vývodov podporovaných súčiastok. Priehľadný kryt ponecháva viditeľnú dosku a súčasne drží konštrukciu prístroja pohromade. Tester je určený na odpojené a pripravené súčiastky v prípustnom meracom rozsahu.\n                        ","desc_t_html":"\n                <h3>Detailný popis produktu</h3>\n                                    <style>.okla-rich{max-width:1240px;margin:auto;padding:24px;color:#17212c;font:16px/1.75 Arial,sans-serif;background:#fff}.okla-rich *{box-sizing:border-box}.okla-rich h2,.okla-rich h3{color:#103e76;line-height:1.25;margin:0 0 20px;font-family:inherit}.okla-rich h2{font-size:32px}.okla-rich h3{font-size:28px}.okla-rich p{font-size:16px;line-height:1.75;margin:0}.okla-rich-intro{max-width:920px;margin:0 0 40px}.okla-editorial-row{display:flex;align-items:center;gap:52px;padding:30px 0;border-top:1px solid #edf0f4}.okla-editorial-reverse{flex-direction:row-reverse}.okla-editorial-copy{flex:1;min-width:0}.okla-editorial-media{flex:0 0 43%;min-width:0;margin:0}.okla-editorial-media img{display:block;width:100%;height:auto;max-width:100%;aspect-ratio:1/1;object-fit:contain;border-radius:10px}.okla-editorial-media figcaption{font-size:12px;color:#707070;margin-top:6px}@media(max-width:700px){.okla-rich{padding:16px 8px}.okla-rich h2{font-size:26px}.okla-rich h3{font-size:23px}.okla-editorial-row,.okla-editorial-reverse{flex-direction:column;gap:22px;padding:28px 0}.okla-editorial-media{width:100%;flex:auto}.okla-rich-intro{margin-bottom:24px}}</style><article class=\"okla-rich\" data-okla-content=\"94\"><header class=\"okla-rich-intro\"><h2>Univerzálny tester elektronických súčiastok</h2></header><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Identifikácia podporovaných súčiastok</h3><p>Tester pracuje s vybranými samostatnými elektronickými súčiastkami. Pripojený prvok vyhodnotí v rozsahu podporovaných režimov a výsledok zobrazí na obrazovke. Táto funkcia uľahčuje základné triedenie a orientačnú kontrolu drobných dielov.</p><p style=\"margin-top:16px\">Meracia elektronika skúma správanie prvku pripojeného k testovacím kontaktom. Podľa podporovaného vyhodnotenia priradí rozpoznaný typ a dostupné charakteristické údaje. Výsledok sa vzťahuje na pripojenú súčiastku v danom teste a poskytuje podklad na orientáciu v dieloch, ktorých označenie alebo zapojenie nie je na prvý pohľad zrejmé.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-033-function-1.jpg\" alt=\"Univerzálny tester elektronických súčiastok – Identifikácia podporovaných súčiastok\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row okla-editorial-reverse\"><div class=\"okla-editorial-copy\"><h3>Displej s výsledkom merania</h3><p>Číselné a grafické údaje na displeji prepájajú rozpoznaný typ súčiastky s dostupnými hodnotami. Výsledok je prístupný priamo na prístroji. Vlastná obrazovka a ovládací prvok vytvárajú samostatnú pomôcku na výučbu aj hobby elektroniku.</p><p style=\"margin-top:16px\">Zobrazenie spája výstup identifikácie s číselným alebo grafickým opisom podľa podporovaného typu prvku. Používateľ tak získava výsledok merania na tej istej jednotke, ku ktorej pripája súčiastku. Elektronika a obrazovka tvoria uzavretý funkčný celok na základnú kontrolu bez nadväzujúceho počítačového programu.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-033-function-2.jpg\" alt=\"Univerzálny tester elektronických súčiastok – Displej s výsledkom merania\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section><section class=\"okla-editorial-row\"><div class=\"okla-editorial-copy\"><h3>Testovacia pätica a priehľadné telo</h3><p>Páčková pätica uľahčuje pripojenie vývodov podporovaných súčiastok. Priehľadný kryt ponecháva viditeľnú dosku a súčasne drží konštrukciu prístroja pohromade. Tester je určený na odpojené a pripravené súčiastky v prípustnom meracom rozsahu.</p><p style=\"margin-top:16px\">Pätica vytvára rozoberateľné spojenie medzi vývodmi súčiastky a meracou elektronikou. Páčkový mechanizmus umožňuje vývody zaistiť bez trvalého spájkovania. Priehľadné puzdro prepája pohľad na dosku s mechanickým krytím prístroja, zatiaľ čo dostupné kontakty určujú spôsob pripojenia prvkov pre konkrétny podporovaný test.</p></div><figure class=\"okla-editorial-media\"><img src=\"https://cdn.jsdelivr.net/gh/AlexanderBurian/okla@dabba7ed57ffac78b1bc865accfa96fd3534cbf7/public/content-v94/images/OKL-033-function-3.jpg\" alt=\"Univerzálny tester elektronických súčiastok – Testovacia pätica a priehľadné telo\" width=\"1200\" height=\"1200\" loading=\"lazy\"></figure></section></article>\n                            ","params":[["Kategorie:","Měřicí technika a nářadí","Kategória:","Meracia technika a náradie"],["Kategorie:","Měřicí technika a nářadí","Kategória:","Meracia technika a náradie"],["Typ produktu:","Tester elektronických součástek","Typ produktu:","Tester elektronických súčiastok"],["Provedení:","Stolní / přenosná měřicí pomůcka","Vyhotovenie:","Stolová / prenosná meracia pomôcka"],["Zobrazení výsledku:","Digitální","Zobrazenie výsledku:","Digitálne"],["Účel:","Kontrola podporovaných součástek","Účel:","Kontrola podporovaných súčiastok"],["Typické použití:","Výuka, třídění a hobby elektronika","Typické použitie:","Výučba, triedenie a hobby elektronika"],["Příprava měření:","Odpojená součástka, vybité kondenzátory","Príprava merania:","Odpojená súčiastka, vybité kondenzátory"]],"catalog_names":{"Univerzální tester elektronických součástek":"Univerzálny tester elektronických súčiastok"},"catalog_short_cs":"Zorientujte se rychleji v podporovaných součástkách pro vlastní elektronické projekty. Univerzální tester pomáhá s jejich kontrolou a vyhodnocením v rozsahu funkcí konkrétního přístroje. Využijete ho při výuce, třídění materiálu i přípravě zapojení na pracovním stole. Důležitý je správný výběr kontaktů, práce s odpojenou součástkou a respektování měřicích limitů. Výsledky berte jako praktickou pomůcku, kterou u přesné aplikace doplníte dokumentací a případně dalším měřením. Při přípravě projektu se snadno sejde více podobně vypadajících prvků. Tester může pomoci u podporovaných typů a zjednodušit první orientaci.","catalog_short_t":"Zorientujte sa rýchlejšie v podporovaných súčiastkach pre vlastné elektronické projekty. Univerzálny tester pomáha s ich kontrolou a vyhodnotením v rozsahu funkcií konkrétneho prístroja. Využijete ho pri výučbe, triedení materiálu aj príprave zapojenia na pracovnom stole. Dôležitý je správny výber kontaktov, práca s odpojenou súčiastkou a rešpektovanie meracích limitov. Výsledky berte ako praktickú pomôcku, ktorú pri presnej aplikácii doplníte dokumentáciou a prípadne ďalším meraním. Pri príprave projektu sa ľahko nazbiera viac podobne vyzerajúcich prvkov. Tester môže pomôcť pri podporovaných typoch a zjednodušiť prvotnú orientáciu."}];
